window.__D("text/likkutei-sichot/c013",{"p":[[1301430142,"השליחות<sup data-n=\"709\">57</sup> — הרי כאן, נפסלו בעצם מלהיות שלוחי משה, כי א\"א שהם יהיו \"כמותו\" דמשה<sup data-n=\"710\">58</sup>, שמדתו מדת האמת<sup data-n=\"711\">59</sup>.\nורק יהושע וכלב שלא נתפתו ל\"עצת מרגלים\" נשארו שלוחי משה<sup data-n=\"712\">*59</sup>, וזה גופא שמרם שלא נטו מהכוונה ומטרת שליחותם, ואמרו \"טובה הארץ מאד מאד. . אל תיראו את עם הארץ כי לחמנו הם. . אל תיראום\"<sup data-n=\"713\">60</sup>, ומשום כך זכו ליכנס לארץ, ועד ש\"חיו מן האנשים ההם\" — ש\"נטלו חלקם של מרגלים בארץ וקמו תחתיהם לחיים\"<sup data-n=\"714\">61</sup>.\n<span data-k=\"q\">(משיחת ש\"פ שלח תשמ\"ה)</span>",[["709","57","רמב\"ם הל' שלוחין ושותפין פ\"א ה\"ב ואילך. שו\"ע חו\"מ סקפ\"ב ס\"ב ואילך."],["710","58","ולהעיר מגו\"א כאן (יג, ג) דזה שנעשו רשעים הי' להיותם \"שלוחיהם של רשעים. . ונעשו כמו המשלחים\". ועד\"ז באוה\"ח ריש פרשתנו."],["711","59","וי\"ל שזהו הפירוש (הפנימי) בפרש\"י חוקת (כא, לב) \"וישלח משה לרגל את יעזר — המרגלים לכדוה, אמרו לא נעשה כראשונים בטוחים אנו בכח תפלתו של משה להלחם\", דכיון שהיו בטוחים \"בכח תפלתו של משה\", שכחו של משה הי' אצלם בגלוי, לא הסתירו א\"ע כמרגלים אלא לחמו בגלוי.\nוי\"ל ע\"ד הרמז, שלכן לא העתיק רש\"י בהד\"ה תיבת \"וילכדו\" (שלכאורה זוהי הראי' שהם לכדוה) — כי עצם הענין שהיו שלוחי משה הביא לכך שלא הסתירו עצמם אלא לחמו ולכדוה."],["712","*59","להעיר מרש\"י יד, כד \"ובלבו הי' לומר האמת\"."],["713","60","פרשתנו יד, ז­ט."],["714","61","שם, לח ובפרש\"י."]]],[1301430143,"<h3>שיחה ב</h3>\nא. מזה שהמרגלים נקראו (בפרשת­נו<sup data-n=\"715\">1</sup>) בשם \"עדה\" והיו עשרה (כי יהושע וכלב לא היו בכללם), למדו חז\"ל<sup data-n=\"716\">2</sup> שכל עשרה מישראל בהצטרפם נחשבים \"עדה\"<sup data-n=\"717\">3</sup> שלמה.\nוצ\"ע<sup data-n=\"718\">4</sup> שמקור להלכה זו, במעלתה ה­מיוחדת של \"עדה\" בעניני קדושה (ש\"כל דבר שבקדושה לא יהא פחות מעשרה\"<sup data-n=\"719\">5</sup>) נלמד דוקא מהמרגלים (דכתיב בהו<sup data-n=\"715\">1</sup> \"עד מתי לעדה הרעה הזאת\")<sup data-n=\"721\">6</sup>?\nואף דדין של עדה<sup data-n=\"722\">7</sup> קדושה (ש\"אין דבר שבקדושה פחות מעשרה\") הוא שגם רשע \"מצטרף למנין עשרה לכל דבר ש­בקדושה. . (כי) ישראל אע\"פ שחטא ישראל הוא<sup data-n=\"723\">8</sup> ובקדושתו הוא עומד ולא יצא מכלל ישראל\"<sup data-n=\"724\">9</sup>, אבל לכאורה אין זה טעם מספיק, כי [נוסף ע\"ז שאת\"ל (כפי שמשמע מפשש\"מ) שהמרגלים היו בגדר מורדים בה' (כדברי כלב<sup data-n=\"725\">10</sup> \"בה' אל תמרודו\"), הרי אין זה פשוט ל­הלכה<sup data-n=\"726\">11</sup> אם אפשר לצרף \"מורדים\" ל­מנין עשרה לדבר שבקדושה, ומה גם כשכל העשרה הם \"מורדים\" — הנה] הלימוד ממרגלים ד\"עדה\" הוי עשרה — נוגע גם לדין \"עדה\" דסנהדרין<sup data-n=\"727\">12</sup> (\"ו­שפטו. . והצילו העדה גו'\"<sup data-n=\"728\">13</sup>) שהיא עשרה, שבזה פשיטא דאין רשע בכלל<sup data-n=\"729\">14</sup>.\nוי\"ל שזהו אחד מהרמזים בנגלה ד­תורה להמבואר בפנימיות התורה, שה­מרגלים היו בדרגא נעלית<sup data-n=\"730\">15</sup>. כלומר, לא",[["715","1","יד, כז."],["716","2","מגילה כג, ב (הובא בפרש\"י עה\"פ). וכן הוא לכמה גירסאות בברכות כא, ב וסנהדרין עד, ב (ראה על הגליון בש\"ס שם. וראה פרש\"י סנהדרין שם. מהרש\"א שם)."],["717","3","ראה רמב\"ם הל' תפלה פ\"ח ה\"ה. שו\"ע אדה\"ז או\"ח סנ\"ה ס\"ב."],["718","4","ראה ספר השיחות תש\"ד ע' 29."],["719","5","ברכות ומגילה שם — דאתיא תוך (אמור כב, לב) תוך (קרח טז, כא).\nבס' השיחות שם הובא \"הבדלו מתוך העדה הרעה הזאת\" — כנראה ט\"ס, ותיבת הרעה מיותרת. או שהכוונה שם להעתיק ב' הפסוקים (גם הפסוק דפרשתנו, וכבגמ' שם), וכסיום הלשון בס' השיחות שם שעדה פי' עשרה."],["715","1","יד, כז."],["721","6","ולהעיר דבירושלמי סנהדרין פ\"א ה\"ד (ועד\"ז בירושלמי ברכות פ\"ז ה\"ג) ישנה דיעה דה­לימוד הוא מהכתוב (מקץ מב, ה) ויבואו בני ישראל לשבר בתוך הבאים."],["722","7","להעיר משו\"ע אדה\"ז שם: ועדה זו צריך להיות כולה מזכרים בני חורין גדולים. . וכמו שהיתה עדה האמורה להלן אבל נשים ועבדים וקטנים אינן מצטרפין."],["723","8","סנהדרין מד, רע\"א."],["724","9","שו\"ע אדה\"ז שם סי\"ד (מב\"י שם (ד\"ה כתב בס') בשם ס' המנהיג סי' עט). וראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310006\" data-slug=\"tanya\" data-id=\"3401310006\">תניא</a> ספ\"א. אגה\"ק סכ\"ג (קלו, ב). סה\"מ תקס\"ה ח\"ב ע' תתקסד. ועוד."],["725","10","יד, ט. וזה אמר לכל עדת בני ישראל (שם, ז), ופשיטא למרגלים שע\"פ פשש\"מ (וראה רש\"י שם יד, כז) היו לא רק חוטאים בעצמם אלא גם מחטיאי הרבים."],["726","11","ראה ב\"י שם מהרשב\"א. פמ\"ג (א\"א) שם סק\"י. ועוד."],["727","12","משנה סנהדרין פ\"א (ב, סע\"א)."],["728","13","מסעי לה, כד­כה."],["729","14","אף שיש לחלק דבזה שאני שאינו בכלל — לא מפני שאינו ב\"עדה\" אלא מפני שאינו ב­\"סנהדרין\"."],["730","15","להעיר ממחז\"ל שטן ופנינה לש\"ש נתכוונו (ב\"ב טז, א)."]]],[1301430144,"זו בלבד שלא היתה כוונתם ח\"ו מרידה כפשוטה, אלא אדרבה, \"היו במדריגה גבוה מאד\"<sup data-n=\"731\">16</sup>, וכדלקמן בארוכה.\n[וכמשנ\"ת בכ\"מ שנגלה דתורה ופני­מיות התורה הם תורה אחת, ולכן, אף שכל חלק יש לו גדרים וכללים משלו וע\"ד שאין למדים הלכה מאגדה<sup data-n=\"732\">17</sup> — מ\"מ, מכיון שבעצם ה\"ה תורה אחת, מובן שיש ביניהם שייכות, קשר ועד — לאי­חוד (ועד, שהם גוף ונשמה זל\"ז כדאיתא בזהר<sup data-n=\"733\">18</sup>), וגם הענינים שבפנימיות התורה שלפום ריהטא אינם מתאימים עם הפשט וההלכה יש להם יסוד ומקור בנגלה דתורה<sup data-n=\"734\">19</sup>, אם ברמז או בפירוש.\nוכן בעניננו, דעם היות שע\"פ פשש\"מ (ונגלה דתורה בכלל) חטאו המרגלים ב­חטא חמור ובגללו נענשו הם עצמם ועל ידם כל דור המדבר כו' — מ\"מ צריך לומר שגם בנגלה דתורה יש רמז עכ\"פ על מעלת המרגלים המבוארת בפנימיות התורה].\nב. בתורת החסידות (פנימיות התורה) מבואר<sup data-n=\"735\">20</sup>, דזה שלא רצו המרגלים ליכנס לא\"י הי' מצד גודל מעלתם<sup data-n=\"736\">21</sup> בעבודת ה': לא רצו להכנס לא\"י משום שמאנו ל­השפיל את עצמם בסדר החיים של \"שש שנים תזרע שדך גו'\"<sup data-n=\"737\">22</sup>, להתעסק ב­ענינים גשמיים וחומריים, וע\"ד מאמר רשב\"י<sup data-n=\"738\">23</sup> \"אפשר אדם חורש כו' וזורע כו' תורה מה תהא עלי'\". כל רצונם ו­חפצם הי' (כהמשך למ\"ת) להשאר בהת­בודדות במדבר, מנותקים מחיי ישוב, בלא טרדות הפרנסה וכו' (כי השם סיפק צרכיהם במדבר ע\"י המן, לחם מן ה­שמים<sup data-n=\"739\">24</sup>, והמים מבארה של מרים<sup data-n=\"740\">25</sup>, וע\"י ענני הכבוד שליוו אותם והרגו את ה­נחשים והעקרבים וגיהצו בגדיהם<sup data-n=\"741\">26</sup> ו­כו'), והרי זוהי הדרך האמיתית ללמוד תורה ולהיות דבוק בה', וכמאמר רז\"ל<sup data-n=\"742\">27</sup> לא ניתנה תורה (לדרוש) אלא לאוכלי המן.\n[אלא שטעו בזה, כי יש מעלה גדולה יותר בעבודה שבסדר החיים בא\"י, קיום המצות התלויות בארץ, ומצות מעשיות בכלל, אפילו לגבי מעלת הדביקות וכו' שבמדבר].\nועפ\"ז י\"ל, שבענין הנ\"ל — שדוקא מ­ה\"עדה\" דמרגלים ילפינן שעשרה מישר­אל נחשבים \"עדה\" קדושה — מרומז ש­חטאם של המרגלים לא הי' במובנו ה­פשוט, אלא שטעו בחשבם שהדרך (הנ\"ל) שבחרו בה היא הדרך העיקרית בעבודת ה'<sup data-n=\"743\">28</sup>,",[["731","16","לקו\"ת פרשתנו לו, סע\"ד."],["732","17","ירושלמי פאה פ\"ב ה\"ד (וראה אנציקלו­פדיא תלמודית ערך אגדה. וש\"נ). ויתרה מזה בהלכה עצמה — ממונא מאיסורא לא ילפינן (ברכות יט, ב וש\"נ) וכיו\"ב."],["733","18","ח\"ג קנב, א."],["734","19","וראה דרמ\"צ ה, א (ועד\"ז כב, א): וגם הגליא הוא כפי הסתים כגוף לנפש."],["735","20","לקו\"ת פרשתנו (לז, ב. לח, ב) מספרי קבלה. אוה\"ת שם (ס\"ע תמג ואילך. ס\"ע תנה ואילך). ובכ\"מ."],["736","21","ראה לקו\"ת ריש פרשתנו."],["737","22","בהר כה, ג."],["738","23","ברכות לה, ב."],["739","24","בשלח טז, ד ואילך."],["740","25","פרש\"י חוקת כ, ב."],["741","26","פרש\"י בהעלותך יוד, לד. עקב ח, ד."],["742","27","מכילתא בשלח טז, ד."],["743","28","ולהעיר דאף שבמשנה (סנהדרין קח, א) אי' שמרגלים אין להם חלק לעוה\"ב, משמע בזהר ח\"ג (רע\"מ) רעו, א שיש להם חלק לעוה\"ב. וידוע הפי' בס' עשרה מאמרות (מאמר חקו\"ד ח\"ב פ\"ח) ובכ\"מ — בדעת רע\"ק (סנהדרין שם) \"דור המדבר אין להם חלק לעוה\"ב\", כי אין להם צורך בעוה\"ב, ואדרבא הם למעלה מזה (וראה לקוטי לוי\"צ אגרות ע' שנח ואילך). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300231102\" data-slug=\"likkutei-sichot\" data-id=\"1300231102\">לקו\"ש חכ\"ג ע' 102</a>. וש\"נ.\nולהעיר מתפלת (ופירוש) אדה\"ז עה\"פ: מי לי בשמים — זע איך וויל נישט כו' (שורש מצות התפלה — בסהמ\"צ להצ\"צ פ\"מ)."]]],[1301430145,"אלא שמצד גודל מעלתם ודרגתם ב­עבודת ה'\nועוד (וי\"ל שזהו עיקר) השתדלותם להשפיע על בנ\"י בזה\n— ה\"ז חטא גדול וחמור.\nג. ויתר על כן יש לומר, דזה ששו­רש הנהגת המרגלים הוא דבר שבקדו­שה, נרמז ונלמד גם מזה שאנשי דור המדבר נשארו במדבר ארבעים<sup data-n=\"744\">29</sup> שנה, ולא חיו חיי צער וטרדות, אלא אדרבה, חיי מנוחה, שכל מ' שנה הי' להם המן למזון, ומים מבארה של מרים וכו', וענני הכבוד הגינו בעדם וכו' (כנ\"ל).\nדלכאורה: הרי זה היתה טענתם ו­רצונם של (המרגלים ו)דור המדבר ל­השאר במדבר ולא להכנס לא\"י — ואיך מתאים שנתמלא מבוקשם ונשארו במד­בר במנוחה וענן ה' עליהם יומם ולילה כו'?\n[ועוד זאת: ע\"פ הידוע<sup data-n=\"745\">30</sup> שעונשי ה­תורה ענינם לתקן פגמו של החטא, ועד שיהי' המצב — הפך מענין החטא — יפלא ביותר, שבנדו\"ד לא שללו רצונם ולא תיקנו ושללו חטאם (כניסה לארץ) אלא היתה ההנהגה אתם כפי שרצו, שנשאר כל הדור ההוא — כל שנותיו במדבר! וגם את\"ל שמצד חטאם לא היו ראויים להכנס לא\"י (דמכיון שמאסו בא\"י לכן לא זכו להכנס אלי') — מ\"מ מהי ההסברה שהעונש יהי' להשאר ב­מדבר בחיי מנוחה כו' בתוך ענני הכבוד, ומשה ואהרן בראשם וכו'?]\nוע\"פ הביאור הנ\"ל (בפנימיות התורה) י\"ל הטעם בדבר, כי המעלה הרוחנית שבמדבר (שהיא כוונתם, ולש\"ש<sup data-n=\"746\">31</sup>) אינה טעות (אלא שבא עי\"ז ונסתעף מזה ל­מעשה דבר טעות),\nכלומר, הישיבה במדבר בתוך ענני הכבוד וכו' כשלעצמה יש בה קדושה, אלא שהם חשבו שזוהי התכלית הסופית, אף שמעלה זו היא (צ\"ל) הכנה לכניסה לא\"י, כי כדי להגיע לשלב הנעלה של כניסה לא\"י, מוכרחת ההכנה וההכשרה שעל ידי שהייתם במדבר מ' שנה.\nד. וילה\"ק בירור בדברי הרמב\"ם ב­הל' תשובה, שעל פיו אפשר להסביר ביאור זה (שבפנימיות התורה) — בסגנון ההלכה:\nבפ\"י מהל' תשובה כ' הרמב\"ם<sup data-n=\"747\">*31</sup>: אל יאמר אדם הריני עושה מצות התורה ו­עוסק בחכמתה כדי שאקבל כל הברכות הכתובות בה או כדי שאזכה לחיי ה­עוה\"ב ואפרוש מן העבירות שהזהירה תורה מהן כדי שאנצל מן הקללות הכתובות בתורה או כדי שלא אכרת מחיי העוה\"ב אין ראוי לעבוד את ה' על הדרך הזה שהעובד על דרך זה הוא עובד מיראה ואינה מעלת הנביאים ולא מעלת החכמים ואין עובדים ה' על דרך זה אלא עמי הארץ והנשים והקטנים שמחנכין אותן לעבוד מיראה עד שתרבה דעתן ויעבדו מאהבה.\nובפרק שלפנ\"ז<sup data-n=\"748\">32</sup> כתב \"ומפני זה נת­",[["744","29","כהלשון בזה בכ\"מ (בתושב\"כ ובתושבע\"פ) אף שבפועל הי' פחות מל\"ט שנה. וראה פרש\"י (פרשתנו יד, לג)."],["745","30","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300231098\" data-slug=\"likkutei-sichot\" data-id=\"1300231098\">לקו\"ש שם ע' 98</a> ואילך. וש\"נ."],["746","31","ראה לעיל הערה 15."],["747","*31","ה\"א."],["748","32","פ\"ט ה\"ב."]]],[1301430146,"אוו כל ישראל נביאיהם וחכמיהם ל­ימות המשיח כדי שינוחו ממלכיות שאינן מניחות להן לעסוק בתורה ובמצות כהוגן וימצאו להם מרגוע וירבו בחכמה כדי שיזכו לחיי העולם הבא\".\nולכאורה צריך ביאור: איך אפ\"ל ב­פ\"י ש\"אין ראוי לעבוד את ה' על הדרך הזה. . ואינה מעלת הנביאים ולא מעלת החכמים\", והרי לפנ\"ז כותב בפירוש<sup data-n=\"749\">33</sup> שזו<sup data-n=\"750\">34</sup> דרך הנביאים והחכמים (שלכן \"נתאוו כל ישראל נביאיהם וחכמיהם ל­ימות המשיח\"), הרי שזוהי כן מעלת הנביאים והחכמים<sup data-n=\"751\">35</sup>?\nבפשטות י\"ל שב' ענינים הם: בפ\"ט לא קאי באופן קיום התומ\"צ, כ\"א ב­ביאור תוכן ומהות שכר המצות שבחיי עוה\"ב<sup data-n=\"752\">36</sup>, שהם \"סוף כל השכר כולו וה­טובה האחרונה שאין לה הפסק וג­רעון\"<sup data-n=\"753\">37</sup>. ולכן \"התאוו לה כל הנביאים\"<sup data-n=\"754\">38</sup>, ו\"כמה כפּמה דוד והתאוה לחיי העולם הבא\"<sup data-n=\"755\">39</sup>, ומטעם זה ג\"כ נתאוו כל ישראל נביאיהם וחכמיהם (למצב זה בעולם<sup data-n=\"756\">40</sup>) לימות המשיח כי דוקא עי\"ז (יוכלו לעסוק בתורה ובמצות כהוגן ו)יזכו לחיי עולם הבא.\nמשא\"כ בפ\"י מבאר הרמב\"ם האופן הרצוי בקיום התומ\"צ, שכוונת עסק ה­תומ\"צ לא תהי' בשביל לזכות לחיי עוה\"ב אלא מאהבה. ונמצא, דאף שצ\"ל התאוה לחיי עוה\"ב אין זה מטרת קיום התומ\"צ<sup data-n=\"757\">41</sup>, אלא ענין בפ\"ע<sup data-n=\"758\">42</sup>.\nאבל חילוק זה לכאורה דחוק הוא, כי מהלשון \"(וימצאו להם מרגוע) וירבו בחכמה כדי שיזכו לחיי העולם הבא\" משמע, דסו\"ס מחשבתם וכוונתם (אף שלא בשעת קיום המצות) היא שעסק התומ\"צ הוא כדי לזכות לחיי העולם הבא.\nה. להלן בפ\"י ממשיך הרמב\"ם (ב­הלכה בפ\"ע): העובד מאהבה עוסק ב­תורה ובמצות והולך בנתיבות החכמה לא מפני דבר בעולם ולא מפני יראת הרעה ולא כדי לירש הטובה אלא עושה האמת<sup data-n=\"759\">43</sup> מפני שהוא אמת וסוף הטובה לבא בגללה ומעלה זו היא מעלה גדולה מאד ואין כל חכם זוכה לה והיא מעלת אברהם אבינו שקראו הקב\"ה אוהבו לפי שלא עבד אלא מאהבה.",[["749","33","וכ\"כ בהל' מלכים פי\"ב ה\"ד."],["750","34","משא\"כ מש\"כ \"כדי שנזכה לחיי העולם הבא\" בהל' תשובה פ\"ט ה\"א שם, שקאי ע\"ז שהקב\"ה משפיע לנו הטובות כו' \"כדי שלא נעסוק כל ימינו כו' אלא נשב פנויים ללמוד בחכמה ולעשות המצוה כדי שנזכה לחיי העולם הבא\", היינו שזוהי כוונת פעולת הקב\"ה, לא \"תאוות\" וכוונת האדם. ועד\"ז מש\"כ \"כדי שתזכו לחיי העוה\"ב\" דלקמן הל' תשובה שם."],["751","35","כן הקשה גם בהגהות עמק מלך על הרמב\"ם הל' מלכים שם."],["752","36","והוא ההמשך והסיום למה שהתחיל בפרק ח ע\"ד \"הטובה הצפונה לצדיקים\" היא חיי העוה\"ב."],["753","37","ל' הרמב\"ם שם פ\"ט ה\"ב."],["754","38","שם פ\"ח ה\"ג בסופה."],["755","39","שם ריש הלכה ז."],["756","40","כתוכן כו\"כ תפלות בנ\"י: תפלת (נדר) יעקב (ר\"פ ויצא) ועוד."],["757","41","וכן צריך לפרש במ\"ש הרמב\"ם שם רפ\"ז: ישתדל אדם לעשות תשובה כו' כדי. . (ש)יזכה לחיי העולם הבא."],["758","42","כמ\"ש הרמב\"ם בפיהמ\"ש סנהדרין הקדמה לפ' חלק (סד\"ה ועתה אחל): והתכלית הוא העוה\"ב ולעומתו הוא ההשתדלות כו' ועם היותו הוא התכלית המבוקש אינו ראוי למי שהוא רוצה שיהי' עובד מאהבה שיהי' עובד להשיג העוה\"ב כו'."],["759","43","וצ\"ע ענין האמת כאן.\nולהעיר מתחלת ס' הרמב\"ם פ\"א ה\"ד: הוא לבדו האמת\nאף שבפשטות הכוונה לאמתית מציאותו."]]],[1301430147,"וצריך ביאור, דלכאורה גם כאן סו­תר דברי עצמו: בה\"א כתב שהעבודה מיראה היא דרך עמי הארץ והנשים וה­קטנים \"ואינה מעלת הנביאים. . (ו)ה­חכמים\", היינו שעבודתם ומעלתם של החכמים והנביאים היא עבודה מאהבה; ובה\"ב כתב על העבודה מאהבה ד\"מעלה זו היא מעלה גדולה מאד ואין כל חכם זוכה לה\", הרי שאין זו מעלת (כל) ה­נביאים וכל החכמים.\nויתירה מזו: בה\"א מסיים דגם עמי הארץ וכו' שעובדים מיראה \"מחנכין אותן לעבוד מיראה עד שתרבה דעתן ויעבדו מאהבה\", הרי דעבודה מאהבה שייכת לכאו\"א, ובה\"ב מפורש ד\"מעלה זו היא מעלה גדולה מאד ואין כל חכם<sup data-n=\"760\">44</sup> (אפילו) זוכה לה\".\nו. לכן נראה לומר, שעסק התומ\"צ \"כדי שיזכו לחיי עוה\"ב\" שבפ\"ט, אין פירושו כדי לקבל השכר דעוה\"ב, אלא כדי להגיע להמשך עסק התומ\"צ באופן שהוא בעוה\"ב<sup data-n=\"761\">45</sup>.\nביאור הדבר: באהבת ה' ממשיך ה­רמב\"ם<sup data-n=\"762\">46</sup> \"וכיצד היא האהבה הראוי' הוא שיאהב את ה' אהבה גדולה יתירה עזה מאוד עד שתהא נפשו קשורה באהבת ה' ונמצא שוגה בה תמיד. . (ובסוף ה­פרק<sup data-n=\"763\">47</sup>:) דבר ידוע וברור שאין אהבת הקב\"ה נקשרת בלבו של אדם עד ש­ישגה בה תמיד<sup data-n=\"764\">48</sup> כו' אינו אוהב הקב\"ה אלא בדעת שידעהו כו' לפיכך צריך האדם ליחד עצמו להבין ולהשכיל ב­חכמות ותבונות המודיעים לו את קונו כו'\".\nהיינו, דגדר האהבה לה' הוא מה ש­נפשו (ודעתו) קשורה בה' — ד(שלימות) ענין זה הוא בעוה\"ב, וכמו שכ' הרמב\"ם בפ\"ח<sup data-n=\"765\">49</sup> ע\"ד עוה\"ב ד\"צדיקים יושבים ועטרותיהם בראשיהן ונהנין מזיו השכי­נה. . (ופי') עטרותיהן בראשיהן כלומר דעת שידעו שבגללה זכו לחיי העוה\"ב מצוי' עמהן והיא העטרה. . (ו)נהנין מזיו שכינה שיודעים ומשיגין מאמתת הקב\"ה מה שאינם יודעים והם בגוף האפל השפל\". ולכן כ' הרמב\"ם<sup data-n=\"766\">50</sup> ש\"זהו השכר שאין שכר למעלה ממנו והטובה שאין אחרי' טובה\".\nוביחד עם זה אין להם מנוחה (היפך ד\"יושבים\" ו\"נהנין\")<sup data-n=\"767\">*50</sup>\nהיינו שחיי עוה\"ב אינם (רק) \"שכר\" על עסק התומ\"צ אלא המשך ועלי' והתקרבות תמידית לשלימות הדביקות בה' שע\"י התומ\"צ.\nועפ\"ז יובן החילוק בין מ\"ש הרמב\"ם ברפ\"י \"אל יאמר אדם הריני עושה מצות התורה ועוסק בחכמתה כדי שאקבל כל",[["760","44","להגירסא בכמה כת\"י \"אדם\" (במקום \"חכם\") — ראה ספר המדע (ירושלים, תשכ\"ד) — מתורץ (וראה פיהמ\"ש שם ד\"ה וכת החמישית קרוב לסופה: שזה הענין קשה מאוד ואין כל אדם משיג אותו). אבל ברוב כת\"י ודפוסים איתא \"חכם\" (כבפנים)."],["761","45","ומהנפק\"מ למעשה — שההמשך בענין מעורר ומזרז לעלי' עוד יותר וכמרז\"ל מי שיש לו מנה רוצה מאתים מאתים רוצה ד' מאות (קה\"ר פ\"א, יג), ואין לו מנוחה, משא\"כ בקבלת שכר — עלול להיות שמח בחלקו וזאת מנוחתו."],["762","46","פ\"י ה\"ג."],["763","47","פ\"י ה\"ו."],["764","48","וי\"ל דבה\"ג מדובר כאשר כבר הגיע אהבה בלבו \"אהבת ה' בלב אוהביו שוגים בה תמיד\". ובה\"ו מדובר \"שישגה בה תמיד\" בדעתו בכדי להגיע לאהבת ה' בלבו."],["765","49","ה\"ב."],["766","50","שם סה\"ג. ועד\"ז בכ\"מ בפ\"ח וסוף פ\"ט."],["767","*50","ראה הערה 45."]]],[1301430148,"הברכות הכתובות בה או כדי שאזכה לחיי העוה\"ב\", למ\"ש בפ\"ט דזה ש\"נתאוו כל ישראל נביאיהם וחכמיהם לימות ה­משיח (הוא) כדי שינוחו ממלכיות שאינן מניחות להן לעסוק בתורה ובמצות כ­הוגן וימצאו להן מרגוע וירבו בחכמה כדי שיזכו לחיי העוה\"ב\":\nמש\"כ \"נתאוו כל ישראל נביאיהם ו­חכמיהם לימות המשיח כדי שינוחו מ­מלכיות כו' וירבו בחכמה כדי שיזכו לחיי העולם הבא\", אין רצונו לומר שהמטרה \"כדי לזכות לחיי עוה\"ב\" היא (ע\"מ לקבל) פרס, קבלת שכר על עבודתם, אלא כדי לזכות לתכליתה ושלימותה של האהבה והדביקות בה' (שמדבר לפנ\"ז)<sup data-n=\"768\">51</sup>, לשגות בה תמיד שזהו ע\"י שירבו ויוסיפו תמיד בחכמה בימות המשיח.\nמשא\"כ בפ\"י, שבו שולל הרמב\"ם עשיית מצות התורה כו' בכוונה לזכות לחיי העוה\"ב כקבלת שכר<sup data-n=\"769\">52</sup> על עבודתו, שלכן כללו הרמב\"ם בין שאר עניני תו­עלת ושכר דעבודתו — \"כדי שאקבל כל הברכות הכתובות בה. . כדי שאנצל כו'\". ומכיון שכוונתו אינה להעלי' ל­שלימות העבודה אלא לקבלת שכר<sup data-n=\"769\">52</sup>, לכן ההלכה \"אל יאמר אדם כו'\".\n[אלא שבזה גופא ישנם שני אופנים:\nבמ\"ש בריש פ\"י \"אל יאמר אדם כו' כדי שאקבל כל הברכות כו' או כדי שאזכה לחיי העולם הבא ואפרוש מן העבירות כו' כדי שאנצל מן הקללות כו' או כדי שלא אכרת מחיי העולם הבא\" כוונת הרמב\"ם לשלול העבודה מיראה, כלומר, שכוונת האדם העובד היא מפני שירא לחיי נפשו<sup data-n=\"771\">53</sup>, ולכן עובד ה' כדי שיהיו לו חיי מנוחה בעוה\"ז (וינצל מן הקללות כו'), או (במי שנוגעים לו חיי נפשו) כדי שתזכה נפשו לחיים נצחיים דעוה\"ב (ולא יכרת מחיי עולם הבא);\nולהלן בהלכה ד כותב הרמב\"ם \"אמ­רו חכמים הראשונים שמא תאמר הריני למד תורה בשביל שאהי' עשיר כו' בשביל שאקבל שכר בעולם<sup data-n=\"772\">54</sup> הבא ת\"ל לאהבה כו'\" — היינו שהכוונה שלו \"לקבל שכר\" היא (לא משום שירא לחיי נפשו, אלא) מפני שרוצה לקבל גמול ותשלום עבור עבודתו (תשלום גשמי — \"שאהי' עשיר\", או תשלום רוחני — \"ש­אקבל שכר בעולם הבא\"), שזוהי דרגא פחותה יותר בעובד ה' שלא לשמה<sup data-n=\"773\">55</sup>].\nז. אמנם אע\"פ שזה שהחכמים וה­נביאים נתאוו לזכות לחיי עולם הבא הוא המשך ועלי' יותר בעבודתם מאהבה — ישנה מדריגה נעלית יותר בעבודה מאהבה ש\"אין כל חכם זוכה לה\". וזהו מה שמחדש הרמב\"ם בהלכה ב<sup data-n=\"774\">56</sup> ע\"ד",[["768","51","ראה עבודת הקודש ח\"ב פ\"ה בשם החכם רבי יוסף. אבל שם לא כתב כן בדעת הרמב\"ם (וראה שם פירושו בדעת הרמב\"ם). וראה גם של\"ה (מז, א ואילך ושם מט, ב בהגהה בדעת הרמב\"ם)."],["769","52","וי\"ל דבכללות גם זה נקרא \"קבלת שכר\", אף שבפרטיות כפי המבואר ברמב\"ם שם ה\"ז נקרא \"עובד מיראה\" ולא \"קבלת שכר\", כדלקמן בפנים."],["769","52","וי\"ל דבכללות גם זה נקרא \"קבלת שכר\", אף שבפרטיות כפי המבואר ברמב\"ם שם ה\"ז נקרא \"עובד מיראה\" ולא \"קבלת שכר\", כדלקמן בפנים."],["771","53","או בלשונו בה\"ה \"שלא תגיע עליו פורענות\"."],["772","54","והיינו שאין כוונתו לזכות לחיי עוה\"ב (שהם המטרה של קיום התומ\"צ, \"סוף מתן שכרן של מצות\") — וכלשון הרמב\"ם בה\"א \"כדי שאזכה לחיי העולם הבא\" — אלא שרוצה לקבל שכר צדדי (לפי השגתו), ע\"ד \"בשביל שאהי' עשיר. . שאקרא רבי\", אלא שמקום קבלת שכר זה הוא \"בעוה\"ב\"."],["773","55","ולהעיר משינוי לשון הרמב\"ם — שבה\"א כ' \"כדי שאקבל הברכות כו' כדי שאזכה כו'\", ובה\"ד משנה וכ' \"בשביל שאהי' עשיר כו' בשביל שאקבל שכר בעוה\"ב\" (שמשמעו בשביל ענין אחר)."],["774","56","פשטות ל' הרמב\"ם בה\"ב \"העובד מאהבה עוסק בתומ\"צ כו'\" קאי בכללות במדריגת אהבה סתם. אלא י\"ל שבדיוק לשונו כולל מדריגה נעלית יותר באהבה."]]],[1301430149,"\"מעלת אברהם אבינו\" ש\"עושה האמת מפני שהוא אמת\".\nוי\"ל שמהיתרון בזה הוא:\nכאשר העבודה היא מאהבה סתם (ש­ישנה אצל כל ישראל (ועאכו\"כ) נביאי­הם וחכמיהם), הרי עסק התומ\"צ הוא בכדי להגיע להתקשרות ודביקות ב­הקב\"ה, ונמצא שהעסק בתומ\"צ הוא ב­אופן שאין העסק בשביל ולשם עצמו אלא בשביל מבוקש, שהוא כעין דבר נוסף; אבל כאשר העבודה מאהבה היא באופן ש\"עושה האמת מפני שהוא אמת\", הרי זה שולל לא רק העבודה בשביל קבלת שכר, אלא שאין מבוקש אחר בעבודתו, גם לא המבוקש שיתדבק בהקב\"ה שהוא התוכן דידיעת ה' ואהבת ה', כ\"א \"עושה האמת מפני שהוא אמת\", להיותו ציווי ורצון ה', שקיום ציווי ה' הוא אמת מצד עצמו.\nועל מעלה זו כתב הרמב\"ם \"ומעלה זו היא מעלה גדולה מאוד\", (ולא כמ\"ש בהלכה שלפנ\"ז סתם \"מעלת הנביאים\", \"מעלת החכמים\") — כי על מעלה זו אין לומר שהיא מעלת כל החכמים, ואדרבא כפי שממשיך \"ואין כל חכם זוכה לה\", אלא \"היא מעלת אברהם אבינו שקראו הקב\"ה אוהבו\", שכדי להגיע למעלה גדולה זו (\"עושה האמת מפני שהוא אמת\") צריך לעלות לדרגא נעלית מאד באהבה.\nח. וע\"פ כל הנ\"ל יש להסביר גם ב­נוגע למרגלים ודור המדבר:\nהמרגלים (ודור המדבר בכלל) היו כנ\"ל \"במדריגה גבוה מאד\", \"ולא רצו להשפיל א\"ע\"<sup data-n=\"775\">57</sup> להכנס לא\"י, בסדר ה­עבודה דשש שנים תזרע שדך גו', אדם חורש אדם זורע (כנ\"ל ס\"ב), משום ש­סדר עבודה זה אינו מניח להם לעסוק בתורה כו' \"כהוגן\", שהרי רוב ימיהם יהיו עסוקים \"בדברים שהגוף צריך להן\"<sup data-n=\"776\">58</sup>, והם רצו להשאר ולהמשיך ו­לנסוע ולעלות<sup data-n=\"777\">59</sup> בסדר החיים דמדבר, שהטובה מושפעת הרבה<sup data-n=\"778\">60</sup> כנ\"ל (מן מן השמים, מים מבארה של מרים, וענני הכבוד שהלכו עמהם, כנ\"ל) — ולא היו שום בלבולים בעבודת ה', ויכלו לישב פנויים למצוא להם מרגוע ולהרבות בחכמה לזכות לחיי עוה\"ב. וע\"ד מה ש\"נתאוו כל ישראל נביאיהם וחכמיהם כו' כדי שינוחו כו' וימצאו להם מרגוע כו'\".\nאבל אף שרצונם ותאוותם לכהנ\"ל ב­מדבר היא דרגא נעלית בדביקות בה'<sup data-n=\"779\">*60</sup>, עבודה מאהבה, מ\"מ הכניסה לא\"י מבי­אה לדרגא נעלית יותר, והוא קיום ציווי ה' בלי שום מבוקש כלל, \"עושה האמת מפני שהוא אמת\".\nאלא שכדי להגיע לדרגא זו דרושה אהבה נעלית עוד יותר, ומכיון שהמרג­לים ודור המדבר רצו להשאר במדבר ולא רצו להכנס לארץ, הרי זאת אומרת שעדיין לא הגיעו לדרגא זו דשלימות הדביקות והעלי' דאהבה.\nולכן נשארו בנ\"י במדבר במצב ד­העדר כל הדברים המונעים מלימוד התורה ודביקות בה' בתכלית, אופן ד­",[["775","57","לקו\"ת פרשתנו לז, רע\"א."],["776","58","רמב\"ם שם פ\"ט ה\"א."],["777","59","דפשיטא שצ\"ל מעלין בקודש."],["778","60","ראה רמב\"ם שם ובסוף הל' מלכים."],["779","*60","להעיר מ<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380845\" data-slug=\"likkutei-torah\" data-id=\"4001380845\">לקו\"ת ראה לב, ג</a> בפי' (פרשתנו יד, לה) במדבר הזה יתמו גו' (ע\"פ זהר פרשתנו קסג, ב)."]]],[1301430150,"מנוחה ומרגוע בכדי \"שירבו בחכמה\", שעי\"ז הגיעו לשלימות דביקות הנפש כו'<sup data-n=\"780\">61</sup>. ולאחרי זה, בדור הבא, בדור ו­דרגא חדשה, נכנסו לא\"י לקיים ציווי ה', הן בעצם הכניסה והן בקיום המצות מעשיות שבארץ, שדוקא בזה נרגש ענין \"עושה האמת מפני שהוא אמת\".\nוי\"ל שזהו גם תוכן דברי יהושע ו­כלב במענה אל כל עדת בנ\"י<sup data-n=\"781\">*61</sup> \"אם חפץ בנו ה' והביא אותנו גו'\" — שהכ­ניסה לארץ קשורה עם \"חפץ בנו<sup data-n=\"782\">62</sup> ה'\", זהו חפץ ורצון ה', ובמילא בקיומו מתג­לה \"חפץ בנו ה'\", דביקות בנ\"י בה' ב­אופן נעלה יותר מהדביקות שע\"י \"ירבו בחכמה\" שבמדבר.\nט. והנה הרמב\"ם בדברו על זה ש­\"עושה האמת מפני שהוא אמת\" מסיים \"וסוף הטובה לבוא בגללה\". ולכאורה מה ענין סיום זה לכאן — הרי מדובר בחכם כזה שאינו חושב כלל על הטובה שמגיע לו מעבודתו.\nויש לומר, שזה מובן מדיוק לשון הרמב\"ם \"וסוף הטובה לבוא בגללה\"<sup data-n=\"783\">63</sup>, והיינו דכאשר עבודתו היא באופן כזה ש\"עושה האמת מפני שהוא אמת\", אזי גם הטובה הבאה היא נעלית יותר<sup data-n=\"784\">64</sup> מטובת עוה\"ב ע\"ד הרגיל<sup data-n=\"785\">65</sup>, ובמילא גם מצד ענין ההתקשרות ודביקות נפשו בה' ה\"ה מגיע לשלימות נעלית יותר<sup data-n=\"786\">66</sup> בזה — ממי שלימוד התורה וקיום המצות שלו הוא באופן שיש לו מבוקש של התקשרות ודביקות בה'.\nועפ\"ז יש לבאר המשך דברי יהושע וכלב, שאמרו (לפנ\"ז<sup data-n=\"787\">67</sup>) \"טובה הארץ מאד מאד\"<sup data-n=\"788\">68</sup>, אף שע\"י אופן העבודה ב­מדבר, לימוד התורה באופן שהיו פנויים בחכמה, זוכים \"לראות<sup data-n=\"789\">69</sup> בטוב ה' ב­ארץ<sup data-n=\"790\">70</sup> חיים\" — עוה\"ב שהוא \"טובה גדו­לה עד מאד ואין לה ערך בטובות ה­עוה\"ז\", אשר \"אותה הטובה גדולה עד אין חקר ואין לה ערך ודמיון הוא שאמר",[["780","61","ועפ\"ז יש לבאר גם להפירוש דהעשרה מאמרות (הנ\"ל הערה 28) דדור המדבר אין להם צורך לעוה\"ב, אף שנת\"ל שרצונם ותאוותם להשאר במדבר הוא בדוגמת \"נתאוו כל ישראל כו' כדי שיזכו לחיי העוה\"ב\" — כי ע\"י היותם במדבר מ' שנה בפועל, שנסעו ונתעלו מחיל אל חיל עד שהגיעו למעלה עליונה יותר בהיותם למטה נשמה בגוף, הרי דרגת חיי עוה\"ב לנשמות (ע\"ד הרגיל) ש\"צדיקים יושבים. . ונהנין כו'\" (רמב\"ם הל' תשובה פ\"ח ה\"ב) הוא השפלה וירידה לגביהם ואין להם צורך לזה (ולהעיר משער מאמרי רז\"ל לר\"פ חלק בחילוקי דרגות בעוה\"ב. ואכ\"מ) — משיחת ש\"פ שלח תשמ\"ז."],["781","*61","פרשתנו יד, ח. וראה לקו\"ת פרשתנו לח, ג."],["782","62","להעיר מתורת הבעש\"ט עה\"פ כי תהיו אתם ארץ חפץ (\"היום יום\" י\"ז אייר. כתר שם טוב (הוצאת קה\"ת) הוספות סמ\"ד. וש\"נ)."],["783","63","בכמה גי' \"בכללה\" (ראה רמב\"ם ספר המדע שם)."],["784","64","משא\"כ בנדרים סב, א: למוד מאהבה וסוף הכבוד לבוא (ותו לא)."],["785","65","משא\"כ בנדרים שם שאין מדובר בטובת עוה\"ב וכיו\"ב כ\"א שלא יאמר אדם אקרא שיקראוני חכם אשנה שיקראוני רבי כו' (שכ' הרמב\"ם בפ\"י ה\"ד), וע\"ז מסיים: סוף הכבוד לבוא."],["786","66","כמ\"ש הרמב\"ם שם (פ\"ט ה\"א) לענין עוה\"ב: ולפי גודל מעשיו ורוב חכמתו הוא זוכה [וכן לדעת הרמב\"ן (בשער הגמול. וכ\"ה ההכרעה בתורת החסידות — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380138\" data-slug=\"likkutei-torah\" data-id=\"4001380138\">לקו\"ת צו טו, ג</a>. דרמ\"צ יד, ב) שעוה\"ב הוא לנשמות בגופים — דישנם בזה חילוקי דרגות (ראה ב\"ב עה, א. תענית בסופה. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191067\" data-slug=\"likkutei-sichot\" data-id=\"1300191067\">לקו\"ש חי\"ט ע' 67</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300241066\" data-slug=\"likkutei-sichot\" data-id=\"1300241066\">חכ\"ד ע' 66</a> הערה 76). ואכ\"מ]."],["787","67","יד, ז."],["788","68","ראה לקו\"ת פרשתנו לז, א. לח, ג. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300041043\" data-slug=\"likkutei-sichot\" data-id=\"1300041043\">לקו\"ש ח\"ד</a> פ' שלח. ובכ\"מ."],["789","69","תהלים כז, יג. רמב\"ם שם פ\"ח ה\"ז."],["790","70","וראה רמב\"ם שם פ\"ג סוף ה\"ח."]]],[1301430151,"דוד<sup data-n=\"791\">71</sup> מה רב טובך אשר צפנת ליראיך וגו'\" (כמ\"ש הרמב\"ם בהל' תשובה<sup data-n=\"792\">72</sup>)\n— כי ע\"י הכניסה לא\"י וקיום המצוות שם — היינו אופן העבודה ד\"חפץ בנו ה'\" — \"עושה האמת מפני שהוא אמת\" — זוכים לטובה גדולה עוד יותר, לא רק \"מאד\" פ\"א (שמורה על טובה גדולה שלמעלה מיכולת האדם לקבל בעוה\"ז והיא טובת עוה\"ב) הבאה ע\"י עבודת ה' בבחי' \"מאד\", \"אהבה גדולה יתירה עזה מאד עד שתהא נפשו קשורה באהבת ה' ונמצא שוגה בה תמיד\", אלא \"מאד מאד\" ב\"פ, וכמ\"ש הרמב\"ם<sup data-n=\"793\">73</sup> ש\"עושה האמת מפני שהוא אמת וסוף הטובה לבא בגללה\", שישנה טובה הבאה דוקא ע\"י עבודה נעלית זו, שגם לגבי אהבה גדו­לה יתירה עזה מאד היא בבחי' מאד, כי זה מורה על ביטול האדם לגמרי לגבי הקב\"ה.\nי. והנה מזה שבתורה, שהיא (הוראה) נצחיית — מסופר ע\"ד המרגלים ודור המדבר ומענה יהושע וכלב על טענתם, מובן, שיש בכח כאו\"א מישראל להתנהג כפי דרישת יהושע וכלב, שלמעלה ממדריגה של \"במדריגה גבוה מאד\" של עבודת המרגלים (ודור המדבר).\nכלומר: מעלה זו דקיום מצות מעשיות בארץ שבאים ל\"טובה הארץ מאד מאד\" (ב\"פ), אינה רק עבור אלו ש­כניסתם לארץ באה לאחרי היותם במד­בר (וארבעים שנה), אלא ישנה בכאו\"א מישראל, דכאשר מקיים מצות בקב\"ע מפני שכן צווה ה', יש בקב\"ע זו מעלה יתירה על הדביקות שמצד האהבה.\nויש לומר, שגם זה מרומז בלשון ה­רמב\"ם:\nבהמשך לדבריו ע\"ד \"מעלת אברהם אבינו שקראו הקב\"ה אוהבו כו'\" כותב הרמב\"ם \"והיא המעלה שצונו בה הקב\"ה ע\"י משה שנא'<sup data-n=\"794\">74</sup> ואהבת את ה\"א ובזמן שיאהוב אדם את ה' אהבה הראוי' מיד יעשה כל המצות מאהבה\" (ובהלכה של­אח\"ז ממשיך לבאר \"כיצד היא האהבה הראוי'\") — ולכאורה אינו מובן: לאחרי כתבו ש\"מעלה זו היא מעלה גדולה מאד ואין כל חכם זוכה לה\", איך מתאים לומר \"והיא המעלה שצונו בה. . ע\"י משה\", היינו שנצטוו בה כל ישראל?\nאלא שהרמב\"ם בא להשמיענו, דמ\"ש \"ואין כל חכם זוכה לה\" היינו מכח עצמו ועבודתו, אבל (ע\"י ו)בכח ציווי השם (ע\"י משה) יכול כאו\"א להגיע לזה.\nיא. אמנם לכאורה יש לעיין עוד, ד­הרי אהבה היא מדה שבלב, שמגיעים אלי' ע\"י התבוננות בגדלות ה', כפי ש­האריך הרמב\"ם בסוף הפרק (וכן בהל' יסוה\"ת<sup data-n=\"795\">75</sup>), ומהו הפירוש שכאו\"א מ­ישראל יכול להגיע ל\"אהבה הראוי'\" ע\"ד מעלת אהבת אברהם אבינו?\nויובן זה בהקדם מ\"ש הרמב\"ם ב­הלכה ד \"אמרו חכמים הראשונים שמא תאמר הריני למד תורה בשביל שאהי' עשיר בשביל שאקרא רבי בשביל ש­אקבל שכר בעולם הבא ת\"ל<sup data-n=\"796\">76</sup> לאהבה את ה' כל מה שאתם עושים לא תעשו אלא מאהבה ועוד אמרו חכמים כו', וכן היו גדולי החכמים מצווים לנבוני תלמי­דיהם כו' אל תהיו כעבדים כו'\".",[["791","71","תהלים לא, כ."],["792","72","פ\"ח ה\"ו."],["793","73","הטעם שהרמב\"ם הביאו כאן בכלל — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201045\" data-slug=\"likkutei-sichot\" data-id=\"1300201045\">לקו\"ש ח\"כ ע' 45</a> ואילך."],["794","74","ואתחנן ו, ה."],["795","75","רפ\"ב."],["796","76","עקב יא, יג."]]],[1301430152,"ולכאורה תמוה, מדוע המתין הרמב\"ם לשלול הכוונה \"בשביל שאהי' עשיר וכו'\" עד לאחרי הביאור בגודל מעלת העבודה מאהבה (מעלת אהבת אברהם אבינו (בהלכה ב) ותיאור ה\"אהבה הראוי'\" (בהלכה ג)), ולא כללה בהלכה א גבי עובד מיראה, ד\"אל יאמר אדם הריני עושה מצות התורה כו' כדי שאקבל כל הברכות כו'\"?\n[דכיון שזוהי דרגא פחותה יותר בעובד שלא לשמה (כנ\"ל סעיף ו) — הרי הו\"ל לשלול דרגא זו בשלא לשמה לפני האריכות ע\"ד גודל מעלת אברהם אבינו ו\"אהבה הראוי'\"].\nויש לומר, שבזה מדגיש הרמב\"ם שה­עבודה מאהבה \"שצונו בה הקב\"ה על ידי משה\" שייכת לכאו\"א מישראל, גם למי שהוא עדיין בדרגא פחותה מאד, שמצ\"ע הי' \"לומד תורה בשביל שאהי' עשיר כו'\".\nביאור הדבר:\nב\"אהבה הראוי'\" יש שתי מדריגות:\n(א) הרגש האהבה שבלב, ו\"מעלה זו היא מעלה גדולה מאוד\" והיא מעלת אברהם ביחוד, וכפי שמאריך בה\"ג \"וכי­צד היא האהבה הראוי' הוא שיאהב את ה' אהבה גדולה יתירה עזה מאוד עד שתהא נפשו קשורה באהבת ה' כו'\".\n(ב) גם מי שלא הגיע לידי מדריגת אברהם לאהוב את ה' אהבה הראוי' (המביאה את האדם ש\"עושה האמת מפני שהוא אמת\"), ואדרבה, מצ\"ע הוא בדרגא זו שאומר \"הריני למד תורה בשביל ש­אהי' עשיר כו'\" — גם לו ניתנה הוראת התורה \"לאהבה את ה', כל מה שאתם עושים לא תעשו אלא מאהבה\", דהיינו אף שאינו מרגיש בלבו אהבה הראוי', מ\"מ יכול לפעול בעצמו לעשות מ­אהבה<sup data-n=\"797\">77</sup>, היינו מחמת זה שצוה הקב\"ה, בדוגמת דרגא זו ב\"מעלה גדולה מאוד\" \"שעושה האמת מפני שהוא אמת\".\nוזהו מה שממשיך בהלכה שלאח\"ז (לאחרי שמבאר הענין דעבודה לשמה ושלא לשמה, \"ואמרו חכמים לעולם יעסוק אדם בתורה ואפילו שלא לשמה שמתוך שלא לשמה בא לשמה\") — \"לפי­כך כשמלמדין את הקטנים ואת הנשים וכלל עמי הארץ אין מלמדין אותן אלא לעבוד מיראה וכדי לקבל שכר עד ש­תרבה דעתן ויתחכמו חכמה יתירה מגלים להם רז זה מעט מעט ומרגילין אותן לענין זה בנחת עד שישיגוהו וידעוהו ויעבדוהו מאהבה\" — דלכאורה, הרי כבר כתב בהלכה א' שמחנכין אותן לעבוד מיראה עד שתרבה דעתן ויעבדו מאהבה, ולמה חזר ושנה ענין זה שוב?\nאלא שבזה בא להדגיש, שגם \"רז זה\", היינו המעלה הכי עליונה ד\"אהבה ה­ראוי'\" דאברהם אוהבי, ביכולת קטנים ונשים וכלל עמי הארץ להגיע אלי' (אלא שצריכין להרגילן בזה \"מעט מעט. . בנחת\") — כי לאחרי ש\"צונו בה הקב\"ה על ידי משה\", הרי בלימוד התורה וקיום המצות<sup data-n=\"798\">*77</sup> דכ\"א מישראל מחמת זה שהם ציווי ה', אף שאין בו אהבה בהתגלות לבו, ודאי שיבוא לעסק ולימוד לשמה כו' ויעבדוהו מאהבה<sup data-n=\"799\">78</sup>.\n<span data-k=\"q\">(משיחת ש\"פ שלח תשמ\"ו)</span>",[["797","77","להעיר מהקדמה ל<a class=\"ft-cite\" href=\"#/read/tanya/3401310021\" data-slug=\"tanya\" data-id=\"3401310021\">תניא ח\"ב</a> חינוך קטן (אבל שם הוא באופן אחר). וראה תניא פט\"ז. שם רפי\"ז."],["798","*77","להעיר מתו\"א ר\"פ יתרו."],["799","78","צירוף עבודה ואהבה. ובגילוי ה\"ה העבודה. ועיין פי' אדה\"ז (ועבודתו בזה) כמצויין לעיל בסוף הערה 28."]]],[1301430153,"<h3>שיחה ג</h3>\nא. כתב המחבר בשו\"ע הל' ציצית<sup data-n=\"800\">1</sup> \"עיקר מצות טלית קטן ללבשו על בגדיו כדי שתמיד יראה ויזכור המצות\". וב­מג\"א שם<sup data-n=\"801\">2</sup> \"ובכתבים (היינו כתבי ה­אריז\"ל), דטלית קטן דוקא תחת בגדיו\".\nובפשטות<sup data-n=\"802\">3</sup>, חילוק שיטות זה הוא ה­מקור לשינוי מנהגים שמצינו בלבישת ט\"ק: הנוהגים ללבוש הט\"ק על בגדיהם למעלה, אזלי כפסק המחבר בשו\"ע; וה­לובשים הט\"ק מתחת לבגדיהם, נוהגים כדעת המג\"א ע\"פ כתבי האריז\"ל.\nובחילוק מנהגים זה בענין הבגד (ה­טלית קטן), יש עוד חילוק בנוגע לה­ציציות — כמה מהלובשים הט\"ק תחת הבגדים, נוהגין שיהיו הציציות מבחוץ.\nויש לעיין, אם מנהג זה שיהיו (רק) ה­ציציות מבחוץ, הוא ג\"כ ע\"פ כתבי ה­אריז\"ל, היינו שע\"פ האריז\"ל הט\"ק צ\"ל מתחת להבגדים, אבל הציציות עצמן צ\"ל בחוץ, או שזהו בכדי לחוש לפסק המחבר, אבל ע\"פ האריז\"ל — גם ה­ציציות צ\"ל מכוסות תחת הבגדים.\nוהנה מהמשך לשון המג\"א \"ונ\"ל דצריך שיהיו הציצית מבחוץ כו'\", אין לדייק לכאורה, שגם לה\"כתבים\" צריכין להיות מבחוץ — כי [מלבד זאת שי\"ל שגם כוונת המג\"א היא שיש להחמיר לצאת גם לדעת המחבר, הנה י\"ל ש]­עיקר<sup data-n=\"803\">4</sup> כוונת המג\"א במ\"ש \"שיהיו ה­ציצית מבחוץ\" אינה שיהיו מחוץ לה­בגדים (באופן שיוכל לראותן תמיד), כ\"א — שיהיו מחוץ להכנפות, וכהמשך לשונו שם \"ודלא כאותם שתוחבין אותן בהכנפות, ע\"ד מ\"ש בגמ<sup data-n=\"804\">5</sup> אין ציצית אלא יוצא כו'\" (וכן משמע בשו\"ע אדה\"ז<sup data-n=\"805\">6</sup> ש­לא הביא מ\"ש ב\"כתבים\" (כבמג\"א), ומ\"מ העתיק דברי המג\"א בסעיף בפ\"ע \"צריך שיהיו הציצית מבחוץ שנאמר<sup data-n=\"806\">7</sup> וראיתם אותו ודלא כאותן שתוחבין אותו בה­כנפות\")<sup data-n=\"807\">8</sup>.",[["800","1","או\"ח ס\"ח סי\"א. והובא בשו\"ע אדה\"ז שם סי\"ח (כדלקמן בפנים)."],["801","2","סקי\"ג."],["802","3","וזאת למודעי: כל הביאור שבהשיחה לא בא לקבוע ולהוכיח איך שצ\"ל המנהג בלבישת הטלית קטן, כי נהרא נהרא ופשטי', אלא רק להסביר טעמי חילוקי המנהגים הקיימים בזה.\nלכללות השאלה — ראה שו\"ת יחוה דעת (לה­גר\"ע שי' יוסף) ח\"ב ס\"א ובס' שנסמנו שם."],["803","4","ראה לקמן הערה 8."],["804","5","מנחות מא, ב ובפרש\"י שם — ראה מחה\"ש ופרמ\"ג (א\"א) למג\"א שם."],["805","6","או\"ח שם סי\"ט."],["806","7","פרשתנו טו, לט."],["807","8","אלא שמסיום הלשון במ\"א (ואדה\"ז) שם \"לכן נ\"ל דאנשים ההולכים בין העכו\"ם יוצאין בזה אך בשעת הברכה יהיו מגולין כדי הילוך ד\"א\" משמע דכוונתו לב' הענינים: שיהיו יוצאין ולא תחובין בתוך הכנפות, ושיהיו מגולין לא מכוסין.\nאבל מזה שאדה\"ז כ' ענין הנ\"ל (לא בהמשך ההלכה שצריך ללובשו על בגדיו שיראו הציצית תמיד (שבסי\"ח), אלא) בסעיף בפ\"ע (סי\"ט) \"צריך שיהיו הציצית מבחוץ וכו' ודלא כאותן שתוחבין אותו בהכנפות\", משמע לכאורה שהו\"ע בפ\"ע, שהם ב' ענינים ב\"וראיתם אותו\": א) שילבשו אותו באופן שיראו הציצית תמיד (שכ' בסעיף יח), ב) שיהיו הציצית מחוץ להכנפות — כי מצד דין הא' אם הכנפות והציצית אינן מכוסות, גם כשהציצית הם בתוך הכנפות, מתקיים \"וראיתם אותו\" — דהרי רואים הקשרים וכו' שיוצאים מהכנפות אף שאין רואים החוטים התלויים מחוץ להקשרים כו'. ולכן מוסיף בסי\"ט לימוד מיוחד \"צריך שיהיו הציצית מבחוץ שנאמר וראיתם אותו ודלא כאותן שתוחבין אותו בהכנפות\". ועצ\"ע."]]],[1301430154,"וגם לכאורה אין להכריע כן ממה ש­הביא אדה\"ז<sup data-n=\"808\">9</sup> (מהלבוש<sup data-n=\"809\">10</sup>) \"וכיון שטעם לבישת הציצית הוא כדי לזכור המצות, לפיכך הלובש<sup data-n=\"810\">11</sup> טלית קטן יזהר ללובשו על בגדיו כדי שתמיד יראוהו ויזכור ה­מצות, ואותן הלובשים אותו תחת הבגדים יזהרו שילבשו אותו באופן שיראו הציצית תמיד שע\"י ראייתן יזכרו המצות תמיד\" — כי גם בזה לכאורה אינו ברור אם זהו לפי שעיקר הקפידא שבכתבי האריז\"ל אינה אלא על הט\"ק ולא על הציצית, או שזהו רק כדי לחוש לפסק ההלכה (דברי המחבר בשולחנו) שיהיו הציציות מחוץ להבגדים.\nב. ולכאורה יש לפתור הספק ע\"פ מ\"ש במקור הדברים בכתבי האריז\"ל, ד­\"הי'<sup data-n=\"811\">12</sup> נוהג מורי (האר\"י) זלה\"ה כשהי' לובש הציצית. . הטלית גדול הוא למע­לה מכל המלבושים והט\"ק הוא תחת כל המלבושים<sup data-n=\"812\">13</sup> ושלא כדעת קצת המקו­בלים שמניחין אותו למעלה מכל המל­בושים והוא שיבוש<sup data-n=\"813\">14</sup>, אמנם יניחנו על החלוק\". ובטעם הדבר מבואר שם, כי \"ענין<sup data-n=\"814\">15</sup> ציצית ט\"ק שהוא בחי' הפנימית כו' וט\"ג הוא<sup data-n=\"815\">16</sup> כו'\".\nומובן, דטעם הנ\"ל בנוגע לט\"ק הוא (גם ובעיקר) על הציצית \"שהוא בחי' הפנימית\" (ובפרט, שהבגד עצמו אין בו קדושה וכו'<sup data-n=\"816\">17</sup>). ולפי זה, הרי גם ה­ציציות שבט\"ק צריכות להיות מכוסות<sup data-n=\"817\">18</sup> —",[["808","9","שם סי\"ח."],["809","10","שם סיו\"ד (כנסמן עה\"ג)."],["810","11","בלבוש שם לא הביא דין הנ\"ל שבשו\"ע (שיזהר ללובשו על בגדיו וכו') כאן (וכתבו בסי' כד) — אלא כותב \"וכיון שטעם. . המצות לפיכך אותם הלובשים הט\"ק תחת הבגדים יזהרו כו'\"."],["811","12","לשון הפע\"ח שער הציצית פ\"א. ועד\"ז הוא בשער הכוונות (ענין הציצית דרוש ו' ודרושי תפלת השחר פ\"ג) ועוד — הובאו במאסף לכל המחנות לשו\"ע או\"ח ס\"ח שם. וראה גם בהנסמן בהערות הבאות."],["812","13","ועד\"ז הוא בנגיד ומצוה וסידור האריז\"ל (סידור הר\"ש מרשקוב; זאלקווא תקמ\"א; סידור ר' אשר). וראה גם אור צדיקים (להר\"מ פאפריש) ס\"ז (הל' ציצית) ס\"ט. — ראה מאסף לכל המחנות שם."],["813","14","ובשער הכוונות שם: וטעות גדול הוא בידם הפך האמת."],["814","15","לשון הפע\"ח שם. ועד\"ז הוא בשער ה­כוונות, נגיד ומצוה וסידור האריז\"ל שם. וראה הערה הבאה."],["815","16","בפע\"ח שם \"פנימית של ג\"ת דיצירה וט\"ג הוא בחי' חיצונות שלהם\". וראה בהמשך הענין שם בפע\"ח, מה שמתרץ ממ\"ש דציצית קטן, אינו רק בעשי' — דציצית קטן הוא בחי' עיבור. ע\"ש ובשער הכוונות שם (הובא הענין גם ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370081\" data-slug=\"torah-or\" data-id=\"3901370081\">תו\"א תולדות יז, רע\"א</a> (בל' אדמו\"ר נ\"ע בעצמו)). וראה נהר שלום ב\"כוונות הב' טליתות\". ואכ\"מ."],["816","17","אלא שע\"פ האריז\"ל הכוונה בזה שאין בו קדושה, היינו ש\"אין בנו כח להשיגו ולכן אין הקדושה חלה על הטלית עצמו. . אבל הציציות הנמשכים ויוצאים מן הטלית הזה יש לנו בהם יותר השגה ולכן נק' תשמישי מצוה\" — ראה שער הכוונות שם דרוש ב' בתחלתו. פע\"ח שם פ\"ג (ראה שמן ששון לשם). <a class=\"ft-cite\" href=\"#/read/torah-or/3901370446\" data-slug=\"torah-or\" data-id=\"3901370446\">תו\"א מג\"א ק, א</a>. לקו\"ת פרשתנו מד, ב."],["817","18","ועפ\"ז, מ\"ש בשער הכוונות שם (בדרוש ז'. ועד\"ז בפע\"ח שם ספ\"ו. והובא בסידור האריז\"ל הנ\"ל, אור צדיקים שם. ועוד) \"כי האדם צריך להסתכל בציציות בכל שעה ורגע כמש\"ה וראיתם אותו כו'\", קאי בעיקר לא בט\"ק אלא בט\"ג [וכהמשך הלשון שם דב\"ההסתכלות יש ב' כוונות. . המסתכל בהם בעת תפלת שחרית בק\"ש. . המסתכל בהם שלא בזמן התפלה\", דכמו שההסתכלות בעת תפלת שחרית בק\"ש, הכוונה להט\"ג שבו מתעטף בתפלה, עד\"ז הוא ההסתכלות שלא בזמן תפלה (דק\"ש וברכות הק\"ש. ואולי גם נוסף ע\"ז — כי בימיהם היו כמה שהיו לובשים ט\"ג לא רק בשעת ק\"ש ותפלה — ראה מ\"ח מסכת ציצית פ\"ה מ\"ג)]. וכ\"מ בפע\"ח שם שכ' בסיום כוונת ההסתכלות \"ולכן ביום נוהגין הציצית שאז יכולין להמשיך הראי' משא\"כ בלילה שהדינין גוברין ואז אין בידינו כח להמשיך הראי'\". והרי זה שרק \"ביום נוהגין הציצית\" הוא רק בט\"ג משא\"כ ט\"ק הוא תמיד כמ\"ש בפע\"ח שם ספ\"א ועוד (הובא לקמן בפנים ס\"ז).\nואת\"ל שקאי בט\"ק (וכ\"מ במצת שמורים הל' ציצית, סוד הסתכלות בציציות תמיד), אולי י\"ל דכוונתו לא בראי' כפשוטו אלא בהסתכלות, היינו התבוננות וכוונות כו'. וראה לקמן ס\"ח. ועצ\"ע."]]],[1301430155,"תחת הלבושים ולא מבחוץ<sup data-n=\"818\">19</sup>.\n[וכן מוכח ממש\"כ בזהר<sup data-n=\"819\">20</sup> ש\"בר נש\" אחד פגע בר' חייא ור' יוסי ולא ראה אותם לובשים ציצית, היינו שהציציות שלהם לא היו נראים בחוץ<sup data-n=\"820\">21</sup>, ועד כדי כך, דגם כאשר ה\"בר נש\" חשד בהם ש­הנהגתם אינה כדבעי — לא ביארו לו (גם אחר שראה שהם \"זכאין\") למה מתנהגים כן<sup data-n=\"821\">22</sup>, כי לפי דעתם פשוט שגם הציציות צ\"ל מכוסות].\nולפי זה, הרי הנוהגים לגלות ה­ציציות זהו רק לצאת גם לדעת המחבר, אבל ע\"פ כתבי האריז\"ל אין צורך בדבר<sup data-n=\"822\">23</sup>, ואדרבה, זהו טעם הנוהגים ללבוש הט\"ק תחת הבגדים<sup data-n=\"823\">*23</sup> באופן ש­גם הציצית הן מכוסות<sup data-n=\"824\">24</sup>.\nג. ויל\"ע בנוגע לכמה מההולכים ל­אור תורת אדמו\"ר הזקן בשולחנו הזהב, וביניהם גם מחסידי חב\"ד — שהציציות אצלם לא היו מגולין בחוץ. ולכאורה אינו מובן, שהרי דברי אדה\"ז בשולחנו ברורים ד\"אותן הלובשים אותו תחת ה­",[["818","19","בסידור הרש\"ר (ועוד. ועד\"ז באור צדיקים שם) \"בטלית קטן יעשה הציצית שלפניו ארוכים שיהיו מזומנים לו בכל עת לראותן\". אבל יש לפרש, דאין הכוונה שיהיו גלויים בפועל, אלא שיהיו מזומנים לו בכל עת שרוצה באופן שיוכל בקל להגבי' בגד העליון שלו לראותן. גם — לא הובא ענין זה בשער הכוונות ופע\"ח שם.\nובמאמר מרדכי (להר\"מ כרמי) או\"ח סכ\"ד ס\"א בסופו, ג\"כ תפס שפשוט שגם הציצית מכוסות דלא כהב\"י, ומסיים \"הלכך יותר נכון. . וכן נוהגין העולם ללובשו תחת הבגדים. וכ\"כ המ\"א. . בשם האריז\"ל, דט\"ק דוקא תחת בגדיו\".\nוכ\"מ מהראי' שבמקור חיים (להר\"ח הכהן) להל' ציצית ס\"ח סי\"א — הובא בס' יפה ללב (להר\"י פאלאג'י) לאו\"ח שם."],["819","20","ח\"א רד, סע\"ב ואילך."],["820","21","וראה ניצוצי אורות וניצוצי זהר (להרב מרגליות) לזהר שם."],["821","22","ע\"ד המסופר בזח\"ג (קפו, א), שר' יצחק ור' יהודא תרצו והסבירו למה לא קראו ק\"ש."],["822","23","וכ\"מ קצת מהנהגת אנשי מעשה (הובא בלקוטי מהרי\"ח מצות ציצית) שלובשים שני ט\"ק, א' תחת הבגדים על חלוקו כדעת האריז\"ל וא' על הבגדים כדעת הטושו\"ע. — ולא ראיתי נוהגין כן במדינתנו."],["823","*23","אבל ללבוש ט\"ק על הכתונת ולמעלה ממנה, בגד קצר (זשילעט), לכאורה אין יוצאים עי\"ז לפי כתהאריז\"ל, שהרי בכתהאריז\"ל מדייק \"תחת כל המלבושים. . יניחנו על החלוק\" (פע\"ח שם פ\"א), \"למטה משאר מלבושיו ע\"ג חלוקו\" (שער הכוונות שם דרוש ו), ועד\"ז בשאר מקומות הנ\"ל, וכהובא במג\"א שם \"תחת בגדיו\", ובסי' קול יעקב: האריז\"ל הי' נוהג ללבוש הטלית קטן בביתו על חלוקו בלי הפסק שום מלבוש."],["824","24","וכ\"מ מפשטות דברי הב\"י או\"ח סכ\"ג<sup data-n=\"e18\">*</sup>; פרישה שם. ומפורש בב\"ח (וש\"ך) יו\"ד סשס\"ז (סק\"ד) \"נהגו העולם היתר בטליתות קטנים תחת בגדיהם כיון שהציצית מכוסים\".\nזה שהט\"ק הוא תחת הבגדים, מפורש בכמה פוסקים — בעל העיטור הל' ציצית סוף החלק השלישי; ספר היראה לרבינו יונה קרוב לתחלתו; מרדכי הל' ציצית סתתקמ\"ג (בשם מהר\"ם מרוטנבורג) ותענית סי' תרלז; שו\"ת הרדב\"ז ח\"ה ב' אלפים קו; שם ב'קס. ועוד. אלא שבכל הנ\"ל א) אין מבואר שכ\"ה בנוגע להציצית. ב) לא נאמר שכצ\"ל ע\"פ הלכה, אלא שבכמה מהם מעשה רב. ואכ\"מ."],["e18","*","ובשו\"ע אדה\"ז שם לא משמע כן. ואכ\"מ."]]],[1301430156,"בגדים יזהרו שילבשו אותו באופן ש­יראו הציצית תמיד כו'\".\n[ואין לתרץ ע\"ד שמצינו<sup data-n=\"825\">25</sup> לענין \"המספר קומי\" שהוא \"מדרכי האמורי\", ד\"אבטולמוס בר ראובן התירו לו לספר קומי מפני שהוא קרוב למלכות\" — כי כמה מהנ\"ל מצאנו ראינו שלא היו ה­ציציות שלהם גלויות הגם שלא היו \"קרובין למלכות\" (וגם באלו שהיו צרי­כים להשתדל עבור בנ\"י אצל המלכות — עשו כן גם בזמן שלא עסקו בזה).\nגם מובן שאין הטעם בזה לפי שב­אותו הזמן היו הולכים בין הגוים כו'<sup data-n=\"826\">26</sup>, כי המדובר גם בחסידים שקיימו כל מנהגי ישראל, ופשיטא — פס\"ד של אדה\"ז בשולחנו!]\nואולי י\"ל בזה ע\"פ המסופר<sup data-n=\"827\">27</sup> \"מפי הרה\"ג החסיד המפורסם ר' הלל פּאַריטשער זי\"ע אשר פעם אחד שאלו את אדמו\"ר הזקן איך לנהוג בדבר שה­מקובלים מחולקים עם הפוסקים, והשיב אדמו\"ר מסתמא יש לנהוג כהמקובלים. ושאלו אותו הלא הוא בעצמו בשו\"ע שלו<sup data-n=\"828\">28</sup> כתב שיש לילך אחר הפוסקים, והשיב כן כותבים הפוסקים (ובשו\"ע נמשך אחר הפוסקים) אבל המקובלים כותבים לילך אחר המקובלים נגד הפוסקים<sup data-n=\"829\">29</sup> (שהכריעו נגד המקובלים, ומובן שאין לומר שהמקובלים יהיו נגד התלמוד (או הפוסקים שלמדו דבריהם מן הגמ', שבזה כל ישראל שווים) כ­מבואר בשו\"ע סימן ס\"ח)\"<sup data-n=\"830\">30</sup>.\nועפ\"ז, ההנהגה דאלה שלבשו הט\"ק וגם הציצית בפנים, שיסודה ע\"פ מ\"ש בכהאריז\"ל (כנ\"ל) — ה\"ה ע\"פ הוראת אדה\"ז עצמו, לנהוג כהמקובלים (ה­אריז\"ל וכו') במקום שאינו כפי ה­פוסקים.\nועדיין יש מקום עיון בדבר: לפי הנ\"ל הי' צ\"ל כן מנהג כל אלה ההולכים לאור תורת אדה\"ז, שיהיו הציציות מכו­סות ביחד עם הט\"ק<sup data-n=\"831\">31</sup>, ולמעשה רואים שכו\"כ נוהגין כפסק אדה\"ז בשולחנו, ללבוש הט\"ק תחת הבגדים באופן שיראו הציציות — שלא ע\"פ כתבי האריז\"ל הנ\"ל<sup data-n=\"832\">32</sup>.\nד. ואולי י\"ל בהקדם הביאור בעצם הענין דלבישת ציצית מתחת להבגדים, דלכאורה יש לתמוה — שהרי הטעם לכך שע\"פ נגלה הציציות צריכות להיות מגולות — הוא ע\"פ הכתוב מפורש (שהוא תוכן מצות ציצית) \"וראיתם אותו",[["825","25","ב\"ק פג, א. סוטה מט, ב. רמב\"ם הל' ע\"ז פי\"א ה\"א וה\"ג. טושו\"ע יו\"ד סקע\"ח ס\"א וב'."],["826","26","ראה ערוך השלחן או\"ח ס\"ח סי\"ז. מ\"ב שם סקכ\"ו."],["827","27","שער הכולל פ\"א סק\"א (נעתק גם בשו\"ע אדה\"ז (קה\"ת) או\"ח ח\"א בסופו (קפד, ב))."],["828","28","או\"ח סכ\"ה סכ\"ח."],["829","29","וכן הכריע בסידורו בד\"כ — כהמקובלים ולא כהפוסקים (ודלא כבשו\"ע שלו) — שער הכולל שם בריש הפרק. ולהעיר משו\"ת צ\"צ או\"ח סי\"ח אות ד'. שו\"ת דברי נחמי' או\"ח סכ\"א."],["830","30","ומסיים בשער הכולל שם: וכ\"ה בשערי תשובה סכ\"ה סקי\"ד בשם הרדב\"ז והחכם צבי."],["831","31","להעיר ממכתב כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע, באג\"ק אדמו\"ר מהוריי\"צ ח\"ז ע' קלא. סה\"ש תש\"ה ע' 115."],["832","32","ואולי מנהג כו\"כ בדורנו, שלא רק שהט\"ק הוא למטה מתחת לבגדים<sup data-n=\"e19\">*</sup>, אלא שהט\"ק תחוב במכנסיים, ורק הציציות מוציאין אותן, וע\"ז עוד לובשים בגד עליון — הוא לחוש לדעת כתבי האריז\"ל."],["e19","*","כבימיהם, שכל השקו\"ט הי' אם ישנו בגד עליון המכסה הט\"ק והציצית."]]],[1301430157,"וזכרתם את כל מצות ה' גו'\"<sup data-n=\"833\">33</sup>, וגם דרשינן בגמ'<sup data-n=\"834\">34</sup> \"וראיתם אותו וזכרתם ועשיתם — ראי' מביאה לידי זכירה כו'\",\nוכיון שטעם לבישת ציצית הוא בכדי לזכור כל המצות כמ\"ש וראיתם אותו וזכרתם גו', וכלשון אדה\"ז בשו\"ע שם — יש להבין למה ע\"פ כתהאריז\"ל אין הציציות צריכות להיות מגולות?\nואף שבפע\"ח שם נאמר בזה טעם ע\"פ קבלה כנ\"ל — טעמא בעי, שהרי (כמובא לעיל) לא יצוייר שהמקובלים יהיו נגד התלמוד כו'.\nה. ואולי י\"ל הביאור בכל זה:\nמ\"ש \"וראיתם אותו וזכרתם את כל מצות ה'\", יש לפרש בשני אופנים: ד­\"וראיתם אותו וזכרתם\" הוא מגוף מצות ציצית (כדמשמע לכאורה מזה שנאמר בכתוב \"והי' לכם לציצית וראיתם אותו גו'\"), או ד\"וראיתם אותו גו'\" הוא דבר נוסף הבא כתוצאה מקיום מצות ציצית.\nונפק\"מ לדינא, דלאופן הא' כיון ד­קיום מצות ציצית (כתיקונה) הוא כאשר ישנו ה\"וראיתם אותו\" בפועל, או שישנה האפשרות לראות הציצית<sup data-n=\"835\">35</sup>, הרי אם חסר בזה — לא קיים מצות ציצית (כתי­קונה); משא\"כ לאופן הב' דקיום מצות ציצית הוא בעצם (עשייתן ו)לבישתן, הרי גם כשא\"א להיות \"וראיתם אותו\" קיים מצות ציצית כתיקונה, אלא שחסר דבר הנוסף — השלימות שיש במצות ציצית — קיום ענין \"וראיתם אותו ו­זכרתם את כל מצות ה' גו'\".\nולכאורה תלוי בב' הפירושים (ש­הביא רש\"י<sup data-n=\"836\">36</sup>) בתיבת \"ציצית\"<sup data-n=\"837\">37</sup>: א) \"ע\"ש הפתילים התלויים בה כמו<sup data-n=\"838\">38</sup> ויקחני ב­ציצית ראשי\"; ב) \"ציצית על שם וראיתם אותו כמו<sup data-n=\"839\">39</sup> מציץ מן החרכים\"<sup data-n=\"840\">40</sup>:\nדלפי' הב' דשם \"ציצית\" הוא ע\"ש ו­ראיתם אותו, מובן ד\"וראיתם אותו\" הוא גדר מצות ציצית<sup data-n=\"841\">41</sup>, וכשחסר \"וראיתם אותו\" חסר בחפצא דציצית, ולא קיים מצות ציצית כתיקונה; משא\"כ לפי' הא' שהוא ע\"ש הפתילים, הרי החפצא ד­ציצית אינו אלא הפתילים עצמם, וא\"כ קיום המצוה הוא כשלובש בגד עם ה­פתילים התלויים ויוצאים ממנה.\nו. וי\"ל דבזה פליגי הרמב\"ם והטור:\nבסוף הל' ציצית<sup data-n=\"842\">42</sup> כתב הרמב\"ם, ש­\"אע\"פ שאין אדם מחוייב לקנות לו טלית ולהתעטף בה כדי שיעשה בה ציצית,",[["833","33","כהובא בשו\"ע אדה\"ז ס\"ח, וכפשטות הלשון בשו\"ע \"שתמיד יראהו ויזכור המצות\". וכן בטושו\"ע ר\"ס כד.\nבב\"י לטור ס\"ח שם כ' \"וכן כתב נמ\"י בשם הריטב\"א\". ובנמוק\"י להלכות ציצית בשם הריטב\"א שם כ' \"ואפילו אותם שאין נוהגין אלא בט\"ק ראוי ללבוש אותו על מלבושיהם לקיים בו יפה ולא תתורו אחרי לבבכם ואחרי עיניכם\" (וראה לקמן הערה 78)."],["834","34","מנחות מג, ב."],["835","35","ראה לקמן הערה 61."],["836","36","פרשתנו טו, לח."],["837","37","גם בעוד מפרשי התורה נאמרו ב' פירושים אלה (ראה רשב\"ם, ר\"י בכור שור ועוד), אבל הם פירשו זה בב' כתובים נפרדים שבציצית, בפסוק לח פי' \"כמו בציצית ראשי קבוצת פתילים כו'\", ובפסוק לט (בו נאמר וראיתם אותו) פי' \"והי' לכם לציצית הציצית הזה יהי' לכם לראי' שתראו אותו כמו מציץ מן החרכים\" (ל' הרשב\"ם). וא\"כ אין מזה ראי' (כ\"כ) על גוף מצות ציצית."],["838","38","יחזקאל ח, ג."],["839","39","שה\"ש ב, ט."],["840","40","וכ\"ה בספרי עה\"פ."],["841","41","להעיר מאוה\"ת פרשתנו ע' תרד, שמביא ממ\"כ לרבות סוף פרשתנו \"והי' לכם לציצית שתהא נראית\" — \"פי' שצריך שיהיו הציצית על בגדיו כו' כמ\"ש הפוסקים כו'\". — ראה לקמן ס\"ז."],["842","42","פ\"ג הי\"א."]]],[1301430158,"אין ראוי לאדם חסיד שיפטור עצמו מ­מצוה זו אלא לעולם ישתדל להיות עטוף בכסות המחוייבת בציצית כדי ש­יקיים מצוה זו כו'\", ובהלכה שלאח\"ז<sup data-n=\"843\">43</sup> \"לעולם יהא אדם זהיר במצות ציצית שהרי הכתוב שקלה ותלה בה כל המצות כולן שנאמר וראיתם אותו וזכרתם את כל מצות ה'\".\nוהטור הביא ג\"כ בספרו<sup data-n=\"844\">44</sup> מעלת ה­זהירות במצות ציצית, וז\"ל: \"אע\"פ שאין אדם חייב לקנות טלית. . כדי שיתחייב בציצית כו' מ\"מ טוב ונכון להיות כל אדם זהיר וזריז במצות ציצית שיהי' לו בגד קטן מצוייץ שילבש אותו כל היום כי עיקר מצותה על זכירת המצות ובכל שעה ובכל רגע צריך לכך כו'\".\nחזינן, שהרמב\"ם חילק ההשתדלות והזהירות במצות ציצית לב' פרטים בב' הלכות. תחלה מדבר אודות מצות ציצית עצמה, ש\"אין ראוי כו' שיפטור עצמו ממצוה זו כו' לעולם ישתדל כו' כדי שיקיים מצוה זו\", ובהלכה בפ\"ע מבאר הזהירות הבאה מזה, שהציצית מביאה לידי זכירת כל המצות — \"שהרי הכתוב שקלה ותלה בה כל המצות כולן\"<sup data-n=\"845\">45</sup>,\nמשא\"כ הטור כללן ביחד כענין והמשך אחד, ולא הזכיר ע\"ד ההשתדלות בקיום מצות ציצית בפ\"ע, כ\"א הזהירות במצות ציצית מצד זכירת כל המצות שבה, ומדייק שענין זה הוא \"עיקר מצותה\" דציצית.\nוע\"פ הנ\"ל מובן, דלהרמב\"ם \"וראיתם אותו וזכרתם את כל מצות ה' גו'\" (ש\"הכתוב שקלה ותלה בה כל המצות כולן\") הוא דבר נוסף<sup data-n=\"846\">46</sup> על עצם מצות<sup data-n=\"847\">*46</sup> ציצית<sup data-n=\"848\">47</sup>, שלכן חלקם לב' פרטים בב' הלכות, ומדגיש חילוקם: חיוב ההשתד­לות במצות ציצית עצמה \"קיום מצוה זו\"; הזהירות במצות ציצית לפי שיש בה עוד ענין<sup data-n=\"849\">48</sup> (מלבד עצם המצוה) — \"שהרי",[["843","43","שם הי\"ב."],["844","44","או\"ח סכ\"ד."],["845","45","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300291004\" data-slug=\"likkutei-sichot\" data-id=\"1300291004\">לקו\"ש חכ\"ט ע' 4</a>­63."],["846","46","וי\"ל שהמקור לזה הוא ממנחות מג, ב \"ורבנן האי וראיתם אותו מאי עבדי לי' כו'\", ומשמע דס\"ל שאינו מעיקר המצוה. ויתירה מזו, שא\"צ שיראו אותן כפשוטו. וכ\"מ גם מזה ש\"מבעי' לי' לכד<a class=\"ft-cite\" href=\"#/read/tanya/3401310015\" data-slug=\"tanya\" data-id=\"3401310015\">תניא</a> וראיתם אותו וזכרתם ראה מצוה זו וזכור מצוה אחרת התלוי' בו ואיזו זו זו קרית שמע\", דלפי דרשה זו (וכן לפי הדרשות שלהלן שם: תניא אידך. . ראה מצוה זו וזכור מצוה אחרת הסמוכה לה ואיזו זו זו מצות כלאים. . <a class=\"ft-cite\" href=\"#/read/tanya/3401310015\" data-slug=\"tanya\" data-id=\"3401310015\">תניא</a> אידך וראיתם אותו. . כיון שנתחייב אדם במצוה זו נתחייב בכל מצות כולן), פי' \"וראיתם אותו וזכרתם גו'\" אינו שיראו אותן כפשוטו כו'. וראה לקמן הערה 48. ועצ\"ע."],["847","*46","וכ\"מ בגמ' ברכות (יב, ב) \"פרשת ציצית. . יש בה חמשה דברים מצות ציצית. . עול מצות. . דכתיב וראיתם אותו וזכרתם את כל מצות ה' ציצית דכתיב ועשו להם ציצית וגו'\". ומשמע, שעול מצות, שהוא \"וראיתם אותו וגו'\", הוא דבר נוסף במצות ציצית.\nועפ\"ז יומתק ל' הרמב\"ם (הל' ק\"ש פ\"א ה\"ב) \"ואח\"כ פרשת ציצית שגם היא יש בה ציווי זכירת כל המצות\", ולא כפרש\"י ברכות שם שפי' \"עול מצות — ועשיתם כל מצותי\". כי להרמב\"ם גם זכירת המצות, הכתוב \"וראיתם אותו וזכרתם את כל מצות ה'\", אינה מגוף מצות ציצית אלא דבר נוסף — עול מצות שנאמר ב\"פרשת ציצית\" [ובפרש\"י י\"ל שכתב מה שלכו\"ע, דגם להדיעה ד\"וראיתם אותו וזכרתם גו'\" הוא מגוף מצות ציצית (כמו להפי' דציצית הוא ע\"ש וראיתם אותו שהביא בפי' עה\"ת כנ\"ל ס\"ה) יש בה גם \"עול מצות\", והוא מ\"ש בכתוב שלאח\"ז \"ועשיתם את כל מצותי\". וראה לקמן ע' 154 הערה 50].\nולהעיר מזהר הרקיע אזהרה כ."],["848","47","והרמב\"ם בריש הל' ציצית פי' לשון ציצית \"שהוא דומה לציצית של ראש שנא' ויקחני בציצית ראשי\", ולא פי' שהוא מלשון ראי'."],["849","48","שלכן גם לדעת הרמב\"ם, למידין (שם פ\"ג ה\"ז) מ\"וראיתם אותו\" שאין לילה זמן ציצית. ולהעיר שמלשונו שם \"חובת הציצית ביום ולא בלילה שנא' וראיתם אותו בשעת ראי'\", משמע דלהרמב\"ם אין מצוה בראייתו בפועל, אלא פי' וראיתם אותו היינו בזמן ראי'."]]],[1301430159,"הכתוב שקלה ותלה בה כל המצות כולן\".\nמשא\"כ הטור ס\"ל ד\"וראיתם אותו וזכרתם את כל מצות ה'\" הוא מגוף<sup data-n=\"850\">49</sup> מצות ציצית<sup data-n=\"851\">50</sup>.\n[וכמו שביאר הב\"ח<sup data-n=\"852\">51</sup> דברי הטור בזה שמקדים להתעטף בציצית לפני הנחת תפלין \"לפי שציצית באים כדי לזכור כל המצות<sup data-n=\"853\">52</sup>, אבל התפילין היא מצוה יחי­דית כו'\".\nולהעיר מדברי הב\"ח<sup data-n=\"854\">53</sup>, בהטעם ש­הביא הטור הכוונה במצות ציצית \"ויכוין בהתעטפו שציונו המקום להתעטף כדי שנזכור כל מצותיו לעשותם\" (אף \"שאין זה מדרכו בחיבורו זה לבאר כוונה לשום מקרא שבתורה\"<sup data-n=\"855\">54</sup>), \"דלפי שכתוב בפרשת ציצית<sup data-n=\"856\">55</sup> למען תזכרו גו' יורה כי עיקר המצוה וקיומה תלויות בכוונתה שיכוין בשעת קיום המצוה\"<sup data-n=\"857\">56</sup>, \"שלא<sup data-n=\"855\">54</sup> קיים המצוה כתיקונה אם לא יכוין אותה הכוונה\"<sup data-n=\"859\">57</sup>].\nולכן אין לחלקם לב' ענינים, וכ­מפורש בלשונו \"להיות כל אדם זהיר וזריז במצות ציצית. . כי עיקר מצותה על זכירת המצות\"<sup data-n=\"860\">58</sup>.\nז. והנה כ\"ז הוא בקיום מצות ציצית מעיקר הדין, היינו בטלית גדול, דגם ל­הדיעה שאין \"וראיתם אותו\" מגוף ה­מצוה, ה\"ה פרט בהמצוה, ובמילא פשוט דמצות טלית גדול היא ללובשו ע\"ג ה­",[["850","49","ומה שהביא הטור בריש ס\"ח \"ונק' ציצית ע\"ש החוטין הנפרדים\", כ' בנוגע להלכה ש\"ע\"כ צריך להפרידם זמ\"ז\" (כמ\"ש הב\"ח שם), ולא כברמב\"ם שבזה התחיל כל הל' ציצית — כהגדרה על מצות ציצית (וראה רמב\"ם שם פ\"א סה\"ח)."],["851","50","וכמפורש בזהר פרשתנו (רע\"מ) קעד, ב: ציצית פקודא דא איהו לאדכרא כל פקודי אורייתא כו'."],["852","51","ר\"ס כה."],["853","52","ולהעיר שגם בסכ\"ד שם, במ\"ש הטור \"גדולה מצות ציצית ששקולה כנגד כל המצות דכתיב וראיתם אותו וזכרתם את כל מצות ה' ציצית עולה ת\"ר וח' חוטין וה' קשרים י\"ג הרי תרי\"ג\" — מפרש הב\"ח שם שהכל \"הוא גורם לזכרון, דע\"י שיעלה על מחשבתו דציצית עולה כו' תרי\"ג ע\"י כך יזכור כל תרי\"ג מצות\". ע\"ש בפרטיות. והוא דלא כפשטות הפי', שהיא מצ\"ע שקולה (וע\"ד שנאמר בע\"ז ושבת בפרש\"י סוף פרשתנו הלשון שקולה). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081108\" data-slug=\"likkutei-sichot\" data-id=\"1300081108\">לקו\"ש ח\"ח ע' 97</a> ואילך."],["854","53","או\"ח ס\"ח ד\"ה ונקראים ציצית. סתרכ\"ה קרוב לתחלתו."],["855","54","ל' הב\"ח שם סתרכ\"ה."],["856","55","פרשתנו טו, מ."],["857","56","לשונו שם ס\"ח."],["855","54","ל' הב\"ח שם סתרכ\"ה."],["859","57","וי\"ל שזהו רק לשיטת הטור ד\"וראיתם אותו וזכרתם את כל מצות ה'\" הוא מגוף מצות ציצית. אבל לדיעה הב' הנ\"ל דאינו מגוף המצוה, י\"ל ד(אף אם נדייק בתיבת \"למען\" כדברי הב\"ח שם גבי תפלין וסוכה) שאני ציצית מתפילין וסוכה, דבתפילין וסוכה נאמרה תיבת \"למען\" על קיום המצוה, \"והי' לך לאות גו' למען תהי' תורת ה' בפיך כי ביד חזקה הוציאך ה' ממצרים\" (בא יג, ט), \"בסוכות תשבו גו' למען ידעו דורותיכם גו'\" (אמור כג, מב­ג), ואילו בציצית — הכתוב \"למען תזכרו ועשיתם את כל מצותי\" בא בהמשך להכתוב \"וראיתם אותו וזכרתם את כל מצות ה' ועשיתם אותם\", שלדיעה הנ\"ל אינו מגוף קיום המצוה. וראה עולת תמיד או\"ח שם סקי\"א."],["860","58","וכ\"מ מדברי רבינו יונה בספר היראה קרוב לתחלתו, וכמו שהביא בביאורי הגר\"א בשו\"ע שם רסכ\"ד.\nוראה גם שו\"ת הריב\"ש ח\"ב סקכ\"ו (הובא בב\"י שם סכ\"ד). ולהעיר מפסקי דינים להצ\"צ לאו\"ח ס\"ח (אות ז): אבל בציצית נזהרין כל העולם ואין זה מדת חסידות לבד כ\"א מצוה דאורייתא כמ\"ש וראיתם אותו וזכרתם כו'. ע\"ש."]]],[1301430160,"בגדים באופן שיש בו \"וראיתם אותו וזכרתם גו'\".\nאבל לענין ט\"ק, פליגי הפוסקים — אם תקנו שהאדם יקיים כל הזמן מצות ציצית בפני עצמה כמצוה פרטית (נוסף על קיום מצות ציצית בט\"ג, שמקיים בו (גם) וראיתם אותו), או — שכל עיקר התקנה דט\"ק היתה כדי לזכור את כל המצות תמיד:\nלדעת המחבר, \"עיקר מצות טלית קטן ללובשו על בגדיו כדי שתמיד יראהו ויזכור המצות\", לפי שקאי בשיטת הטור הנ\"ל, וכמפורש בחיבורו ב\"י<sup data-n=\"861\">59</sup>, שדין הנ\"ל הוא — \"ממה שאמר (הטור<sup data-n=\"862\">60</sup>) בסימן כד כי עיקר מצותה על זכירת המצות ובכל שעה ובכל רגע צריך שיזכור נראה שעיקר מצות טלית קטן ללובשו מלמעלה כדי שתמיד יראהו<sup data-n=\"863\">61</sup> ויזכור המצות\"<sup data-n=\"864\">62</sup>.\nובשיטה זו קאי אדה\"ז בשלחנו, שב­תחלה כ'<sup data-n=\"865\">63</sup> \"כשיתעטף בציצית יכוין ש­ציונו הקב\"ה להתעטף בציצית כדי שנז­כור כל מצותיו לעשותם שנאמר וראיתם אותו וזכרתם את כל מצות ה'\", ואח\"ז ממשיך \"וכיון שטעם לבישת הציצית הוא כדי לזכור המצות לפיכך הלובש טלית קטן יזהר ללובשו על בגדיו כדי שתמיד יראוהו ויזכור המצות\", וממשיך \"ואותן הלובשים אותו תחת הבגדים יזהרו ש­ילבשו אותו באופן שיראו הציצית תמיד שע\"י ראייתן יזכרו המצות תמיד\", ש­מדייק \"יזהר\" \"יזהרו\", כי בלי זה חסר בגוף מצות ציצית.\nאבל לפי מ\"ש בכהאריז\"ל, ענין הט\"ק אינו אלא בשביל קיום מצות ציצית לבד, ומה\"ט הי' מניחן למטה תחת כל הלבושים<sup data-n=\"866\">64</sup>, לפי שבט\"ק אינו נוגע (ואינו שייך) הענין ד\"וראיתם אותו וגו'\".\n[וכמודגש גם בהחילוק בנוגע לציצית בלילה: ע\"פ הפסק בשו\"ע<sup data-n=\"867\">65</sup> \"לילה לאו זמן ציצית הוא דאמעיט מוראיתם אותו\" — אתמעט כל מה שלובש בלילה או כסות לילה וכו'; ואילו בפע\"ח<sup data-n=\"868\">66</sup> מחלק בזה: \"אין טלית וציצית בלילה. . אך הט\"ק צריך שישכב עמו אפי' במטה. . לעולם לא יתבטל. . אפילו בלילה אינו נפסק רק של גדלות לבדו הוא שמתבטל אבל ציצית (דט\"ק). . לעולם לא יתבטל אפי' בלילה לכן נקרא ט\"ג וט\"ק ולכן ראוי ליזהר שלא להסיר מעליו ט\"ק",[["861","59","או\"ח ס\"ח ד\"ה ומתוך מה שאמר."],["862","60","וכ\"כ בשו\"ע ר\"ס כד \"ונכון ללובשו על המלבושים\" בהמשך לתוכן דברי הטור שהביא שם [וכבר העירו על הכפל והסתירות בדברי המחבר, דכאן כתב \"עיקר מצות ט\"ק\" ובסי' כד כתב רק \"נכון\" — ראה מאמר מרדכי ס\"ח וכ\"ד. ועוד. ואכ\"מ]."],["863","61","ומ\"ש בשו\"ע שם סכ\"ד ס\"ג רק \"טוב ל­הסתכל בציצית בשעת עטיפה כשמברך\" (וראה ביאורי הגר\"א שם סק\"ז), דלכאורה לפי הנ\"ל הרי זה מגוף מצות ציצית — י\"ל, כי הראי' והסתכלות בפועל אינה מעכבת, והרי המדובר בשעת העטיפה שאז הרי זה גלוי ונראה לפניו (וראה ביאורי הגר\"א שם סק\"ח)."],["864","62","וכמפורש בשל\"ה קיא, סע\"ב ואילך (ע\"פ זהר פרשתנו קעד, ב), דעיקר מצות ט\"ק לקיים תמיד וראיתם אותו וזכרתם (ולכן \"עיקר העונש הוא על בלתי זהיר בט\"ק אשר הוא לבוש בכל עת\")."],["865","63","ס\"ח סי\"ז."],["866","64","וכהלשון באור צדיקים ועוד (הנ\"ל הערה 13) עיקר מצות ט\"ק על החלוק כו'."],["867","65","או\"ח ר\"ס יח ובנו\"כ שם. שו\"ע אדה\"ז שם."],["868","66","שם ספ\"א. מהר\"י צמח בהגהותיו כו' (הובא בברכ\"י או\"ח שם ס\"ח סי\"א). וראה גם בסידורי האריז\"ל הנ\"ל. ועוד."]]],[1301430161,"בשום זמן אפילו בהיותו ישן<sup data-n=\"869\">67</sup> רק ב­כניסתו למרחץ, לכך ראה דוד עצמו ערום במרחץ ולא בהיותו ישן כי אז הי' לו ט\"ק כנ\"ל\"<sup data-n=\"870\">68</sup>.\nוהיינו כי ע\"פ כתהאריז\"ל אין תקנת הט\"ק בעיקרה בשביל קיום מצות \"וראי­תם אותו<sup data-n=\"871\">69</sup> וזכרתם את כל מצות ה'\"].\nח. ועוד י\"ל בזה, ע\"פ דיוק בלשון כהאריז\"ל שם: בשער הכוונות<sup data-n=\"872\">70</sup> מביא ענין זה בתור הנהגת האריז\"ל עצמו אבל לא הורה בפירוש שכן צריך לנהוג כאו\"א<sup data-n=\"873\">71</sup>. וגם בפע\"ח כתב \"הי' נוהג מורי. . כשהי' לובש הציצית קטן כמו בשעה שהי' עולה כו' אז הי' מעטף בו ומורידו מן הגוף כדרך לבישתו, אמנם זה השינוי הנ\"ל הוא כי הט\"ג הוא למעלה כו' וה­ט\"ק הוא תחת כל המלבושים\", וממשיך \"שלא כדעת קצת מקובלים כו'\". והיינו, דגם לפי המקובלים יש מקום ללבוש הט\"ק למעלה מן הלבושים, אלא ש­הנהגת האריז\"ל עצמו לא היתה כן<sup data-n=\"874\">72</sup>.\nובטעם הדבר י\"ל: גם לפי מ\"ש בכת­האריז\"ל, ישנו גם בט\"ק הענין ד\"וראיתם אותו\", אלא שחלוק גדר \"וראיתם אותו\" בט\"ק מבט\"ג<sup data-n=\"875\">73</sup>:\nבט\"ג \"שהוא בחי' חיצוניות כו'\", גדר \"וראיתם אותו\" הוא כפשוטו — ראי' בחיצוניות, כי זה נוגע להנהגה חיצונית \"שלא יזדמן חטא לידו\"<sup data-n=\"876\">74</sup>, ויבוא לידי שמירת כל המצות; משא\"כ בט\"ק ש\"הוא בחי' הפנימיות\"<sup data-n=\"877\">75</sup>, גדר \"וראיתם אותו\" הוא ראי' פנימית, והיינו ראי' והסתכלות בפנימיותו, קדושת ועליית האדם עצמו למעלה נעלית יותר במצות.\nועפ\"ז מובן מה שכו\"כ מבנ\"י, וגם מהחסידים לובשים הט\"ק תחת הבגדים — ונזהרין שהציצית יראו מבחוץ, ב­התאם לפס\"ד אדה\"ז בשלחנו, ולא כפי הוראת אדה\"ז עצמו שיש לנהוג כה­מקובלים נגד הפוסקים\n— כי הנהגה זו של האריז\"ל, אינה הוראה לרבים<sup data-n=\"873\">71</sup>, כי בנ\"י זקוקים לזכירת כל המצות כפשוטה<sup data-n=\"879\">76</sup>, הן בסו\"מ שלא יזדמן חטא על ידו<sup data-n=\"880\">77</sup>, כבהמשך הכתוב \"ולא תתורו אחרי לבבכם ואחרי עיניכם אשר אתם זונים אחריהם\"<sup data-n=\"881\">78</sup>, והן בוע\"ט,",[["869","67","הובא במג\"א שם סכ\"א סק\"ב (מ\"כתבי האר\"י\")."],["870","68","במג\"א הקשה על הראי' שבכתבי האריז\"ל הנ\"ל. וראה נו\"כ השו\"ע שם. ובארוכה בברכ\"י ס\"ח שם. ואכ\"מ."],["871","69","ראה פע\"ח (הנ\"ל הערה 18). וראה סידור האריז\"ל (קול יעקב) שם \"אף בלילה אף שהוא זמן פטור מהברכה מוראיתם אותו כו'\"."],["872","70","ב\"ענין ציצית\", משא\"כ בדרושי תפלת שחרית שם. ואולי י\"ל דקאי אדלעיל מיני'. וצ\"ע."],["873","71","להעיר מברכ\"י שם ד\"ה ומ\"ש דאין ראי', בחילוק אם הרח\"ו כותב מנהג האריז\"ל לחוד או לשון סתמי שאז הוא לכאו\"א."],["874","72","ומ\"ש בשער הכוונות \"שלא כאותם ה­מתייהרים ללבשו ע\"כ בגדיו\" אין הכוונה לחשש יוהרא (ע\"ד מ\"ש בשו\"ת מהר\"י ברונא סצ\"ו), אלא הכוונה דיוהרא הוא חיצוניות וט\"ק הוא פנימיות. ועצ\"ע."],["875","73","וראה לעיל הערה 18."],["876","74","ל' שער הכוונות שם דרוש ז. פע\"ח שם פ\"ו."],["877","75","ולהעיר גם מל' אדמו\"ר (מהורש\"ב) נ\"ע שצויינה בהערה 31."],["873","71","להעיר מברכ\"י שם ד\"ה ומ\"ש דאין ראי', בחילוק אם הרח\"ו כותב מנהג האריז\"ל לחוד או לשון סתמי שאז הוא לכאו\"א."],["879","76","ומה שהבגד גופא לובשים תחת כל ה­בגדים, היינו בכדי שיהי' להם גם הענין ד\"פנימי\". וראה בהנסמן בהערה הקודמת."],["880","77","כמעשה רב במנחות מד, א. ובכו\"כ דרז\"ל. וראה בארוכה במפרשי התורה פרשתנו — אבר­בנאל, ספורנו. ובכ\"מ."],["881","78","ועפ\"ז יומתק מה שהביא הנמוק\"י (הנ\"ל הערה 33) הכתוב הנ\"ל, שהוא המקור לדברי הב\"י בשלחנו כמ\"ש בב\"י ס\"ח שם."]]],[1301430162,"קיום כל המצות, והוא ע\"י \"וראיתם אותו (שאז) וזכרתם את כל מצות ה' ועשיתם אותם\".\nורק בחלק מהם — שייך מעין הנהגת האריז\"ל — שהט\"ק וגם הציציות יהיו מכוסות, כי אין צריכים (כ\"כ) לגדר \"וראיתם אותו\" כפשוטו (במשך כל היום וכל רגע) בשביל זהירות וקיום מצות כפשוטו, ואצלם מאיר יותר ענין הראי' בפנימיות.\nומה\"ט גם בדור שלפנינו לא ראינו הנהגה זו ללבוש ט\"ק תחת כל הבגדים באופן שהציציות תהיינה מכוסות בכל בנ\"י כ\"א בחלק מהם, וי\"ל מפני שזהו \"אפס קצהו ושמץ מנהו\" מהעבודה ה­נעלית של האריז\"ל.\nט. ויהי רצון, שהזהירות במצות ציצית — לפי שינוי המנהגים שבזה<sup data-n=\"882\">79</sup>\n— אלה שמוציאים הציציות מבחוץ להבגדים, ש\"נושא חותם אדונו קבוע בכסותו\"<sup data-n=\"883\">80</sup>, ואחינו בנ\"י שאין הולכים ב­ציצית בגלוי, ע\"פ הנהגת האריז\"ל (שאז היא הנהגה (הראוי') ע\"פ תורה) —\nתזרז קיום מצות ציצית של הקב\"ה — בלשון תפלתנו<sup data-n=\"884\">81</sup> \"והביאנו לשלום מ­ארבע כנפות הארץ. . לארצנו\", בביאת משיח צדקנו בקרוב ממש.\n<span data-k=\"q\">(משיחות ש\"פ פקודי תשמ\"א. ש\"פ מקץ תשמ\"ג)</span>",[["882","79","ולהעיר, שבהנהגת כ\"ק מו\"ח אדמו\"ר ראינו, שאף שהי' לובש הט\"ק, באופן שכאשר הבגד העליון הי' פתוח, היו הט\"ק והציציות נראים — אמנם בכמה זמנים במשך היום הי' הבגד העליון סגור (מכופתר) ומכסה הט\"ק והציצית. — אבל לא שמענו ממנו — בכ\"ז."],["883","80","ל' החינוך מצוה שפו. וראה גם נמוק\"י שם. ספורנו פרשתנו. ועוד."],["884","81","בברכת אהבת עולם. ולהעיר שתיבות אלו שייכות במיוחד לאחיזת הציצית — ראה אור צדיקים שם. מקו\"ח סכ\"ד סוס\"א. שם ס\"ה. וראה גם \"היום יום\" כ\"ב סיון."]]],[1301430163,"<h3>שיחה א</h3>\nא. בפסוק<sup data-n=\"885\">1</sup> \"ויחר למשה מאד ויאמר אל ה' אל תפן אל מנחתם גו'\", מעתיק רש\"י \"אל תפן אל מנחתם\" ומפרש \"לפי פשוטו הקטורת שהם מקריבים לפניך מחר אל תפן אליהם<sup data-n=\"886\">2</sup>. והמדרש<sup data-n=\"887\">3</sup> אומר<sup data-n=\"888\">4</sup> יודע אני שיש להם חלק בתמידי צבור אף חלקם לא יקובל לפניך לרצון תני­חנו האש ולא תאכלנו\"<sup data-n=\"889\">5</sup>.\nוכתבו המפרשים<sup data-n=\"890\">6</sup> הטעם שהוצרך רש\"י להביא את פירוש המדרש ולא הסתפק בפירוש הפשוט — דקאי על \"הקטורת שהם מקריבים לפניך מחר (ש)אל תפן אליהם\" — דקשה לי' איך סלקא אדעתי' של משה שהקטורת ש­הקריבו רשעים הללו תקובל לרצון לפני הקב\"ה והי' צריך לבקש ע\"ז מ­הקב\"ה \"אל תפן\"? ולכן מביא רש\"י את פירוש המדרש דקאי על חלקם בתמידי צבור, שעל זה יש צורך לתפלה מיוחדת ש\"חלקם לא יקובל לפניך לרצון וכו'\".\nאבל צ\"ע בזה, שהרי קושי זה שב­פירוש הפשוט אינו בפרט (צדדי) שבו, אלא בכללות הפירוש, ולכן, לכאורה אין לפירוש זה מקום כלל מעיקרא, וא\"כ מדוע מביא רש\"י פירוש זה בכלל, ויתרה מזה — כפירוש ראשון ועקרי — והו\"ל להביא רק פירוש המדרש לחוד (כדמצינו בכו\"כ מקומות שרש\"י מביא רק פירוש המדרש).\nלכאורה יש לומר, שלכן מקדים רש\"י (לפני הפירוש הראשון) \"לפי פשוטו ה­קטורת כו'\" [ולא כדרכו בכל מקום שכשמפרש (תחילה) את פירושו הפשוט בהכתוב, אינו מזכיר שזהו \"לפי פשוטו\"] — להדגיש, דאע\"פ שמוכח מיד כי פי' זה קשה מעיקרו, מ\"מ זהו פירוש הכתוב \"לפי פשוטו\" (היינו לפי פשטות לשון הכתוב הזה).\nאבל פירוש זה בדברי רש\"י אינו מסתבר כלל, כי פשיטא שרש\"י לא יביא (וכ\"ש שלא יקדים) פירוש כזה שהוא מופרך ומוקשה מחמת תוכן הענין (אף שזהו פשוטו של לשון הכתוב). וכיון שלמרות הקושי הנ\"ל מביא רש\"י את ה­פירוש \"לפי פשוטו\", ולא עוד אלא ש­מקדימו לפירוש \"המדרש\", הרי עכצ\"ל שפירוש זה קרוב יותר לפשש\"מ (לא רק מצד שטחיות לשון הכתוב, אלא גם) מצד תוכנו, והיינו שהוא קרוב יותר ליישב דברי המקרא מאשר המדרש.\nב. ויובן זה בהקדים הדיוק בלשון רש\"י \"הקטורת שהם מקריבים לפניך מחר אל תפן אליהם\" — כלומר, אל ה­אנשים המקריבים — ולא כתב \"אל תפן אלי'\", שזה (א) מתאים יותר להתחלת דבריו: \"הקטורת. . אל תפן אלי'\"; וב­עיקר (ב) מתאים לתוכן הבקשה בהכתוב \"",[["885","1","פרשתנו טז, טו."],["886","2","ברמב\"ן כאן העתיק מפרש\"י \"אלי'\". וכ\"ה בדפוס ראשון ודפוס שני וכו\"כ כת\"י רש\"י. וראה לקמן סעיף ב."],["887","3","תנחומא פרשתנו ז. במדב\"ר פי\"ח, י. וראה לקמן סעיף ה."],["888","4","ברמב\"ן \"(ומדרשו) אמר\". וכ\"ה בעוד כת\"י רש\"י (שתח\"י). וראה לקמן הערה 29."],["889","5","ברמב\"ן ליתא סיום פרש\"י \"תניחנו האש כו'\", וכן ליתא בדפוס ראשון. וראה לקמן הערה 28."],["890","6","גו\"א. הואיל משה. דבק טוב. אמרי שפר. ועוד. וראה גם פענח רזא כאן: לא שחשש משה ח\"ו שהקב\"ה יקבל מנחת שוא אלא שלא ישרף חלקם כו'."]]],[1301430164,"אל תפן אל מנחתם\", שהפני' (תפן) היא אל המנחה ולא אל האנשים המקריבים.\n[ברמב\"ן אכן העתיק בפירש\"י \"אלי'\", וכ\"ה לכמה גירסאות בפרש\"י<sup data-n=\"891\">7</sup>. אמנם מזה שמצינו בכמה מקומות כהנוסחא שלפנינו \"אליהם\"<sup data-n=\"892\">8</sup>, מקום להכריע שכ\"ה הנוסח העיקרי, וכמבואר כ\"פ, שכאשר מוצאים ב' גירסאות ברש\"י — גירסא המובנת בפשטות וגירסא שלכאורה קשה להבינה ולהולמה — אזי מסתבר, אדרבה, שהגירסא הבלתי מובנת ובכ\"ז הובאה — היא היא הנכונה. ומובן ג\"כ — המעתיקים (או המדפיסים) שינו, שבודאי כוונתם רצוי' וכשרה, אלא שלדעתם ה­שינוי תיקון הוא, כי רק עפ\"ז יובן הכתוב והלשונות בהכתובים].\nוי\"ל שדייק רש\"י וכתב \"אליהם\" ולא \"אלי'\", כדי להסביר את פירוש הכתוב כאן.\nוהביאור בזה: בדברי משה אל קרח ואל כל עדתו<sup data-n=\"893\">9</sup> \"זאת עשו קחו לכם מחתות קרח וכל עדתו ותנו בהן אש ושימו עליהן קטורת לפני ה' מחר והי' האיש אשר יבחר ה' הוא הקדוש\", פרש\"י: \"זאת עשו קחו לכם מחתות — מה ראה לומר להם כך אמר להם כו' אנו אין לנו אלא כו' כה\"ג אחד ואתם מאתים וחמשים איש מבקשים כהונה גדולה אף אני רוצה בכך הא לכם תשמיש חביב מכל היא הקטורת החביבה מכל הקרבנות וסם המות נתון בתוכו שבו נשרפו נדב ואביהוא לפיכך התרה בהם כו' מי שיבחר בו יצא חי וכולכם אובדים\".\nולפ\"ז מובן שהבירור שאהרן \"הוא הקדוש\" בא עי\"ז שאהרן \"יצא חי וכול­כם אובדים\"<sup data-n=\"894\">10</sup>, כי מאחר ש\"אין לנו כו' אלא כה\"ג אחד\", שרק לו שייכת עבודת הקטורת ולא לאחרים, נמצא שהקטורת של \"כולכם\" היא קטורת זרה<sup data-n=\"895\">11</sup> — וזר שמקטיר קטורת ה\"ה במיתה, בדוגמת נדב ואביהוא שנשרפו על ידה — ולכן \"כולכם אובדים\" וזה ש\"יצא חי\" בו בחר ה'.\nאבל כ\"ז הי' בתחלה, כשחשב משה שאותם חמשים ומאתים איש מבקשים כהונה גדולה (דבר ש\"אף אני רוצה בכך\"). אבל לאחרי השקו\"ט והדברים הרכים<sup data-n=\"896\">12</sup> ודברי שלום שדיבר משה אל קרח ובני לוי (\"המעט מכם כי הבדיל וגו'\"<sup data-n=\"897\">13</sup>), ולאחר ששלח משה \"לקרוא לדתן ולאבירם גו'\" — \"שהי' משה מחזר אחריהם להשלימם בדברי שלום\"<sup data-n=\"898\">14</sup> — וכל דבריו והשתדלותו לא הועילו כלל, אלא עמדו במרדם, אז — \"ויחר למשה מאד — נצטער עד למאד\"<sup data-n=\"899\">15</sup>, ואז אמר \"אל תפן אל מנחתם\": \"הקטורת שהם",[["891","7","ראה לעיל הערה 2."],["892","8","וכן הובא בכמה מפרשי רש\"י."],["893","9","טז, ו­ז."],["894","10","פרש\"י שם."],["895","11","כמפורש בהמשך הפרשה (יז, ה) \"למען אשר לא יקרב איש זר אשר לא מזרע אהרן הוא ל­הקטיר קטורת לפני ה'\". וכן משמע במפרשי רש\"י כאן ובכמה מפרשי התורה (ראה רמב\"ן טז, ח. חזקוני שם, ו. ועוד). וראה ת\"י יומא (מז, א ד\"ה הכא מחתה). תוד\"ה נאמרה שם (מה, ב). ועוד.\nובצפע\"נ (עה\"ת פרשתנו טז, ז. שם, יז. שו\"ת צפע\"נ נ. י. סרמ\"ז) \"גם הקטורת הוי של חול וזרה ולית בי' שום חיוב של זרות וגם על הכנסה ליכא חיוב מיתה ביד\"ש. . החיוב שלהם הוי רק בשביל שהם לקחו אש מן המזבח\". ע\"ש בארוכה. וראה לקמן ס\"ג."],["896","12","פרש\"י שם, ח."],["897","13","טז, ט."],["898","14","טז, יב ובפרש\"י."],["899","15","ראה בארוכה במפרשי רש\"י במה שכ' \"נצטער עד למאוד\" ולא פי' ש\"כעס\" וכיו\"ב."]]],[1301430165,"מקריבים לפניך מחר אל תפן אליהם\", והיינו שעונשם לא יהי' בדוגמת מיתת נדב ואביהוא, עונש ע\"ז שהקטירו אש זרה, אלא \"אל תפן (כלל) אליהם\", ש­ימותו מחמת פשעם ומרדם הם.\nועפ\"ז יומתקו דברי משה \"אל תפן אל מנחתם\", ולא \"אל תקבל את גו'\", או \"אל תקח את גו'\", וכיו\"ב, כי כאן אין הכוונה שלא יקבל הקרבת הקטורת שלהם, דפשיטא הוא ומאי קמ\"ל<sup data-n=\"900\">16</sup> (כנ\"ל ס\"א) — אלא שלא יפנה אליהם כלל, שעי\"ז יהי' ניכר שמיתתן לא באה כתוצאה מזה שהקטירו קטורת (אלא שהייתה שלא כהלכה).\nוהטעם על זה מובן: מתחלה כאשר הי' מקום לחשוב שהמאתים וחמשים איש רוצים כהונה גדולה בחשבם שראויים הם לכך, אמר להם משה שע\"י הקטורת יבחר ה' מי הוא הראוי לכהונה, וכולם אובדים מחמת סם המות שבקטורת; אבל<sup data-n=\"901\">17</sup> לאחרי שראה שכל ערעורם של הר\"ן איש נשיאי העדה אינו אלא חלק מכללות מחלוקתם של קרח ודתן ואבירם על משה ואהרן וכו' כנ\"ל — אין להענש עבור פרט הקרבת קטורת זרה, אלא צ\"ל עונש כזה שיבטל את הכלל והעיקר, כללות הערעור על שליחותו של משה וכהונתו של אהרן.\nודבר זה מוכח מהמשך הכתובים, ש­הכתוב שבו נאמר עונשם של הר\"ן איש — \"ואש יצאה מאת ה' ותאכל את החמשים ומאתים איש מקריבי הקטו­רת\"<sup data-n=\"902\">18</sup> — לא בא בהמשך לסיפור הקטרת הקטורת שלהם<sup data-n=\"903\">19</sup>, אלא<sup data-n=\"904\">*19</sup> בהמשך לעונש הבליעה ד\"כל<sup data-n=\"905\">20</sup> האדם אשר לקרח ואת כל הרכוש\"<sup data-n=\"906\">21</sup>.\nוזהו שמדייק רש\"י \"אל תפן אליהם\" ולא \"אלי'\" להמנחה (קטורת), כי בקשת משה לא היתה ביחס להקטורת — כ\"א (בעיקר) לשלילה ביחס להגברא, כנ\"ל.\nג. ובזה יש לבאר השינוי בלשון הכתובים בציוויי משה ע\"ד הקרבת הקטורת, שציווי זה הי' פעמיים:\nבפעם הא' אמר משה \"זאת עשו קחו לכם מחתות קרח וכל עדתו ותנו בהן אש ושימו עליהן קטורת לפני ה' מחר והי' האיש אשר יבחר ה' הוא הקדוש גו'\", אבל לאחרי ש\"ויחר למשה מאד גו' אל תפן אל מנחתם גו'\", אמר להם פעם שני'<sup data-n=\"907\">22</sup> \"אתה גו' ואהרן גו' וקחו איש מחתתו גו' והקרבתם לפני ה'\" — ושני שינויים (עיקריים) ביניהן: (א) בפעם הא' נאמר רק \"ותנו גו' ושימו גו' לפני ה'\", אבל בפעם השני' נאמר ציווי גם על ההקרבה — \"והקרבתם לפני ה'\", (ב) בפעם הא' לא נזכר שגם אהרן נצטווה להקטיר קטורת, משא\"כ בפעם הב'<sup data-n=\"908\">23</sup>.",[["900","16","ועפי\"ז יובן דמש\"כ בשפ\"ח כאן \"אפילו העשן אל תעלה לפניך\", וכן מש\"כ במשכיל לדוד כאן שהכוונה (ע\"ד פי' המדרש) שהאש לא ישרוף את הקטורת — ג\"כ דוחק בפשוטו של מקרא, דסו\"ס מאי קמ\"ל."],["901","17","ראה גם אוה\"ח כאן."],["902","18","טז, לה."],["903","19","טז, יח."],["904","*19","וראה רש\"י יז, ג \"שנחלקו על הכהונה ונשרפו\"."],["905","20","טז, לב­ג."],["906","21","ומש\"כ בפרש\"י (יז, יג) שאמרו בנ\"י \"על ידו מתו נדב ואביהוא על ידו נשרפו חמשים ומאתים איש\", ה\"ז מה שישראל היו \"מליזין ומרננים אחר הקטורת\", וסו\"ס שריפתם באה בשייכות ובהמשך להקטורת, וכמ\"ש (טז, לה) \"ואש יצאה גו' ותאכל את גו' מקריבי הקטורת\" (וראה לעיל הערה 11). וצע\"ק."],["907","22","טז, טז­יז."],["908","23","ראה ראב\"ע ורמב\"ן שם, טז. אוה\"ח שם, יז. ועוד."]]],[1301430166,"וע\"פ הנ\"ל יש לומר, שהשינוי בפעם הב' הוא בהמשך לבקשת משה \"אל תפן אל מנחתם\".\nוהביאור בזה:\nלאחרי ש\"ויחר למשה מאד ויאמר גו' אל תפן אל מנחתם\", שהכוונה בזה (כנ\"ל בארוכה) ש\"אל תפן (כלל) אליהם\", שלא יענשו מפני שהקטירו קטורת זרה אלא מחמת מרדם כו' — קס\"ד לומר, שע\"י בקשה זו פעל משה שלא יהא נחשב כלל כמעשה של הקטרת קטורת (אפילו קטורת זרה)<sup data-n=\"909\">*23</sup>, ולכן הוצרך הכתוב ל­הדגיש שאעפ\"כ הי' כאן מעשה של הקרבת קטורת — \"והקרבתם לפני ה'\"<sup data-n=\"910\">24</sup> (ולכן מפרש הכתוב שגם אהרן הקטיר קטורת, שזה מדגיש שזהו גדר של עבודת הקטורת, השייכת לכהונה).\nוההכרח שהי' בגדר הקטרת קטורת — כי מפורש אח\"כ בפרשה שהמחתות שבהן הקריבו הקטורת נתקדשו, כדיבור ה' למשה<sup data-n=\"911\">*24</sup>: \"אמור אל אלעזר בן אהרן הכהן וירם את המחתות גו' כי קדשו\", ובפרש\"י \"כי קדשו — המחתות ואסורין בהנאה שהרי עשאום כלי שרת\"<sup data-n=\"912\">25</sup>, ואת\"ל שבפועל לא היתה הקטרתם אפילו בגדר קטורת זרה, איך נתקדשו המחתות, ולכן זקוק הכתוב להודיע כאן שמ\"מ היתה כאן פעולה של הקרבת קטורת<sup data-n=\"913\">*25</sup>.\n[משא\"כ בציווי הא' בתחילת הענין, הרי שם אין צורך להדגיש שזוהי עבודת הקטורת, כי עדיין לא ביקש משה \"אל תפן גו'\". וי\"ל, דשם נוגע להדגיש רק המציאות של קטורת, כי עצם הענין של קטורת (גם לולא העבודה שבזה) יש בו כדי לבחון מיהו \"הקדוש\" אשר בו \"יבחר ה'\", וכדיוק לשון רש\"י<sup data-n=\"914\">26</sup> שמשה אמר לקרח ועדתו \"הא לכם תשמיש חביב מכל. . וסם המות נתון בתוכו\", כלומר, המעלה היא שהוא \"תשמיש חביב\", ולאידך \"סם המות נתון בתוכו\", שלכן אלה שלא בחר בם השם — \"(כול­כם) אובדים\"].\nד. אמנם רש\"י אינו מסתפק בפירוש זה, כי עדיין ישנם כמה קשיים ביישוב דברי הכתוב:\nמפשטות המשך הכתוב \"ויחר למשה מאד ויאמר אל ה' אל תפן אל מנחתם\", משמע שבקשה זו יש בה חידוש כללי לגבי הענין המדובר בפרשה דהיינו ה­ערעור על כהונת אהרן, ומסתבר שאין משה צריך לבקש בקשה מיוחדת ש­הקב\"ה יעשה ככל הדרוש לשלול את המחלוקת והערעור על הכהונה.\nולכן מתאים יותר לפרש שהיתה זו בקשה מיוחדת על ענין שאינו שייך (מצ\"ע) לעצם פעולתם ומחלוקתם על אהרן.\nובכלל דוחק לומר שכל בקשת משה היתה רק על אופן שלילת קבלת ה­קטורת שלהם.\nובגלל קשיים אלה (שאינם רק קשיים",[["909","*23","ראה צפע\"נ הנ\"ל הערה 11."],["910","24","ולהעיר מל' רש\"י כאן: הקטורת שהם מקריבים לפניך."],["911","*24","יז, ב."],["912","25","וראה רמב\"ן שם. בכור שור שם. באר מים חיים (לאחי המהר\"ל) ודברי דוד (להט\"ז) על פרש\"י שם. ועוד."],["913","*25","ואולי י\"ל, שזה שהי' נחשב כהקרבת קטו­רת הוא מצד המעשה, שהי' כאן מעשה של הקטרה, וכן מצד ציווי משה, שלכן נתקדשו המחתות; אבל לא בשייכות להגברא, שלא נחשב שהם הקטירו הקטורת (שע\"ז ביקש משה \"הקטורת שהם מקריבים לפניך מחר אל תפן אליהם\", כנ\"ל). אבל ראה לעיל הערה 11, 21. ועצ\"ע."],["914","26","טז, ו."]]],[1301430167,"פרטיים בפירוש זה, אלא יש בהם דוחק בכללות משמעות הכתובים) מקדים רש\"י שפירוש זה הוא \"לפי פשוטו\", שאף שפירוש זה קשה ליישבו בהמשך הכתוב — הרי לפי פשוטו זהו תוכן הכתוב.\nומטעם קושי זה מוסיף רש\"י עוד פירוש: \"והמדרש אומר יודע אני שיש להם חלק בתמידי צבור אף חלקם לא יקובל לפניך לרצון כו'\", שענין זה — \"חלק בתמידי צבור\" א) הו\"ע בפ\"ע שאינו שייך להקרבת הקטורת שלהם, ולא למחלוקת וערעור על כהונת אהרן בכלל, ב) הוא דבר חיובי, שכ\"א מבנ\"י יש לו חלק בתמידי צבור.\nוע\"ז באה הבקשה המיוחדת (דמשה) \"אל תפן אל מנחתם\", שגם חלקם ב­תמידי צבור לא יקובל לרצון ש\"תניחנו האש ולא תאכלנו\".\nובזה התכוון משה (לא (רק) להביא עליהם עוד עונש מיוחד, אלא) להוסיף עי\"ז בשלילת המחלוקת והערעור על ה­כהונה. והיינו, דלא רק שאינם שייכים לכהונה ומגיע להם עונש עבור זה, אלא שהם כאילו נבדלים ר\"ל מכלל ישר­אל<sup data-n=\"915\">27</sup>, שבדבר שכל ישראל משותפים בו — תמידי צבור, הרי בנוגע אליהם — חלקם אינו מקובל ברצון.\nאמנם מובן שפירוש זה אינו לפי פשוטו ורק מדברי ה\"מדרש\" — כי<sup data-n=\"916\">28</sup> ב­כתוב זה ובכל פרשה זו לא נזכר (אפילו ברמז) הענין ד\"תמידי צבור\"<sup data-n=\"917\">29</sup>.\nה. מענינים מופלאים בהלכה שב­פרש\"י זה:\nבמדרש<sup data-n=\"918\">30</sup> איתא \"יודע אני שיש לאלו חלק באותה מנחה<sup data-n=\"919\">31</sup> שהקריבו שנאמר<sup data-n=\"920\">32</sup> מלבד עולת התמיד ומנחתה\", ורש\"י משנה וכ' \"יודע אני שיש להם חלק ב­תמידי צבור\".\nויש לומר, דרש\"י אזיל בזה לשיטתו, דס\"ל שפחות משוה פרוטה אינו נחשב \"שלו\" (כמ\"ש במס' סוכה<sup data-n=\"921\">33</sup>), ועפ\"ז אא\"ל שיש לעדת קרח חלק באותה מנחה, שהרי חלקם אינו שוה פרוטה ובמילא אין שייך בזה \"שלהם\"<sup data-n=\"922\">34</sup>, ולכן שינה",[["915","27","וכלשון המדרש שבהערה 3 \"הואיל ופירשו אלו מבניך אל תסתכל בחלקם\"."],["916","28","ונוסף ע\"ז גם תוכן הפירוש \"חלקם לא יקובל לפניך לרצון תניחנו האש ולא תאכלנו\" הו\"ע של דרש, שהרי בקרבן (תמיד) שלכל ישראל יש חלק בו — חלק של אנשים אחדים (ואפילו ר\"ן וקצת יותר) בזה הוא משהו, וקשה לומר על משהו שיחול ע\"ז \"תניחנו האש ולא תאכלנו\". ואולי זה טעם הגירסא (דלעיל הערה 5) שליתא הסיום בפרש\"י \"תניחנו האש כו'\", והכוונה ב\"חלקם לא יקובל\" היא ל\"חלק\" בציור במחשבה ולא חלק גשמי. וראה לקמן סעיף ה."],["917","29","ואולי י\"ל שפירוש ה\"מדרש\" ברש\"י כאן כוונתו שהמדרש מוסיף על פירוש הפשוט, ולא כבמדרשו ברש\"י בכלל, שבא לומר פירוש שני ולא כפירוש הפשוט, שעפ\"ז יובן: א) מה שלא כ' רש\"י \"ורבותינו דרשו\", או \"ומדרשו\"<sup data-n=\"e20\">*</sup> וכיו\"ב, כ\"א \"וה­מדרש אומר\". ב) ל' רש\"י \"אף<sup data-n=\"e21\">**</sup> חלקם לא יקובל כו'\", והיינו שלא רק שלא יפנה אל הקטורת שלהם (שע\"ז אין צריך בקשה), כ\"א דאף חלקם בתמידי צבור לא יקובל."],["918","30","במדב\"ר שם."],["919","31","וראה תנחומא: שיש להם חלק באותה מנחה שישראל מקריבים לפניך בכל יום."],["920","32","פינחס כט, יט. שם, כב. ועוד."],["921","33","כז, ב ד\"ה כל האזרח."],["922","34","ראה במפרשים לסוכה שם. והאריכו בזה באחרונים. וראה גם לקו\"ש (חלק לד) עקב תשמ\"ז ס\"ד ואילך ובהנסמן שם. ואכ\"מ."],["e20","*","וראה גירסא כזו לעיל הערה 4."],["e21","**","וראה אמרי שפר דשקו\"ט בפי' \"אף\" בפרש\"י כאן. וכ' דלכמה גירסאות ליתא \"אף\"."]]],[1301430168,"רש\"י מלשון המדרש \"באותה מנחה ש­הקריבו\" (שבמנחה אחת ודאי אין להם שווה פרוטה) וכתב \"שיש להם חלק בתמידי ציבור\", שכוונתו בזה (לא לה­מנחה או קרבן תמיד של אותו היום, אלא) לתמידי (ל' רבים) ציבור של כל השנה, שאותו החלק שיש להם (לר\"ן איש) בתמידי ציבור של כל השנה כולה — יחד הוא דבר דשפיר שייך לקרותו בשם \"חלק\". וע\"ז ביקש משה ש\"חלקם בתמידי ציבור (דכל השנה) לא יקובל לפניך לרצון\".\nויש להוסיף ב\"ענינים מופלאים\" ע\"ד הרמז שבפרש\"י — שבדיוק לשונו \"יש להם חלק בתמידי ציבור\" יש למצוא רמז לדברי האריז\"ל<sup data-n=\"923\">35</sup> שקדושה אינה זזה ממקומה, וכמ\"ש אדמו\"ר הזקן<sup data-n=\"924\">36</sup> ש­זהו \"גם לאחר שנתעלה למעלה למעלה\" — שמ\"מ \"אינו נעקר לגמרי מכל וכל ממקומו ומדרגתו הראשונה\".\nובהקדם השאלה בדברי רש\"י \"יש להם חלק בתמידי צבור\", דלכאורה, מלבד השאלה (הנ\"ל) מצד שווי הדבר ודין ממון שבו (כיון שחלקם אינו שווה פרוטה) — הרי אתינן כאן להשקו\"ט הידועה בנוגע לקרבן ציבור, דכיון דהוי דבר של ציבור אין בו שום שייכות להיחיד<sup data-n=\"925\">37</sup>, כי הגדר דציבור הוא לא שותפות של כמה וכמה יחידים, אלא מציאות חדשה, באופן שאין שייכות להיחידים בתור יחידים, ובמילא אין שייך לומר בזה \"חלק\" לכמה יחידים בפ\"ע.\nויש לומר הביאור בזה:\nכוונת רש\"י (שיש להם חלק בתמידי צבור) בפשטות היא — דכיון שכל ישר­אל נתנו מחצית השקל שמהם קנו קר­בנות ציבור (כמפורש בפרש\"י לעיל<sup data-n=\"926\">38</sup>), נמצא, שיש לכאו\"א מישראל חלק ב­קרבנות ציבור<sup data-n=\"927\">39</sup>.\nואף שצריכים למוסרו לציבור יפה יפה<sup data-n=\"928\">40</sup>, כדי שתהא נעשית מציאות חדשה דממון ציבור וחלות דקרבן ציבור, ולא השתתפות של כמה יחידים — מ\"מ כיון שהמציאות של \"צבור\" וקופת הצבור נוצרה ע\"י נתינת מחצית השקל דכל יחיד, א\"א שתתבטל ותעקר לגמרי שיי­כות היחיד להקרבן<sup data-n=\"929\">41</sup> (שהיא ע\"י מחצית השקל שנתן, שזוהי מצותו הפרטית, וב­פרט שנתינת מחצית השקל היתה לכפר על נפשותיכם<sup data-n=\"930\">42</sup>), ובלשון אדה\"ז הנ\"ל ד\"גם לאחר שנתעלה למעלה למעלה\" להיות גדר של צבור, מ\"מ לא \"נעקר לגמרי מכל וכל\" המעלה (והקדושה) שנפעלה על ידי נתינת היחיד, ולכן אפשר לומר בזה \"שיש להם חלק ב­תמידי ציבור\".\nו. ע\"פ כל הנ\"ל יש לבאר גם דיוק הלשון \"יודע אני (שיש להם חלק בתמידי",[["923","35","ראה ע\"ח שער ד פ\"ג. של\"ד פ\"ג. שער לה פ\"א. וראה פרדס שי\"ד פ\"א. וראה לקו\"ש חל\"ב ע' 25­24. וש\"נ."],["924","36","אגה\"ק ביאור לסי' זך (קמז, א)."],["925","37","ראה זבחים ד, סע\"א ובפרש\"י ותוס' שם. תוד\"ה או (מנחות עח, ב). וראה מפענח צפונות פ\"ד ס\"ב וס\"ד. וש\"נ."],["926","38","תשא ל, טו."],["927","39","וכמפורש בבחיי כאן: ודעת רז\"ל שהתפלל משה שלא יתקבל חלקם בתמידי צבור שכל אחד ואחד מישראל יש לו חלק בהם על ידי השקלים."],["928","40","ראה ר\"ה ז, סע\"א. וש\"נ. משנה למלך להל' כלי המקדש פ\"ו ה\"ט."],["929","41","וראה ספר המאמרים תיש\"א ע' 31 ובהערה שם. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181122\" data-slug=\"likkutei-sichot\" data-id=\"1300181122\">לקו\"ש חי\"ח ע' 113</a> ואילך."],["930","42","תשא שם. ובפרש\"י שם \"ועל אותה תרומה (לקנות מהם קרבנות צבור) נאמר לכפר על נפשו­תיכם\"."]]],[1301430169,"צבור)\" — דלכאורה מיותר, והול\"ל \"יש להם חלק בתמידי צבור\" וכיו\"ב.\nאך הביאור בזה: ענין הנ\"ל, שגם ל­אחרי שמחצית השקל נעשית חפצא ד­ממון ציבור, יש שייכות להיחיד עם הקרבן ציבור שנקנה ע\"י נתינת מחצית השקל שלו, אינו דבר שניתן לכאו\"א להבין מצ\"ע, אלא רק ע\"י משה רבינו, שהוא נשיא הדור,\nכי ע\"פ סדר וטבע הדברים, הרי צבור ויחיד הם שני גדרים וסוגים הפ­כיים, וכמו בקרבנות, דקרבן יחיד וקרבן ציבור הם שני מינים שונים, ולא הרי זה כהרי זה<sup data-n=\"931\">43</sup> [ומזה נשתלשל גם בסדר ה­עולם, שישנן שני הנהגות כלליות בסדרי החיים של קיבוצי בני אדם (מדינות וכיו\"ב): יש משטר המדגיש את צרכי הציבור והכלל, גם כשהם על חשבון הפרט והיחיד וגורע או גם שולל אותם, וישנה הנהגה המדגישה את חירות וטובת ותועלת הפרט, כל יחיד בפ\"ע (ועד של­פעמים דוחים את טובת הציבור והכלל עבור תועלת היחיד), כי בסדר הנהגה זו, מעלת הפרט והיחיד היא המכרעת וקובעת את סדר החיים].\nאבל כל זה הוא מצד גדר של \"סדר\", סדר דציבור וסדר דיחיד מצ\"ע. אבל כפי שהוא מצד \"נשיא הדור\", ש\"הנשיא הוא הכל\"<sup data-n=\"932\">44</sup> — הרי בכחו ופעולתו לאחד את שתי המעלות. וכמו שהוא בנוגע למציאות הנשיא עצמו — ששני ענינים אלה נכללים בהנשיא גופא: מצד אחד הרי הוא איש אחד, ולאידך, כל עניניו ופעולותיו שייכים ונוגעים להכלל כולו. ועד\"ז הוא בענין הנשיאות שבו גופא, שהנשיאות היא לא רק נשיאות על הכלל כולו, אלא הוא הנשיא של כל אחד ואחד בפרט בפני עצמו [ויש לומר שזהו דיוק לשון הרשב\"א<sup data-n=\"933\">45</sup> \"המלך כצבור ש­הצבור וכל ישראל תלויין בו\", שהתלות במלך היא לא רק תלות הצבור והכלל, שהיא מציאות אחת, אלא גם התלות דכל ישראל, כל אחד בפני עצמו (ריבוי יחידים)].\nולכן דוקא מצד משה, \"נשיא הדור\", נמשכת ובאה הידיעה (הפועלת ועושה פירות בפועל), שגם בתמידי ציבור, ש­כל כולם הוא גדר של קרבן ציבור ולא קרבן שותפין, השתתפות של יחידים, לא יתבטל חלק היחיד, ובמילא המעות שישנן ב(קרבן) ציבור שהוא נעלה יותר ובשלימות אחרת לגמרי, יש להם שיי­כות וקשר גם ליחיד, לא רק כפי שהוא חלק מהציבור, אלא גם כפי שהוא חלק ופרט בפני עצמו.\nז. פ' קרח חלה בכמה שנים בסמיכות לג' תמוז, היום אשר \"חופשה ניתנה לו\" לכ\"ק מו\"ח אדמו\"ר, נשיא הדור, ממאסרו אשר נאסר על הרבצת התורה וחיזוק הדת.\nונקודה ותוכן הנ\"ל מצינו ב\"עבודה הגדולה\" אשר עבד \"בהרבצת התורה וחיזוק הדת\"<sup data-n=\"934\">46</sup>, שאף שהי' בממדים גדו­לים ורחבים הנוגעים להצבור וכלל ישראל (הן במדינה ההיא וכ\"ש וק\"ו",[["931","43","ראה פיה\"מ להרמב\"ם הקדמה לסדר קדשים (נעתק בלחם משנה ריש הל' מעשה ה­קרבנות)."],["932","44","פרש\"י חוקת כא, כא."],["933","45","בשו\"ת שלו ח\"א סקמ\"ח."],["934","46","ל' כ\"ק מו\"ח אדמו\"ר במכתבו לחגיגת י\"ב תמוז הראשונה — בשנת תפר\"ח (נדפס בסה\"מ תש\"ח ע' 263. אגרות קודש שלו ח\"ב ע' פ. ועוד), בו כותב \"ראוי הוא לקובעו ליום התועדות והתעוררות לחיזוק התורה והיהדות בכל אתר ואתר לפי ענינו כו'\"."]]],[1301430170,"לאחר צאתו ממדינה ההיא), מ\"מ לא נגרע עי\"ז ח\"ו מההתענינות וההשתדלות בטובת היחיד והפרט ברוחניות וגם ב­גשמיות, ועד שהניח את עצמו בשביל טובתו של איש פרטי, אף שהאיש שהי' מטיב עמו הנה לא זו בלבד שלא הי' כלל בסוג של \"חבירו בתורה ומצות\"<sup data-n=\"935\">47</sup>, אלא שהי' שלא בערכו כלל.\nומעלה זו ממשיך נשיא הדור לכאו\"א ההולכים בדרכיו, ועוסקים בהרבצת ה­תורה וחיזוק הדת, שיוכלו לעסוק ולפ­עול בהפצת היהדות והמעינות לכלל ולצבור, וביחד עם זה שלא לגרוע בה­השתדלות לטובת הפרט.\nועל ידי העבודה באופן הנ\"ל פועלים הגאולה לא רק דכלל ישראל כולו אלא גם דכל אחד ואחת בפרט [וכמו שהי' בגאולת כ\"ק מו\"ח אדמו\"ר בי\"ב י\"ג תמוז, כמו שמדייק במכתבו הידוע<sup data-n=\"936\">48</sup> \"לא אותי בלבד גאל הקב\"ה בי\"ב תמוז כי אם גם את כל מחבבי תורתנו הק', שומרי מצוה, וגם את אשר בשם ישראל יכונה, כי כל איש ישראל (מבלי התחשב עם מצבו הפרטי בשמירת וקיום המצות) לבו תמים עם ד' ותורתו\"] —\nשהקב\"ה גואל לא רק את כלל ישראל, אלא את כאו\"א, כמ\"ש<sup data-n=\"937\">49</sup> \"ואתם תלוקטו לאחד אחד בני ישראל\", כל יחיד בפני עצמו, וכפרש\"י<sup data-n=\"938\">50</sup> שהקב\"ה \"אוחז בידיו ממש איש איש\", וכולם מתאחדים יחד ב\"קהל גדול\" ש\"ישובו הנה\"<sup data-n=\"939\">51</sup> בגאולה האמיתית והשלימה, בעגלא דידן ממש.\n<span data-k=\"q\">(משיחות ש\"פ קרח תשמ\"ז, י\"א ניסן תשל\"א)</span>",[["935","47","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310037\" data-slug=\"tanya\" data-id=\"3401310037\">תניא פרק לב</a> ובהנסמן בקיצורים והערות לשם."],["936","48","הנ\"ל הערה 46."],["937","49","ישעי' כז, יב."],["938","50","נצבים ל, ג."],["939","51","ירמי' לא, ז."]]],[1301430171,"<h3>שיחה ב</h3>\nא. ממש\"נ גבי חיוב הפרשת תרומה<sup data-n=\"940\">1</sup> \"כן תרימו גם אתם תרומת ה'\" למדו חז\"ל<sup data-n=\"941\">2</sup> \"גם אתם, מה אתם בני ברית אף שלוחכם (ד\"גם אתם (בא) לרבות את ה­שליח\"<sup data-n=\"942\">3</sup>) בני ברית\", שאין שליחות ל­נכרי.\nומצינו בגמ'<sup data-n=\"943\">4</sup> שקו\"ט בגדרי דין זה: רב אשי אמר כי אמרינן אין שליחות ל­נכרי הני מילי בתרומה אבל בכל התורה כולה יש שליחות לנכרי (ומסיק בגמ') והא דרב אשי ברותא<sup data-n=\"944\">5</sup> היא מאי שנא תרומה דלא, דכתיב אתם גם אתם מה אתם בני ברית אף שלוחכם נמי בני ברית, שליחות דכל התורה כולה נמי (שיהא שלוחו כמותו. רש\"י<sup data-n=\"945\">6</sup>) מתרומה גמרינן לה (בקידושין. רש\"י<sup data-n=\"945\">6</sup>).\nבפשטות משמע<sup data-n=\"947\">7</sup>, דטעמו של ר\"א דדין \"אין שליחות לנכרי\" הוא רק ב­תרומה ולא בכל התורה כולה הוא מפני שס\"ל שלא גמרינן שליחות כל התורה כולה מתרומה<sup data-n=\"948\">8</sup>.\nאבל לכאורה דוחק לומר שהפלוגתא כאן היא אם גמרינן שליחות כל התורה כולה מתרומה<sup data-n=\"949\">9</sup>. ויותר מסתבר לומר, ש­החילוק בין ר\"א ומסקנת הגמ' הוא ב­סברא:\nרב אשי ס\"ל דדין זה \"מה אתם בני ברית כו'\" הוא גזירת הכתוב, כי מצד הסברא היינו אומרים שגם נכרי יכול להיות שליח לישראל, ולכן אין לך בו אלא חידושו, ורק בתרומה אמרינן הכי ולא בכל התורה כולה.\nמשא\"כ למסקנת הגמ', ה\"ז דבר שב­סברא, שהשליח צ\"ל דומה למשלח — \"מה אתם כו' אף שלוחכם כו'\", והיינו דמ\"ש גבי תרומה \"גם אתם\" הוא רק גילוי מילתא, שגדר השליחות מחייב ש­השליח יהי' דומה להמשלח — ולכן אין דין שליחות לנכרי (גם) בכל התורה כולה.\nב. ונראה דפליגי בעצם גדר השלי­חות — ובהקדם החקירה הידועה<sup data-n=\"950\">10</sup> בענין",[["940","1","פרשתנו יח, כח."],["941","2","קידושין מא, ב. וש\"נ. רמב\"ם הל' אישות פ\"ג הי\"ז (וראה לח\"מ שם). הל' תרומות רפ\"ד. הל' שלוחין ושותפין רפ\"ב."],["942","3","קידושין שם ריש ע\"ב (וראה רש\"י שם ד\"ה גם וד\"ה לכדר' ינאי). וראה רמב\"ם הל' אישות והל' תרומות שם. וש\"נ."],["943","4","ב\"מ עא, ב."],["944","5","או \"בדותא\" (ראה על הגליון בב\"מ שם. יד מלאכי כללי הב' אות קיג)."],["945","6","ראה תורת חיים לב\"מ שם ד\"זה תימה דבריש פ\"ב דקידושין איתא בהדיא דאדרבא הא דשליחות מהניא בתרומה גמרינן לה משאר מילי\". ובכוס ישועות (ב\"מ שם) מפרש דברי הגמ' \"דילפינן כל התורה כולה מתרומה (רק) לענין זה דאין שליחות לנכרי. . וגם ברש\"י אפשר לדחוק ולפרש כזה\".\nאבל ראה טורי אבן לחגיגה י, ב (ד\"ה מה התם). ועוד. ואכ\"מ."],["945","6","ראה תורת חיים לב\"מ שם ד\"זה תימה דבריש פ\"ב דקידושין איתא בהדיא דאדרבא הא דשליחות מהניא בתרומה גמרינן לה משאר מילי\". ובכוס ישועות (ב\"מ שם) מפרש דברי הגמ' \"דילפינן כל התורה כולה מתרומה (רק) לענין זה דאין שליחות לנכרי. . וגם ברש\"י אפשר לדחוק ולפרש כזה\".\nאבל ראה טורי אבן לחגיגה י, ב (ד\"ה מה התם). ועוד. ואכ\"מ."],["947","7","וכ\"כ בכוס ישועות שם."],["948","8","כהסוגיא בקידושין שם (כנ\"ל הערה 6)."],["949","9","ובכוס ישועות שם מפרש, שמסקנת הגמ' היא שלמדין הדין דאין שליחות לנכרי (בכל התורה) מתרומה. וראה לעיל הערה 6."],["950","10","ראה לקח טוב להר\"י ענגל כלל א בארוכה (והביא ראיות לכל הצדדים). ולהעיר מל' אדה\"ז (קו\"א לשו\"ע או\"ח סרס\"ג סכ\"ה): כעושה בעצמו ממש כו' ה\"ז כאילו אוחז ידו של חבירו כו' שנעשית כידו אריכתא."]]],[1301430172,"השליחות, דשלוחו של אדם כמותו, שיש לבארו בכמה אופנים:\nא) \"כמותו\" ממש<sup data-n=\"951\">11</sup> — בנוגע לעושה המעשה, שגוף השליח הוא כגוף המשלח (ובדרך ממילא מתייחסת עשיית השליח למשלח).\nב) \"כמותו\" — (רק) בשייכות לכח ה­עשי' דהשליח או להמעשה, דעשיית ה­שליח היא כמו עשיית המשלח.\nג) \"כמותו\" — רק בנוגע לתוצאות ה­מעשה. בלשון אחר: להחפצא בו נעשה העשי' — שגם עשייתו של השליח אינה דהמשלח, אלא שעשיית השליח בהחפצא ה\"ז (פועלת אותו הדבר שפועלת) עשיית המשלח.\nועפ\"ז יש לומר, דדעת רב אשי היא כאופן הג' הנ\"ל, שגם מעשה השליחות אינו מתייחס להמשלח אלא להשליח, ו­מכיון שאין השליח עומד במקום המשלח (אפילו לא שמעשהו יחשב כמעשה ה­משלח), לכן, אם הוא רק בן אדם השייך לעשי' זו יכול להיות שליח, של זה ה­מבקשו ומקשרו עם פעולה זו, וע\"ד ש­מקשרו בחבל ואינו מתנגד לזה.\nולכן ס\"ל שבכל התורה כולה יש שליחות לנכרי, דאם השליחות היא ב­ענין כזה שגם הנכרי שייך לעשייתו<sup data-n=\"952\">12</sup>, הרי הוא יכול להיות שליח לישראל.\nאמנם מסקנת הגמ' היא, ד\"הא דר\"א ברותא היא\", ששיטה זו מופרכת, והכרח שהשליח יהי' דומה להמשלח (\"מה אתם כו' אף שלוחכם כו'\"). היינו, שגם את\"ל שענין שליחות הוא כאופן הג' הנ\"ל, שה­עשי' היא מעשה השליח — מ\"מ, ענין ה­שליחות לא יתכן אלא במי שהוא \"כמותו דהמשלח\"<sup data-n=\"953\">13</sup>, וזהו ע\"פ כל האופנים ש­מבארים ענין השליחות.\nהסברת הענין:\nבשליחות יש שני ענינים: (א) קיום השליחות בפועל. (ב) חלות שם שליח.\nכל שלשת האופנים הנ\"ל בגדר ה­שליחות הם רק בנוגע לקיום השליחות בפועל: כאשר דנים איך מועיל מעשה איש זה (השליח) עבור איש אחר (ה­משלח) — אז יתכן לומר הטעם בזה בג' אופנים, אם משום שחדשה תורה בשלי­חות שמעשה השליח מועיל כמעשה ה­משלח, או מטעם שעשייתו זו נחשבת כעשיית המשלח, או יתירה מזו, שגוף השליח נחשב כגוף המשלח ובמילא מעשהו כמעשה המשלח.\nאבל קודם לכן צ\"ל חלות של שלי­חות על השליח, היינו המינוי הפועל חלות שם שליח<sup data-n=\"954\">14</sup>. וכדי שיחול עליו שם שליח, צ\"ל קשר בין השליח והמשלח, כי אא\"פ להיות שלוחו של המשלח (באיזה אופן שהוא) מבלי שיהי' \"כמותו דה­משלח\", ש\"צריך להיות השליח מתייחס בערך מה\"<sup data-n=\"955\">15</sup> להמשלח.\nולכן אין שליחות לנכרי בכל התורה",[["951","11","ראה שו\"ת הריב\"ש סי' רכח. וראה הערה 13."],["952","12","שהרי צ\"ל ב\"תורת\" אותו דבר כדי להיות שליח בדבר (קידושין שם. גיטין כג, א וברש\"י שם. ועוד)."],["953","13","ל' אדה\"ז ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380080\" data-slug=\"likkutei-torah\" data-id=\"4001380080\">לקו\"ת ויקרא (א, ג</a>) — היינו שהפירוש ב\"שלוחו של אדם כמותו\" הוא לא רק בנוגע לדין השליחות, אלא גם בנוגע למהות ה­שליח, שצ\"ל \"כמותו דהמשלח\", כדלקמן. וראה לקמן סעיף ד."],["954","14","להעיר מצפע\"נ (להל' אישות פ\"ג הט\"ו. השמטות להל' מת\"ע — ג, א) אם השליח יש עליו שם שליח תיכף או לאחר שהתחיל לעשות הדבר. ע\"ש."],["955","15","ל' אדה\"ז בלקו\"ת שם."]]],[1301430173,"כולה, כי אינו יכול להיות \"כמותו דה­משלח\"<sup data-n=\"956\">16</sup> (הישראל).\nג. ע\"פ ההסבר הנ\"ל בדברי רב אשי, יש לבאר עוד מאמר של ר\"א בענין השליחות, שמצינו ג\"כ שנפרך להלכה — בדין שליח עושה שליח, שיכול לעשות כמה שלוחין<sup data-n=\"957\">17</sup> (\"אפילו מאה\"<sup data-n=\"958\">18</sup>), דס\"ל לרב אשי<sup data-n=\"957\">17</sup> ש\"אם מת (שליח) ראשון בטלו כולן, אמר מר בר רב אשי הא דאבא דקטנותא היא (בקטנותו אמר אבי שמועה זו שיש להשיב עלי'<sup data-n=\"960\">19</sup>) אילו מת בעל מידי מששא אית בהו כולהו מכח מאן קאתו מכח דבעל קאתו איתי' לבעל איתנהו לכולהו ליתי' לבעל ליתנהו ל­כולהו\".\nוהנה באחרונים<sup data-n=\"961\">20</sup> כתבו שפלוגתת ר\"א ומר בר\"א (אם קאתו מכח שליח ראשון או מכח הבעל) היא, דמר בר\"א ס\"ל דהשליח הוא כהמשלח עצמו או עכ\"פ שמעשהו מתייחס להמשלח, ונמצא שהשליח הראשון (וכמוהו כל השלוחים אחריו) קאתי מכח הבעל המשלח שהרי הוא עומד במקומו; משא\"כ ר\"א ס\"ל שה­שליח אינו כהמשלח עצמו, וגם מעשהו אינו מתייחס למשלח ורק מועיל עבור המשלח, וא\"כ השליח השני לא נעשה שליח מכח המשלח אלא מכח שליח הראשון.\nאבל צ\"ע בזה, שהרי מלשון מר בר\"א \"הא דאבא דקטנותא היא\" מובן, שסברת ר\"א מופרכת להלכה (וכן נפסק ל­הלכה<sup data-n=\"962\">21</sup> כמר בר\"א). והרי הביאו האחרו­נים<sup data-n=\"963\">22</sup> כמה ראיות (גם) כצד זה בשליחות שהמעשה לא נחשב אלא כעשיית ה­שליח.\nולכן נראה לומר, דגם כאן שיטת ר\"א היא לא רק מטעם שמעשה השליח לא נחשב כעשיית המשלח (ורק שעשייתו מועלת עבור המשלח), אלא משום דס\"ל יתירה מזו, שמכיון שכל ענין השליחות הוא רק בשייכות לתוצאות המעשה בה­חפצא (כנ\"ל), א\"צ להיות שום ערך בין השליח והמשלח. כלומר: לאחרי שה­משלח עשאו שליח שוב לא אתי השליח מכח המשלח אלא \"כח\" השליחות נמצא אצלו, וכאילו הוא הבעלים על דבר זה. ומטעם זה ס\"ל ש\"אם מת (שליח) ראשון בטלו כולן\", כי השלוחים לא אתו מכח המשלח אלא מכח השליח הראשון<sup data-n=\"964\">23</sup>.\nוזהו מה שאמר מר בר\"א דסברא זו מופרכת לגמרי — הא דאבא דקטנותא היא — כי \"כולהו מכח מאן קאתו מכח דבעל קאתו\", כלומר: גדר שליחות הוא מה ש\"אתי מכח\" המשלח (דעצם תואר שליח פירושו — שהוא כחו של המשלח), שלוחו של אדם כמותו, ולכן אא\"פ לייחס את ענין השליחות למי שהוא (שליח ראשון וכו') מבלי שבא ונמשך מ­",[["956","16","בשו\"ת משאת בנימין סצ\"ו (הובא בש\"ך חו\"מ סרמ\"ג סק\"ה) ועוד, שלכן גוי נעשה שליח לגוי מכיון שהם דומים. — הדיעות בזה ראה שד\"ח כללים מערכת א ס\"מ. אנציקלופדי' תלמודית ערך גוי (ע' שלו). וש\"נ."],["957","17","גיטין כט, ב."],["958","18","ל' הרמב\"ם הל' גירושין פ\"ז ה\"ד. שם הכ\"ב. וראה רש\"י גיטין שם: וכן לעולם."],["957","17","גיטין כט, ב."],["960","19","רש\"י."],["961","20","לקח טוב שם (אות ד)."],["962","21","רמב\"ם הל' גירושין פ\"ז ה\"ד. טושו\"ע אה\"ע סקמ\"א סמ\"א."],["963","22","ראה לקח טוב כלל הנ\"ל. ועוד."],["964","23","ומה שכל השלוחים שלאחריו תלויים בשליח ראשון (שאם מת שליח ראשון בטלו כולן) — ולא אמרינן דכשם ששליח ראשון לא אתי אלא מכח הבעל, כך שלוחים האחרונים לא אתו אלא מכח שליח שלפני כאו\"א — י\"ל, כי ענין השליחות נתחדש ע\"י שליח הראשון ודי בזה. וראה לקח טוב שם."]]],[1301430174,"הבעל — המשלח. ואף את\"ל שמעשה השליחות (ואפילו הפעולה דמינוי השלי­חות) נחשב כאילו עשאו השליח (כאופן הג' הנ\"ל) — מ\"מ אין הוא הבעלים כלל על הענין ד\"כולהו. . (רק) מכח דבעל קאתו\"<sup data-n=\"965\">24</sup>, וכנ\"ל בארוכה.\nד. ע\"פ הנ\"ל יומתק זה שהלימוד למעט נכרים מדין שליחות — \"מה אתם בני ברית כו'\" — נאמר גבי תרומה, ולא גבי גירושין וכיו\"ב [שגם בהם נאמר דין שליחות<sup data-n=\"966\">25</sup>]:\nיש חילוק עיקרי בין ענין השליחות בהפרשת תרומה והשליחות בשאר עני­נים — גירושין וכו':\nבהפרשת תרומה העיקר הוא הנפעל, זה שהתרומה נפרשת מהתבואה, ולכן הסברא נותנת שענין השליחות בתרומה אצ\"ל באופן ש(יהי' נחשב כאילו) ה­משלח (בעל התבואה) עשה פעולת ה­הפרשה, אלא דמכיון שהוא הבעלים של התבואה ע\"כ צ\"ל ההפרשה מדעתו — ואע\"פ שהיא פעולת השליח<sup data-n=\"967\">26</sup>.\nמשא\"כ גבי גירושין הרי פשוט שה­מגרש צ\"ל הבעל דוקא, כי גירושין הוא (לא רק הפעולה של כתיבת ונתינת הגט, אלא בעיקר) שהבעל מגרש את אשתו, ומובן ששליחות בגט פירושה שע\"י עשיית השליח נחשב שהבעל גירש את אשתו.\nולפ\"ז, אי כתב רחמנא דינא ד\"מה אתם בני ברית כו'\" גבי גירושין וכיו\"ב הי' קס\"ד לומר שהוא רק בדברים הדור­שים פעולת הבעלים ובמילא צריך ה­שליח להיות דומה להמשלח (הבעלים) שאז ראוי הוא לעמוד במקום הבעלים;\nולכן נאמר דין זה דוקא גבי תרומה, ללמדנו, שכל ענין של שליחות (באיזה ענין שהוא) — גם בתרומה שבה אנו דנים רק על העשי' והפעולה שתועיל עבור הישראל — לא יתכן חלות שם שליח אם אין השליח דומה למשלח (\"מה אתם כו' אף שלוחכם כו'\"), כי עיקר ענין ה­שליחות הוא זה שהשליח הוא \"כמותו דהמשלח\".\nה. ויש להביא ראי' לענין זה מדברי רבינו הזקן, שבנוגע לענין השליחות כותב<sup data-n=\"968\">27</sup> \"דשלוחו של אדם כמותו, ולכן אין שליחות לחרש שוטה וקטן שאינן כמותו דהמשלח\".\nולכאורה צ\"ע, שהרי מפורש בגמ'<sup data-n=\"969\">28</sup>",[["965","24","ועפ\"ז מובנת אריכות ל' מר בר\"א \"אילו מת בעל מידי מששא כו' כולהו מכח מאן כו' איתי' לבעל כו'\" [ועוד — לכאורה הו\"ל להדגיש ולהסביר איך לא בטלו כולן במיתת שליח הראשון שב­אמצעותו נעשו הם שלוחים] — אלא שמר בר\"א בא להדגיש, שכל \"כח\" השליחות אינו אלא דהמשלח (\"מכח דבעל קאתו\") ואין להשליח שייכות ל\"כח\" השליחות.\n[וכבר הקשו באחרונים מכאן על מ\"ש בקצוה\"ח (סרפ\"ח סק\"ב) שלדעת הרמב\"ם (הל' גירושין פ\"ב הט\"ו) גם אם מת המשלח לא בטלה השליחות. ואכ\"מ]."],["966","25","ראה קידושין מ, א (ואילך). וראה לעיל הערה 6.\nבפשטות י\"ל שאא\"פ לכתוב דין זה בגירושין מפני שעכו\"ם אינן בתורת גירושין וקידושין (ראה הנסמן בהערה 12). אבל ראה תוס' גיטין (שם ע\"ב ד\"ה מה אתם) דגם לר\"ש דס\"ל שעכו\"ם שתרם אין תרומתו תרומה ילפינן מתרומה לכל התורה כולה דאין שליחות לנכרי (ע\"ש) — וא\"כ ה\"ה דאפשר לכתוב דין זה בגירושין."],["967","26","ולהעיר מדעת הרמב\"ן (גיטין סו, ב — הובא בר\"ן שם (והקשה עליו). וראה ר\"ן נדרים לו, ב ד\"ה הכא נמי) ד\"גבי תרומה אפילו גלוי מילתא נמי מהני\" (וא\"צ שליחות גמורה). ע\"ש. ואכ\"מ."],["968","27","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380080\" data-slug=\"likkutei-torah\" data-id=\"4001380080\">לקו\"ת ויקרא א, ג</a>."],["969","28","גיטין כג, א. וראה רש\"י שם (וכ\"ה ברש\"י קידושין מב, א ד\"ה והא. ועוד) ד\"גבי שליחות איש בעינן\"."]]],[1301430175,"שהטעם שאינן בני שליחות הוא משום \"דלאו בני דיעה נינהו\"<sup data-n=\"970\">29</sup>?\nואף שי\"ל שזהו פירוש דברי הגמ', ד­מכיון שאינן בני דיעה נמצא שאינן \"כמותו דהמשלח\"<sup data-n=\"971\">30</sup> — מ\"מ צריך ביאור מהו ההכרח לפירוש זה?\nוע\"פ הנ\"ל י\"ל:\nידוע הכלל<sup data-n=\"972\">31</sup> דקטן אין לו כוונה, אבל יש לו מעשה. ועפ\"ז, את\"ל שענין השליחות אינו זה שהשליח עומד במקום המשלח, אלא רק שעשייתו מועלת עבור המשלח, א\"כ בדברים שאינם צריכים כוונה אלא עשי' בלבד, אין טעם לכאו­רה שלא יהי' דין שליחות לקטן<sup data-n=\"973\">32</sup>?\nוזהו שדייק רבינו הזקן לומר דמה שחש\"ו אינן בני שליחות הוא מפני שאינן \"כמותו דהמשלח\" — שלכן הם מופקעים בעצם מגדר השליחות. כלומר: אף שב­נוגע למעשה השליחות הי' מקום לומר שישנם בשליחות, שעשייתם תועיל עבור המשלח, מ\"מ, אין הם בתורת שליחות, כי אא\"פ שיחול עליהם שם שליח, מאחר שאינם \"כמותו דהמשלח\".\nו. דין שליחות בפשטות, בין אדם ל­חבירו, נמשך ומשתלשל מענין השליחות בין אדם למקום, בין ישראל לאביהם ש­בשמים:\nכאו\"א מבנ\"י ה\"ה שלוחו של הקב\"ה, שלוחו של אדם — העליון — כמותו<sup data-n=\"974\">33</sup>, ל­השלים כוונת הבריאה על ידי העבודה בקיום התומ\"צ.\nוכמו שיש ג' אופנים בדין שליחות הנ\"ל, כן הוא גם בעבודת האדם, שישנם ג' דרגות באופן מסירת וביטול השליח (האדם) אל המשלח (הקב\"ה):\nיש דרגא בעבודת השם, שהאדם ה­עובד — בהרגשתו ה\"ה מציאות בפני עצמו בכל עניניו, אלא שהוא כופה עצמו לקיים רצונו ית' — בעשיותיו הוא ממלא שליחותו של הקב\"ה;\nויש מי שפועל בעצמו ביטול פנימי, עד שעשיותיו מתייחסות להמשלח, כלו­מר, מעשיו ועניניו (בענין השליחות) ה\"ה מסורים ונתונים להשם עד שפעולותיו אלו אינן מציאות בפ\"ע ואינן אלא כח המשלח;\nולמעלה מזה הוא מי שהוא בטל ל­גמרי להקב\"ה, עד שכל מציאותו (ובדרך ממילא כל עשיותיו) אינה אלא מציאות המשלח.\nאמנם כל דרגות אלו הן רק בשייכות לקיום השליחות, אבל זה שכ\"א מישראל יש ביכלתו לקיים שליחות זו (באיזה אופן שהוא), הוא מפני שחל עליו שם \"שליח\"; וחלות שם זה יכולה להיות רק על בני ישראל (ולא באוה\"ע להבדיל) כי רק בבנ\"י יתכן לומר שהם \"כמותו דה­משלח ממש\"<sup data-n=\"975\">34</sup>; והיינו לפי שנשמות ישראל הם \"חלק ה' עמו\"<sup data-n=\"976\">35</sup>, חלק אלקה",[["970","29","להעיר מחי' רעק\"א לגיטין כג, א (וכן לכתובות יא, א) ד\"היכא דא\"צ דעתו שיעשה שליח גם לקטן יש שליחות (שיכול לעשות שליח) וזהו דאמרינן כיון דלאו בני דיעה נינהו\"."],["971","30","ראה תוס' רי\"ד ומאירי (למשנה) גיטין שם. תוד\"ה שאני גיטין סד, ב. ראב\"ד הל' גירושין פ\"ו ה\"ט. ולהעיר מנתיבות המשפט סקפ\"ב סק\"א."],["972","31","חולין יב, ב ואילך."],["973","32","להעיר ממעילה כא, א. נתה\"מ שבהערה 30. ואכ\"מ."],["974","33","ראה לקו\"ת שם."],["975","34","ל' אדה\"ז בלקו\"ת שם (בנוגע לשלוחו של אדם התחתון. אבל מהמשך הענין שם מובן דכ\"ה גם בשליחות דנש\"י מ\"קדש העליון\")."],["976","35","האזינו לב, ט. וראה אגה\"ת פ\"ד (צג, סע\"ב)."]]],[1301430176,"ממעל ממש<sup data-n=\"977\">36</sup>, ולכן רק להם יש יחס \"בערך מה\" לגבי הקב\"ה, המשלח, ועד שהם \"כמותו דהמשלח ממש\".\n[וזה מרומז גם במרז\"ל \"מה אתם בני ברית כו'\"<sup data-n=\"978\">37</sup> — שכל בנ\"י הם \"בני ברית\" עם הקב\"ה, שזהו עצם מציאותו של איש ישראל (השווה בכאו\"א בישראל) שהוא נכלל ב\"בני ברית\", דהיינו הקשר וה­ברית בין ישראל ואביהם שבשמים].\nומכל זה למדנו הוראה בפועל בעבו­דת השם:\nגם מי שעבודתו עדיין בדרגא ה­פחותה ביותר, שהוא מציאות בפ\"ע ורק שעשייתו היא עבור השם, מ\"מ, מכיון שעצם מציאותו היא \"כמותו דהמשלח ממש\", יש ביכלתו — ולכן צריך הוא — להכניס גם בעבודתו זו חיות מעצם נפשו.\nז. והנה אע\"פ שדברי רב אשי (דיש שליחות לנכרי, וכמשנת\"ל טעם הדבר, דס\"ל שאין השליח צ\"ל \"כמותו דה­משלח\") נדחו להלכה עד שאמרו \"ברותא היא\" — מ\"מ, מזה גופא שגם דבריו הוכנסו בתורת אמת, עכצ\"ל שיש גם להם מקום<sup data-n=\"979\">38</sup>.\nוי\"ל הביאור בזה — בעבודת האדם:\nבעבודת האדם לקונו ישנו עילוי כש­השליח הוא מציאות בפ\"ע (נפרד מה­משלח)<sup data-n=\"980\">39</sup> — כי אז יש בעבודתו בגלוי ה­מעלה ד\"קב שלו\", ואמרז\"ל<sup data-n=\"981\">40</sup> שע\"פ טבע בריאתו \"אדם רוצה בקב שלו מתשעה קבים של חבירו\", וכמו שרואים במוחש, דכאשר הרגשת האדם ביחס לדבר מ­סויים היא שזהו ענין הנוגע לו ה\"ז מעורר אצלו יגיעה גדולה יותר, וכן יש לו בזה יותר תענוג<sup data-n=\"982\">41</sup> וכו'.\nוכן בעבודה רוחנית, דכאשר עבודתו היא באופן שאינו מרגיש את מציאותו וחושב רק אודות המשלח [או אפילו בדרגא הפחותה בשליחות, שנחשב ל­עשיית השליח אלא שעשייתו היא בשביל המשלח], ה\"ז יכול לגרום לחלי­שות בענין היגיעה.\nולדוגמא: כאשר התייגע בכל כחו, ומ\"מ הענין לא נשלם עדיין, שאז אפשר שיעלה במחשבתו, דמכיון שהוא עשה את כל אשר ביכלתו, והענין ה\"ה של ה\"משלח\" (הקב\"ה), הרי הוא את שלו עשה, והשאר — ישלים המשלח.\nולכן יש מעלה בהרגשה שישנה מצי­אות השליח, אשר דבר השליחות נמסר לו וזהו ענין שלו, ובמילא הדבר נוגע לו במיוחד.\n[וכידוע המשל בזה — מהחילוק שבין מסירותו של פקיד או שכיר העושה ענין באמונה, למסירותו של בעל הבית באותו ענין: הפקיד, מכיון שעושה מלאכתו ב­אמונה עובד ככל יכולתו בכחות ה­גלוים, ואח\"כ הולך לעסקיו במנוחה, מ­כיון שבאמת עשה כל המוטל עליו; משא\"כ הבעה\"ב — שאינו יכול לישון במנוחה, אף אם עשה ככל יכולתו,",[["977","36","<a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a>."],["978","37","להעיר מגיטין כג, ב: מאי טעמא לאו. . מה אתם ישראל. . לא מה אתם בני ברית."],["979","38","וראה לקוטי לוי\"צ אגרות (ע' רסו): וכן ההלכה שעלי' אמרו אח\"כ שבדותא (ברותא) היא. . כולם ממש אמר ה' ובאותו הלשון ממש. . וה' עצמו אומר ההלכה והוא עצמו אמר שבדותא היא."],["980","39","להעיר מהסברא דמשלוח מנות צ\"ל דוקא ע\"י שליח (ראה שד\"ח אסיפת דינים מערכת פורים סוס\"ו)."],["981","40","ב\"מ לח, א."],["982","41","ראה פרש\"י שם: חביבה עליו ע\"י שעמל כו'."]]],[1301430177,"ובמילא מתגלים אצלו כחות נעלמים וכו'].\nח. אלא שמ\"מ מסקנת הגמ' היא \"הא דר\"א ברותא היא\", כי אע\"פ שיש מעלה בהרגשת מציאות השליח, אין זה סותר ח\"ו לענין \"שלוחו של אדם כמותו\", שה­שליח צ\"ל בטל אל המשלח.\nהסברת הענין:\nזה גופא שצ\"ל מציאות של שליח (נפרד מהמשלח), ה\"ז גופא רק מפני שזהו רצון ותענוג המשלח — כי דוקא עי\"ז \"נחת<sup data-n=\"983\">42</sup> רוח לפני שאמרתי ונעשה רצוני\".\nומזה מובן, שבעומק הענין, מציאותו של השליח (אינה מציאות בפ\"ע, אלא היא) מתאחדת עם מציאותו של המשלח להיות מציאות אחת.\n[ואדרבה — זה גופא הוא החידוש ב­ענין השליחות, שהשליח צ\"ל איש בר דעת בפני עצמו (ולא קטן<sup data-n=\"984\">43</sup>), שנמסר לו כחו ותוקפו של המשלח, ומ\"מ כל כחו (בענין השליחות) קאתי מכח המשלח].\nונמצא, שאין כאן דרגא ואופן בשלי­חות שהשליח נשאר (באמת) מציאות בפני עצמו, אלא דבר זה (שהשליח צ\"ל מציאות בפני עצמו) הוא פרט נוסף ב­ענין השליחות (דשלוחו של אדם כמו­תו), שכדי שיושלם רצון המשלח כדבעי צ\"ל מעשה השליחות נעשה על ידי מציאות השליח (עד שמרגיש את עצמו כבעל הדבר).\nוזהו גם הרמז בלשון חז\"ל (הנ\"ל) \"אדם רוצה בקב שלו מתשעה קבים של חבירו\":\n\"אדם\" ו\"חבירו\" קאי על ישראל ו­הקב\"ה (\"ריעך. . זה הקב\"ה\"<sup data-n=\"985\">44</sup>), שעל ידי שניהם יחד ישנם עשרה קבים, ה­מורה על שלימות (דעשר הוא מספר השלם<sup data-n=\"986\">45</sup>).\nוכדי להגיע לשלימות זו צ\"ל החיבור דה\"קב שלו\" של האדם וה\"תשעה קבים של חבירו\" — כלומר, מחד גיסא צ\"ל יגיעת האדם, שבזה מרגיש שזהו שלו (\"קב שלו\"), וביחד עם זה צריך להכיר שכל עבודתו (כולל זה שיש \"קב שלו\") היא בשביל \"חבירו\", וע\"י צירוף שניהם יחדיו<sup data-n=\"987\">46</sup> — ישנם כל העשרה קבים.\n<span data-k=\"q\">(משיחות כ\"ף מנ\"א תשמ\"ה, כ\"א מנ\"א תשד\"מ)</span>",[["983","42","ספרי (ורש\"י) פינחס כח, ח. ובכ\"מ."],["984","43","להעיר מהא דקטן עושה על דעת גדול ה­עומד על גביו (גיטין כג, רע\"א. ועוד. וראה אנציקלופדי' תלמודית ערך חש\"ו ס\"ה. וש\"נ)."],["985","44","שמו\"ר ר\"פ כז. רש\"י ד\"ה דעלך שבת לא, א."],["986","45","ראה ראב\"ע שמות ג, טו. פרדס ש\"ב."],["987","46","ע\"ד תורת הה\"מ (אור תורה מה, ד ואילך) שישראל והקב\"ה הם כמו \"שתי חצאי צורות\", ד\"כשיתדבקו יחד נעשה צורה שלימה\".\nולהעיר ממשנ\"ת בביאוה\"ז לאדהאמ\"צ (בשלח מג, ג) דיש הנברא ויש האמיתי חד הם. ע\"ש."]]],[1301430178,"<h3>שיחה ג</h3>\nא. עה\"פ בסיום פרשתנו<sup data-n=\"988\">1</sup> \"ולא תשאו עליו חטא בהרימכם את חלבו ממנו\" איתא בספרי: \"מנין אתה אומר שאם הפרשתם אותו שלא מן המובחר<sup data-n=\"989\">2</sup> שאתם בנשיאות עון ת\"ל ולא תשאו עליו חטא\".\nובגמרא<sup data-n=\"990\">3</sup> אמרו: \"א\"ר אילעאי מנין לתורם מן הרעה על היפה שתרומתו תרומה דכתיב ולא תשאו עליו חטא בהרימכם את חלבו ממנו [הא אם לא תרימו מן המובחר תשאו חטא. רש\"י], ואם אין קדוש נשיאות חטא למה, מיכן לתורם מן הרעה על היפה שתרומתו תרומה\".\nולכאורה נראה שיש כאן פלוגתא בין הגמ' והספרי, שבגמ' נאמר רק האיסור לתרום מן הרעה על היפה, ומשמע מזה שאין איסור לתרום מן הרעה על הרעה (וכן מן הבינונית על הבינונית)<sup data-n=\"991\">4</sup>; משא\"כ מלשון הספרי מבואר שהתרומה עצמה צריכה תמיד להיות \"מן המובחר\". וכן משמע גם מלשון הספרי לעיל עה\"פ<sup data-n=\"992\">*4</sup> \"בהרימכם את חלבו ממנו ונחשב ללוים גו'\" — \"הרי זו אזהרה. . שלא יהו תורמים אותו אלא מן המובחר<sup data-n=\"989\">2</sup>\".\n[ואע\"פ שאם אין לו אלא בינונית או רעה הרי חיוב התרומה חל רק על ה­פירות שיש לו, ואין לחייבו להשיג יפות כדי לתרום מן המובחר — מ\"מ נפק\"מ באם יש לאדם תבואה יפה ותבואה רעה ורוצה לתרום מכל סוג בפני עצמו, מן היפה על היפה ומן הרעה על הרעה, שלשיטת הש\"ס אין בכך איסור, משא\"כ להספרי שצ\"ל מן המובחר דוקא<sup data-n=\"991\">4</sup>].\nובזה יש לבאר עוד שינוי בלשון ה­ספרי מלשון הש\"ס, שבספרי הלשון \"שלא מן המובחר\"<sup data-n=\"995\">5</sup>, \"לא יהו תורמים אותו אלא מן המובחר\", דלא כלשון הש\"ס \"על היפה\": בש\"ס ההדגשה היא על החילוקים בטיב התבואה והפירות, אם הן \"רעות\" או \"יפות\", ולכן נקט \"יפה\" בניגוד ל\"רעה\" [ע\"ד שמצינו לענין שיעור תרומה<sup data-n=\"996\">6</sup>, \"עין יפה\", \"בינונית\" או \"רעה\"]; משא\"כ כוונת הספרי שלעולם חייבים לתרום \"מן המובחר\", והיינו שגם כשתורם מן היפה על היפה, הרי מבין היפות גופא צריך לתרום את המובחר ביותר<sup data-n=\"997\">7</sup>, ולכן נקט \"מובחר\" [ע\"ד הלשון",[["988","1","יח, לב."],["989","2","כ\"ה ביל\"ש, רמב\"ם (סהמ\"צ מ\"ע קכט. וראה הערה 5), רמב\"ן שהובא לקמן (ס\"ג) ועוד (ראה ספרי הוצאת האראוויטץ. ועוד). ובדפוס ראשון ועוד \"מן המחובר\". וראה מפרשי הספרי."],["990","3","יבמות פט, ב. וש\"נ."],["991","4","לכאורה י\"ל, דאם אינו תורם מן היפה ב­יותר, ממילא הוי מן הרע על היפה (כי כל שיש יפים ממנו ה\"ז בגדר רע לגבי היפים). וראה ל' רש\"י ד\"ה בהרימכם (קידושין מו, סע\"ב) \"הא אם תרימו את הרעה שבו\".\nאבל מהדוגמאות שהובאו במשנה (תרומות פ\"ב מ\"ה ואילך), תוספתא (שם פ\"ד), מנחות (נה, א) ועוד — שהם מסוג א' על סוג השני (ולא שבסוג זה גופא צריכים לתרום מן המובחר שבו) משמע, שהכוונה ב\"רע על היפה\" היא רק — שאין לתרום מסוג רע על סוג יפה. וראה לקמן סעיף ג."],["992","*4","יח, ל."],["989","2","כ\"ה ביל\"ש, רמב\"ם (סהמ\"צ מ\"ע קכט. וראה הערה 5), רמב\"ן שהובא לקמן (ס\"ג) ועוד (ראה ספרי הוצאת האראוויטץ. ועוד). ובדפוס ראשון ועוד \"מן המחובר\". וראה מפרשי הספרי."],["991","4","לכאורה י\"ל, דאם אינו תורם מן היפה ב­יותר, ממילא הוי מן הרע על היפה (כי כל שיש יפים ממנו ה\"ז בגדר רע לגבי היפים). וראה ל' רש\"י ד\"ה בהרימכם (קידושין מו, סע\"ב) \"הא אם תרימו את הרעה שבו\".\nאבל מהדוגמאות שהובאו במשנה (תרומות פ\"ב מ\"ה ואילך), תוספתא (שם פ\"ד), מנחות (נה, א) ועוד — שהם מסוג א' על סוג השני (ולא שבסוג זה גופא צריכים לתרום מן המובחר שבו) משמע, שהכוונה ב\"רע על היפה\" היא רק — שאין לתרום מסוג רע על סוג יפה. וראה לקמן סעיף ג."],["995","5","בסהמ\"צ להרמב\"ם שם לפנינו (מספרי) \"מן היפה\". אבל בסהמ\"צ הוצאת העליר וקאפח — \"מן המובחר\"."],["996","6","תרומות פ\"ד מ\"ג. ובכ\"מ."],["997","7","ראה גם של\"ה חלק תושב\"כ סוף פרשתנו."]]],[1301430179,"אצל קרבנות שצ\"ל<sup data-n=\"998\">8</sup> \"תמימין ומובחרין\", \"מן המובחר\"].\n[ויש לומר, שהספרי יליף דין זה מלשון הכתוב \"חלבו ממנו\", דלכאורה תיבת \"ממנו\" מיותרת. ובספרי לעיל עה\"פ<sup data-n=\"999\">9</sup> \"והרמותם ממנו\" — \"ממין על מינו ולא ממין על שאינו מינו\", שמפרש \"ממנו\" — \"ממינו\"<sup data-n=\"1000\">10</sup>. ועפ\"ז י\"ל, שלספרי הפירוש ב\"חלבו ממנו\" היינו שגם אם הוא \"ממינו\", צ\"ל מן המובחר שבו, דהיינו מובחר מן היפות גופא].\nב. אלא שלכאורה יש לעיין אם יש לפרש דהש\"ס פליג על הספרי בזה, ש­הרי שנינו בפירוש<sup data-n=\"1001\">11</sup> \"כל מקום שיש כהן תורם מן היפה\" (ורק כשאין כהן \"תורם מן המתקיים\", ולדעת ר' יהודה<sup data-n=\"1001\">11</sup> \"לעולם הוא תורם (רק) מן היפה\"), ועכצ\"ל שגם לשיטת הש\"ס החיוב ד\"בהרימכם את חלבו ממנו\" אינו רק איסור לתרום מן הרעה על היפה, אלא שחייבים לתרום \"מן היפה\".\nוכן שנינו<sup data-n=\"1003\">12</sup> \"וכל שאינו כלאים ב­חברו תורם מן היפה על הרע\", הרי שהחיוב לתרום \"מן היפה\" פירושו גם \"מן היפה על הרע\", ואין תורמין מן הרע על הרע.\nאיברא שבמשנה שם ממשיך \"(תורם מן היפה על הרע) אבל לא מן הרע על היפה\", וע\"פ הנ\"ל הו\"ל להתנא לומר רק \"אבל לא מן הרע\" שאז ה\"ז כולל גם לא מן הרע על הרע, ומשמע לכאורה, שה­איסור הוא רק \"מן הרע על היפה\". אבל י\"ל דהא שנקט התנא \"אבל לא מן הרע על היפה\" הוא מחמת המשך דבריו, \"ואם תרם מן הרע על היפה תרומתו תרומה\", ולכן נקט \"מן הרע על היפה\" להשמיענו חידוש, שגם באופן כזה, שלא רק שלא תרם מן היפה, אלא עוד זאת, שתרם מן הרע על היפה, מ\"מ בדיעבד תרומתו תרומה. אבל לכתחילה אסורים לתרום (לא רק מן הרע על היפה, אלא) אפילו מן הרע על הרע.\nוזהו גם הטעם שבש\"ס שם נקט ר' אילעאי \"תורם מן הרעה על היפה\" (ש­הוא ב\"נשיאות חטא\"), דלא כלשון ה­ספרי \"שהפרשתם אותו שלא מן המו­בחר\" — שאין צ\"ל שזוהי פלוגתא, אלא טעם השינוי, כי כוונת ר' אילעאי ל­השמיענו (לא עצם הדין שהוא בנשיאות חטא, אלא) הדין ש\"תרומתו תרומה\", ובזה חידוש יותר בתורם מן הרע על היפה; משא\"כ הספרי שבא להשמיענו עצם הדין שהוא \"בנשיאות עון\", סתם וכתב \"שלא מן המובחר\", שזהו החידוש, דאפילו אם רק לא הפריש מן המובחר, יש עליו נשיאות עון<sup data-n=\"1004\">13</sup>.\nג. אבל דוחק לפרש כן שיטת הש\"ס, כי בכ\"מ שמצינו במשנה וגמ' האיסור שלא יתרום מן הרע, נאמר \"לא מן הרע על היפה\"<sup data-n=\"1005\">14</sup> [או לא ממין פלוני (שהוא רע) על מין פלוני (שהוא טוב)<sup data-n=\"1006\">15</sup>] — אף שבמקומות אלה לא נזכר כלל הדין שבדיעבד תרומתו תרומה. ומשמע, שה­איסור הוא רק מן הרע על היפה.",[["998","8","רמב\"ם ריש הל' איסורי מזבח. שם רפ\"ז."],["999","9","יח, כו. — ולהעיר שבש\"ס (בכורות נג, סע\"ב. תמורה ה, א) יליף דין זה מ\"כל חלב יצהר וכל חלב תירוש ודגן\" (פרשתנו יח, יב)."],["1000","10","כ\"פ בתולדות אדם לספרי שם. מלבי\"ם שם."],["1001","11","תרומות פ\"ב מ\"ד."],["1001","11","תרומות פ\"ב מ\"ד."],["1003","12","שם מ\"ו."],["1004","13","וראה לקמן ס\"ז."],["1005","14","בתמורה (ה, א) \"חלבו אין גירועין לא\" — אבל גם שם מתחיל \"והרי תורם מן הרעה על היפה דרחמנא אמר מכל חלבו כו'\"."],["1006","15","ראה הנסמן לעיל הערה 4."]]],[1301430180,"ולכאורה יש לדייק כן מלשון ה­רמב\"ן בהשגותיו על ספר המצות לה­רמב\"ם, שמוסיף במנין מצות עשה<sup data-n=\"1007\">16</sup> \"שנצטוינו בהפרישנו תרומה שנפריש אותה מן היפה או מן השוה לא מן הרע על היפה\" (וכן מוסיף במנין הל\"ת<sup data-n=\"1008\">17</sup> \"שנמנעו הלוים שירימו מן המעשר הניתן להם תרומת מעשר מן הרע שבו אבל ירימו ביפה או בשוה והוא אמרו יתעלה ולא תשאו עליו חטא בהרימכם את חלבו ממנו\").\nוהנה לכאורה יש לפרש כוונת ה­רמב\"ן במ\"ש \"או מן השוה\" (\"או בשוה\"), שהחיוב לתרום מן היפה שולל רק הפרשה מן הרע, אבל מותר להפריש מן הבינוני<sup data-n=\"1009\">18</sup> [וע\"ד דין \"מובחרים\" בקרבן, שנוסף לכך שגם אם אינו מובחר אינו נפסל בכך<sup data-n=\"1010\">19</sup>, הנה גם גדר ד\"מובחר\" ש­חייבים להביא לכתחילה, הוא רק ש\"לא יביא שה כחוש וכעור\"<sup data-n=\"1011\">20</sup>, אבל אין חייבים (אולי אפילו לכתחילה) להביא \"מן היפה המשובח ביותר\"<sup data-n=\"1012\">21</sup>].\nוכן מפורש בש\"ס<sup data-n=\"1013\">22</sup>, בסוגיא ד\"כלך אצל יפות\", ד\"סתמי' דבעל הבית כי תרום מבינונית הוא תרום\"<sup data-n=\"1014\">23</sup>, ומדוייק גם כן בלשון הגמ' במ\"א<sup data-n=\"1015\">24</sup> \"והרי תורם מן הרעה על היפה דרחמנא אמר מכל חלבו, חלבו אין גירועין לא\", שרק \"גירועין\" אסור.\nאבל צע\"ק לשון הרמב\"ן \"או מן ה­שוה\", דלכאורה ע\"פ הנ\"ל הו\"ל לנקוט כלשון הש\"ס \"או מן הבינוני\"?\nומסתבר יותר לפרש לשון הרמב\"ן \"או מן השוה\" שכוונתו שאם התרומה והשיריים הם \"בשווה\", כלומר מאותו הסוג (ללא הבדל, אם הם יפים, בינונים או רעים), מותרים לתרום זה על זה. כי האיסור הוא רק לתרום \"מן הרע על היפה\" (וכן מ\"ש הרמב\"ן \"מן הרע שבו\", היינו שהשיריים אינם רע, ובמילא הוי תורם מן הרע על היפה) — אבל אם התרומה והשיריים \"בשוה\", אפילו שני­הם מן הרע, אין בכך איסור<sup data-n=\"1016\">25</sup>.\n[ויש להוסיף, שגם את\"ל שכוונת ה­רמב\"ן ב\"או מן השוה\" היא שמותרים לתרום מן הבינוני — ה\"ז לכאורה דלא כשיטת הספרי הנ\"ל<sup data-n=\"1017\">26</sup>, שכ' בפירוש \"שאם הפרשתם אותו שלא מן המובחר שאתם בנשיאות עון\", \"אזהרה. . שלא יהו תורמים אותו אלא מן המובחר\", ודוחק גדול לומר שכוונתו לשלול רק \"רע\" (ואדרבה, פשטות משמעות הספרי היא, דגם כשתורם מן היפה צריך לתרום מן המובחר שביפות גופא, כנ\"ל ס\"א)].",[["1007","16","מצוה ט."],["1008","17","מצוה ז."],["1009","18","ע\"ד לשון הרמב\"ם סוף הל' איסורי מזבח \"יפה. . והשוה והפחות\"."],["1010","19","דרק אם יש בו מום פסול."],["1011","20","רמב\"ם שם רפ\"ז."],["1012","21","ל' הרמב\"ם שם בסוף הפרק — למי ש\"רוצה לזכות עצמו\". וראה לקמן בפנים ס\"ה."],["1013","22","ב\"מ כב, א."],["1014","23","ובתוס' שם (ד\"ה ואם לאו) ש\"מיפות אין רגילות לתרום\". — וראה בארוכה השקו\"ט בספרי דבי רב על הספרי פרשתנו כאן (ועוד), שלכאו' לפי לשון הספרי (וכן ל' הרמב\"ם הל' תרומות רפ\"ה, הובא לקמן ס\"ד) צ\"ל רק מן המובחר. ומפרש שדברי הגמ' \"סתמי' דבעה\"ב. . מבינונית הוא תרום\" נאמרו רק להקס\"ד ולא למסקנא. ע\"ש."],["1015","24","תמורה שם."],["1016","25","וראה ערוך השולחן העתיד הל' תרומות (סי' סו) שמגרוגרות על גרוגרות יכול להפריש."],["1017","26","ואף שהרמב\"ן שם הביא דברי הספרי — י\"ל שכוונתו רק לראי' לכללות דבריו שהוא ציווי בפ\"ע (ולכן נמנה במנין המצות, דלא כהרמב\"ם שלא מנאו במנין המצות)."]]],[1301430181,"וע\"פ הנ\"ל י\"ל שמקורו של הרמב\"ן הוא בלשונות הש\"ס הנ\"ל, שהאיסור הוא רק לתרום מן הרע על היפה.\nד. ולכן מסתבר לומר, שלשיטת ה­ש\"ס (שבכל מקום מדייק שהאיסור הוא רק לתרום \"מן הרע על היפה\", ולאידך מפורש (כנ\"ל) שיש לתרום \"מן היפה על הרע\", שמזה משמע — ולא מן הרע על הרע) — יש חילוק בין החיוב והאיסור (מ\"ע ול\"ת<sup data-n=\"1018\">27</sup>):\nהחיוב (מ\"ע) לכתחילה ולהידור<sup data-n=\"1019\">28</sup> הוא לתרום מן היפה, וזה כולל שיש לתרום \"מן היפה על הרע\" (וכן ביפות גופא, המובחר מן היפות); אבל האיסור (ל\"ת) כשאינו תורם מן היפה הוא רק כשתורם מן הרע על היפה, שרק אז הוא ב­\"נשיאות חטא\"<sup data-n=\"1020\">29</sup> (משא\"כ אם רק החסיר ההידור לתרום מן היפה ומן המובחר, אין בו נשיאות חטא).\n[ויש לומר, שהחילוק תלוי בלשונות הכתובים: גבי האיסור (ל\"ת) נאמר \"ולא תשאו עליו חטא בהרימכם את חלבו ממנו\", שפשטות הכתוב<sup data-n=\"1021\">30</sup> היא, שהנשאר (\"ממנו\") אינו \"חלבו\", והיינו שצ\"ל הפ­רשה מן היפה על הרעה, ולא להיפך, מן הרעה על היפה; משא\"כ גבי החיוב (העשה) לתרום מן היפה נאמר<sup data-n=\"1022\">31</sup> (גם) \"מכל חלבו\" (סתם), \"כל חלב יצהר גו'\", שהתרומה (בכלל) צ\"ל תמיד מן ה\"חלב\" והמובחר].\nמשא\"כ לפי הספרי, שהאיסור הוא לא רק לתרום מן הרע על היפה, אלא גם כשאינו מפריש \"מן המובחר\" הרי הוא \"בנשיאות עון\".\nוזוהי גם שיטת הרמב\"ם ששינה מלשון המשנה<sup data-n=\"1001\">11</sup> \"כל מקום שיש כהן תורם מן היפה\", וכתב<sup data-n=\"1024\">32</sup> \"אין תורמין",[["1018","27","לדעת הרמב\"ן בהשמטות לסהמ\"צ שמנה החיוב לתרום מן היפה במנין העשה ובמנין הל\"ת (כנ\"ל ס\"ג), משא\"כ לדעת הרמב\"ם (סהמ\"צ מ\"ע קכט) שלא מנאו כמ\"ע בפ\"ע, וגם \"ולא תשאו עליו חטא\" אינו לאו אלא \"שלילת החיוב\" (וראה השקו\"ט במפרשי סהמ\"צ שם. הרי\"פ פערלא לסהמ\"צ הרס\"ג עשה קנד. ועוד). — וראה הערה 32."],["1019","28","להעיר מהקס\"ד דאביי (תמורה שם) \"אי לאו דאמר רחמנא ולא תשאו עליו חטא ה\"א הכי אמר רחמנא עביד מצוה מן המובחר ואי לא עביד חוטא לא מקרי, קמ\"ל\". ועפ\"ז י\"ל, שלפי המסקנא לא מקרי חוטא אלא בתורם מן הרע על היפה, משא\"כ זה שצריך לתרום מן היפה על הרעה (וכן מן המובחר ביפה גופא) הוי רק למצוה מן המובחר (כיון דלא נזכר בזה נשיאות חטא, ואין בו אלא חידושו)<sup data-n=\"e22\">*</sup>. וראה לקמן הערה 32 בשוה\"ג."],["1020","29","להעיר מספרי זוטא (פרשתנו יח, כט) \"ממנו — שלא יפריש תרומה ממין על שאינו מינו, שלא יטול מן הרע על היפה\", שמשמע, שגדר האיסור שלא ליטול מן הרע על היפה הוא ע\"ד האיסור ליטול ממין על שאינו מינו. והיינו שאין האיסור מפני שמפריש מן הרע, אלא מפני שאין ההפרשה מן הרע יכולה להתיר את היפה, ע\"ד מין על שאינו מינו."],["1021","30","משא\"כ לדרשת הספרי \"ממנו — ממינו\" (כנ\"ל בפנים סוס\"א)."],["1022","31","פרשתנו יח, כט (שפסוק זה הובא בש\"ס — תמורה ה, א). שם, יב (הובא לענין זה בתוס' (ד\"ה אם) קידושין מז, רע\"א)."],["1001","11","תרומות פ\"ב מ\"ד."],["1024","32","הל' תרומות רפ\"ה. וראה גם הל' מעשר פ\"א הי\"ג.\nועפ\"ז י\"ל שהרמב\"ם והרמב\"ן לשיטתייהו אזלי: להרמב\"ם ש\"לא תשאו עליו חטא\" אינו לאו בפ\"ע אלא \"שלילת החיוב\" (כנ\"ל הערה 27), אין חילוק בין החיוב להרים מן היפה ו\"לא תשאו עליו חטא\", ש­שניהם איירי באותו ענין (וראה ל' הרמב\"ם שם); משא\"כ להרמב\"ן, ש\"ולא תשאו עליו חטא\" הוא לאו בפ\"ע, ס\"ל שהעשה והלאו איירי בגוונים שונים<sup data-n=\"e23\">*</sup>, כבפנים."],["e22","*","ועפ\"ז י\"ל, שגם לרבא (ראה תוד\"ה אם שם ובקידושין מו, ב), יש חילוק (למסקנא) בין העשה והל\"ת, כבפנים. ואכ\"מ."],["e23","*","אף שגם בהמ\"ע כ' \"שנפריש אותה. . או מן השוה\" — י\"ל (בדוחק עכ\"פ) שזהו מפני שבהמשך דבריו מוסיף גם השלילה, \"לא מן הרעה על היפה\", שאיסור זה אינו כשתורם \"מן השוה\" [דכיון שגבי הל\"ת (\"ולא תשאו עליו חטא\") מודגש שהאיסור הוא רק בתורם מן הרעה על היפה, מסתבר, שכ\"ה גם לגבי העשה, שאין איסור עשה (לאו הבא מכלל עשה) אלא בתורם מן הרעה על היפה; והחיוב לתרום מן המובחר ביותר הוא רק לכתחילה ולהידור, כנ\"ל בפנים]."]]],[1301430182,"אלא מן היפה שנאמר בהרימכם<sup data-n=\"1025\">33</sup> את חלבו ממנו\" — שיש לפרש כוונתו, שה­חיוב לתרום מן היפה אינו רק הידור מצוה, אלא שיש איסור לתרום שלא מן המובחר (\"אין תורמין אלא מן היפה\"), וכלשון הספרי הנ\"ל \"שלא יהו תורמים אותו אלא מן המובחר\"<sup data-n=\"1026\">34</sup>.\nה. ויש לומר, ששני אופנים אלה (אם הפרשה שלא מן המובחר הוא בנשיאות חטא) — תלויים בגדר החיוב לתרום מן היפה.\nדהנה בסוף הל' איסורי מזבח כתב הרמב\"ם \"שהרוצה לזכות עצמו יכוף יצרו הרע וירחיב ידו ויביא קרבנו מן היפה המשובח ביותר כו' והוא הדין בכל דבר שהוא לשם הא­ל הטוב שיהי' מן הנאה והטוב, אם בנה בית תפלה יהי' נאה מבית ישיבתו כו' הקדיש דבר יקדיש מן היפה שבנכסיו וכן הוא אומר<sup data-n=\"1027\">35</sup> כל חלב לה' וגו'\".\nויש לחקור אם החיוב דתרומה מן היפה (\"בהרימכם את חלבו ממנו\") אינו אלא פרט מהחיוב הכללי ד\"כל חלב לה'\", או שזהו דין מיוחד גבי תרומה.\nוי\"ל דבזה פליגי הש\"ס והספרי:\nלשיטת הש\"ס חיוב זה אינו אלא פרט מהדין הכללי ד\"כל חלב לה'\", ולכן אין לומר דכשאינו מקיים זה הרי הוא בכלל \"נשיאות חטא\", שהרי דין כללי זה אינו אלא הידור למי ש\"רוצה לזכות עצמו\" (כמ\"ש הרמב\"ם שם). ולכן ס\"ל להש\"ס שרק כשתורמים מן הרע על היפה הוי \"נשיאות חטא\", שאז הוא בזיון התרומה, ששירי' הם יפים והתרומה (המתירה את השיריים) היא מן הרע.\nמשא\"כ לשיטת הספרי, שהדין ד\"בה­רימכם את חלבו ממנו\" הוא דין מיוחד בתרומה, מובן שזהו חיוב גמור להפריש מן המובחר, ובמילא, כשאין מפרישים מן המובחר \"אתם בנשיאות עון\".\nו. ואולי יש לומר עוד, ובהקדם פלוגתת ת\"ק ור' יהודה (הנ\"ל ריש סעיף ב) אם כשאין כהן תורמין מן המתקיים או לעולם תורמין מן היפה גם כשאין כהן.\nשיש לבאר דפליגי אם החיוב לתרום מן היפה הוא תנאי בההפרשה או תנאי בהנתינה לכהן<sup data-n=\"1028\">36</sup>:\nר' יהודה הסובר שלעולם תורמים מן היפה (גם כשאינו מתקיים) טעמו — כי חיוב זה הוי דין בהפרשת התרומה, כי",[["1025","33","וג\"ז הוא כהספרי, ולא כבש\"ס שהביא (כנ\"ל הערה 31) הכתוב ד\"מכל חלבו\" (אלא שבסהמ\"צ (מ\"ע קכט) גם הרמב\"ם הביא \"מכל חלבו\")."],["1026","34","ולהעיר מלשון הרמב\"ם בסהמ\"צ שם, \"כשיוציאוהו מן הרע יחטאו\" [ולא כ' כלשון המשנה \"מן הרע על היפה\"], וממשיך בהעתק לשון הספרי."],["1027","35","ויקרא ג, טז."],["1028","36","להעיר מצפע\"נ על הרמב\"ם ריש הל' כלאים (ב, סע\"ג) ובהשמטות לשם (נדפסו לאחרי הל' מתנ\"ע — א, א)."]]],[1301430183,"תוכן ענין הפרשת תרומה הוא — ה­הפרשה לה'<sup data-n=\"1029\">37</sup>, כלשון הכתוב<sup data-n=\"1030\">38</sup> \"כל חלב יצהר גו' אשר יתנו לה' לך נתתים\", \"כן תרימו גם אתם תרומת ה'\" (אלא שאח\"כ נותנים אותה לכהנים), ולכן חל על עצם ההפרשה חיוב שתהי' מחלבו (ע\"ד \"כל חלב לה'\"), ומטעם זה ס\"ל לר' יהודה ד­אע\"פ שאינו מתקיים לא חיישינן לפסי­דא דכהן, כי העיקר הוא שההפרשה לה' תהי' מן היפה<sup data-n=\"1031\">39</sup>.\nמשא\"כ הת\"ק ס\"ל שזהו בעיקר בשביל הכהן, שהנתינה אליו תהי' מן ה­יפה<sup data-n=\"1032\">40</sup>, כדי שהספקת צרכיו על ידי בנ\"י תהי' באופן היותר טוב, מן היפה וה­מובחר. ולאופן זה אם היפה אינו מתקיים דין קדימה להמתקיים.\nועפ\"ז יש לומר, שהשאלה הנ\"ל (אם החיוב להפריש תרומה מן המובחר הוא חלק מהחיוב הכללי ד\"כל חלב לה'\" או לא) תלוי בגדר ד\"כל חלב לה'\".\nדהנה נת' במ\"א<sup data-n=\"1033\">41</sup> בביאור שיטת ה­רמב\"ם שלא הביא הא ד\"התנאה לפניו במצות\"<sup data-n=\"1034\">42</sup> (שנלמד מ\"זה א­לי ואנוהו\"<sup data-n=\"1035\">43</sup>) אלא רק הדין ד\"כל דבר שהוא לשם הא­ל הטוב יהי' מן הנאה והטוב, אם בנה בית תפלה יהי' נאה מבית ישיבתו כו' הקדיש דבר יקדיש מן היפה שב­נכסיו וכן הוא אומר כל חלב לה' וגו'\" — שהכוונה בזה לדבר שהוא דומה לקרבן ע\"ג מזבח (קרבן לה'), שמוסר את הדבר לה', כמו \"בנה בית תפלה\", \"הקדיש דבר\" [וגם הדוגמאות שברמב\"ם שם ד­\"האכיל רעב כו' כסה ערום\" הוא מפני שאיירי בצדקה שהיא לכפרה<sup data-n=\"1036\">44</sup>], שבזה צ\"ל \"מן היפה שבנכסיו\", כי זה נוגע להחפצא, שע\"י שהדבר הוא \"מן היפה\" הרי ההקרבה לה' היא בשלימות וב­הידור יותר.\nולפי זה מבוארת שיטת הרמב\"ם בנדו\"ד (הפרשת תרומה מן היפה): כיון שנקטינן להלכה כת\"ק שכשאין כהן תורמין מן המתקיים, והיינו מפני שזהו דין בנתינה לכהן, נמצא, שאין דין זה שייך לחיוב הכללי ד\"כל חלב לה'\" (שזהו רק ב\"כל דבר שהוא לשם הא­ל\"), ולכן ס\"ל להרמב\"ם שזהו דין חדש ו­מיוחד גבי הפרשת תרומה שצריכים לתת לכהן מן היפה, וכיון שזהו דין מיוחד בתרומה ס\"ל ג\"כ שאינו רק הידור לכתחילה, אלא דאם אין מקיימים דין זה יש בו נשיאות עון (כשיטת הספרי), ולכן כתב \"אין תורמין אלא מן היפה\", כנ\"ל.\nמשא\"כ לשיטת הש\"ס, שיש חיוב דהידור מצוה בכל המצות, \"התנאה ל­פניו במצות\" (וי\"ל שלשיטת הש\"ס אין חילוק בין דין הידור מצוה בכלל, והחיוב ד\"כל חלב לה'\"), ולכן ס\"ל שה­חיוב לתרום מן היפה הוא רק פרט בחיוב הכללי דהידור מצוה ו\"כל חלב לה'\"<sup data-n=\"1037\">45</sup>, ולכן אא\"פ לומר שבגלל זה",[["1029","37","ראה ספרי פרשתנו (יח, כא) כל מצות כהונה קנאו השם ונתנו לכהונה. וראה מגילת אסתר ומרגניתא טבא לסהמ\"צ שורש יב. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081034\" data-slug=\"likkutei-sichot\" data-id=\"1300081034\">לקו\"ש ח\"ח ע' 34</a> ובהערות שם. חי\"ח ע' 223. ועוד."],["1030","38","פרשתנו יח, יב. שם, כח (ושם, כו)."],["1031","39","ולהעיר מהשקו\"ט במפרשי הספרי (סוף פרשתנו) ועוד, אם חייבים לתרום מן היפה בתרומה טמאה ההולכת לאיבוד. וראה צפע\"נ הנ\"ל."],["1032","40","וכן משמע מדיוק ל' רש\"י (ב\"מ כב, א ד\"ה כלך) \"הי' לך לילך אצל יפות לתת מהן לכהן\"."],["1033","41","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300271010\" data-slug=\"likkutei-sichot\" data-id=\"1300271010\">לקו\"ש חכ\"ז ע' 10</a> ואילך ובהערות שם."],["1034","42","שבת קלג, ב."],["1035","43","בשלח טו, ב."],["1036","44","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300271014\" data-slug=\"likkutei-sichot\" data-id=\"1300271014\">לקו\"ש שם ע' 14</a> ובהערות שם. וש\"נ."],["1037","45","ראה של\"ה (שבהערה 7) \"המצוה מהמובחר ליתן חלק הכהנים מן המובחר ביותר, וכן אלו ה­נותנים מעות לקופה של צדקה או לעני יתנו מטבע המובחרת כו'\".\nולהעיר ג\"כ שהדין ד\"כל חלב לה'\" שברמב\"ם (סוף הל' איסורי מזבח) — הועתק (בשינוי לשון קצת) בשו\"ע הל' צדקה (יו\"ד סו\"ס רמח), אף שלכאורה הי' מקום להביאו לפנ\"ז בהל' בית הכנסת (או\"ח סק\"נ ואילך), כהדוגמא \"בנה בית תפלה\". וי\"ל של­דעת הב\"י הדין ד\"כל חלב לה'\" אינו רק בדברים שהם דומים לקרבן ע\"ג מזבח, אלא בכל מצוה<sup data-n=\"e24\">*</sup>, והוא דין אחד עם כללות החיוב דהידור מצוה (שהובא בשו\"ע או\"ח סתרנ\"ו לענין אתרוג \"עד שליש\", משא\"כ ברמב\"ם שהשמיט דין זה). ולכן הביאו בהל' צדקה דוקא, שאין מוסרים לשמים כ\"א לעני."],["e24","*","ואולי י\"ל שזהו טעם השינוי, שברמב\"ם כתב \"כל דבר שהוא לשם הא­ל\", ובשו\"ע \"לשם שמים\", ד\"לשם הא­ל\" משמעו דבר שמוסרים לה', כקרבן ע\"ג מזבח, משא\"כ \"לשם שמים\" משמעו כל ענין של עבודת השם."]]],[1301430184,"שאינו מן המהדרים תהי' בזה \"נשיאות חטא\".\nז. והנה יש עוד שינוי בין לשון הספרי ולשון הש\"ס, דבש\"ס הלשון \"ואם אין קדוש נשיאות חטא למה\" (והוא כלשון הכתוב עצמו \"ולא תשאו עליו חטא\"), אבל בספרי משנה ואומר \"שאתם בנשיאות עון\", וידוע ד\"עון\" חמור יותר מן החטא<sup data-n=\"1038\">46</sup>.\nוהנה אע\"פ שנת\"ל שדין זה (שרק משום שחסר \"מן המובחר\" יש בזה \"נשיאות עון\") הוא רק בתרומה — מ\"מ, יש ללמוד מזה גם לגבי שאר מצוות התורה החומר כשחסר בהידור מצוה — דאע\"פ שאין לחייבו ולכופו על הידור, מ\"מ, כשאינו מהדר במצות, אין זה רק שחסרה בו המעלה דהידור מצוה, אלא שיש בזה (מעין) נשיאות עון<sup data-n=\"1039\">47</sup> (שנחשב לחסרון בהמצוה עצמה).\nומרובה מדה טובה כו' — דכאשר מקיימים מצות בהידור, הרי נוסף על השכר עבור ההידור מצוה, יש הוספה בשכרה של המצוה עצמה.\n<span data-k=\"q\">(משיחות ש\"פ קרח תשכ\"ד, כ\"ף מנ\"א תשמ\"ה)</span>",[["1038","46","ראה יומא לו, ב. ובכ\"מ."],["1039","47","וראה שו\"ע אדה\"ז או\"ח (סתפ\"א ס\"א) \"והאוכל והשותה (אחר כוס ד) אין עליו כלום, אלא שנמצא מוציא עצמו מכלל המהדרין ועובר על דברי חכמים שאמרו (ברכות מט, סע\"ב) לעולם אל יוציא אדם עצמו מן הכלל\"."]]],[1301430185,"<h3>שיחה א</h3>\nא. \"זאת חוקת התורה גו' ויקחו אליך פרה אדומה גו'\"<sup data-n=\"1040\">1</sup>, וארז\"ל<sup data-n=\"1041\">2</sup> בטעם הדיוק \"ויקחו אליך\" (למשה דוקא) \"שכל ה­פרות בטלות ושלך קיימת\", וזה נוגע (לא רק לפרת משה, אלא) לכל הפרות ה­אדומות שבכל הדורות, כי בכולם נת­קדשו הכהנים שעשו את הפרה מאפר פרתו של משה<sup data-n=\"1042\">3</sup>, ולכן נקראו כל הפרות ע\"ש משה דוקא<sup data-n=\"1043\">4</sup>.\nוהשייכות המיוחדת של פרה אדומה למשה רבינו מודגשת גם בנוגע לטעם מצוה זו, דאע\"פ שאפילו שלמה המלך [ש\"על כל אלה (כל חוקי התורה) עמד­תי\"<sup data-n=\"1044\">5</sup>] אמר על מצוה זו \"והיא רחוקה ממני\"<sup data-n=\"1045\">6</sup> — מ\"מ, למשה רבינו נתגלה טעם פרה, כמחז\"ל<sup data-n=\"1046\">7</sup> על תיבות אלו \"ויקחו אליך\" — \"לך אני מגלה טעם פרה\".\nוצריך להבין — מה נשתנתה מצוה זו מכל מצות התורה, שבה מודגשת שייכו­תה למשה רבינו, הן באופן קיומה, ש­קיום מצוה זו (גם לדורות) הוא ע\"י אפר פרתו של משה, והן באופן לימודה, \"לך אני מגלה טעם פרה\"<sup data-n=\"1047\">8</sup>?\nב. ויש לבאר זה בהקדים מה שאמרו רז\"ל<sup data-n=\"1048\">9</sup> (בטעם שפרה אדומה היא נקבה, דלא ככל קרבנות ציבור שהם זכרים) — \"אמר הקב\"ה תבא פרה ותכפר על מעשה העגל\" (ובפרש\"י על התורה<sup data-n=\"1049\">10</sup> מ­יסודו של ר' משה הדרשן, גם פרטי הרמזים במצות פרה אדומה על כפרת חטא העגל).\nוביארו המפרשים<sup data-n=\"1050\">11</sup> השייכות בין כפרת חטא העגל להטהרה מטומאת מת (ענינה של פרה אדומה כפשוטה) — ע\"פ דברי חז\"ל<sup data-n=\"1051\">12</sup> שלולא חטא העגל לא הי' כל ענין המיתה אצל בנ\"י, כי היתה \"חי­רות ממלאך המות\" (כמו לפני חטא עץ הדעת, שהרי בעת מ\"ת פסקה זוהמתן<sup data-n=\"1052\">13</sup>, אלא שע\"י חטא העגל חזרה זוהמתן<sup data-n=\"1053\">14</sup>), ונמצא שחטא העגל הי' סיבה (לענין ה­",[["1040","1","ריש פרשתנו (יט, ב)."],["1041","2","תנחומא פרשתנו ח. במדב\"ר פי\"ט, ו. וראה רש\"י יומא ד, רע\"א. וראה הנסמן בהערה הבאה."],["1042","3","ראה פרה פ\"ג מ\"ה \"ומאחת\" (ועד\"ז הוא ל' הרמב\"ם הל' פרה אדומה פ\"ב ה\"ו) ובמשנה אחרונה שם (ע\"פ תוי\"ט שם מ\"ג). ולהעיר ג\"כ מפי' מהרז\"ו לבמדב\"ר שם. ביאורי מהרא\"י (לבעל תרוה\"ד) ושפ\"ח (לפרש\"י פרשתנו שם). של\"ה חלק תושב\"כ פרשתנו (שנט, ב). וראה לקמן הערה 36."],["1043","4","של\"ה, ביאורי מהרא\"י ושפ\"ח שבהערה הקודמת."],["1044","5","תנחומא שם ו (קרוב לסופו). במדב\"ר שם, ג (בסופו)."],["1045","6","קהלת ז, כג. תנחומא ובמדב\"ר שם."],["1046","7","תנחומא שם, ח. במדב\"ר שם, ו. וראה ידי משה שם."],["1047","8","בכלי יקר ריש פרשתנו מבאר השייכות למשה מצד הענין דכפרת חטא העגל, ע\"ש (וראה לקמן סעיף ב). אבל עדיין צריך ביאור השייכות למשה מצד הענין דטהרה מטומאת מת (כפשוטה)."],["1048","9","תנחומא שם ח (בסופו). במדב\"ר שם, ח (בסופו). וראה גם תוד\"ה מי — מו\"ק (כח, רע\"א)."],["1049","10","בסוף פרשת פרה אדומה (יט, כב)."],["1050","11","כלי יקר, אלשיך, ש\"ך עה\"ת, עץ הדעת טוב (להרח\"ו) ועוד פרשתנו."],["1051","12","שמו\"ר רפל\"ב. זח\"א לז, סע\"ב. קלא, סע\"ב. ועוד."],["1052","13","שבת קמו, רע\"א."],["1053","14","זח\"א נב, ב. קכו, ב. זח\"ב קצג, סע\"ב. ועוד."]]],[1301430186,"מיתה, ובמילא — גם) לטומאת מת; וזהו הקשר בין שני הענינים דכפרת חטא ה­עגל וטהרה מטומאת מת — דהא בהא תליא, שע\"י כפרת חטא העגל, מתבטל בדרך ממילא הענין דטומאת מת (ע\"י שבטלה הסיבה לטומאת מת — מיתה בכלל).\nובזה יש לבאר (ע\"ד הדרוש) דיוק ל' הרמב\"ם<sup data-n=\"1054\">15</sup> \"ותשע פרות אדומות נעשו משנצטוו במצוה זו עד שחרב הבית ב­שניי', ראשונה עשה משה כו' והעשירית יעשה המלך המשיח\" — דלכאורה אינו מובן: מה טעם הוצרך הרמב\"ם לכתוב מספר<sup data-n=\"1055\">16</sup> הפרות שנעשו במשך כל ה­דורות?\nכן צע\"ק: הרמב\"ם לא הסתפק ב­הבאת מספר הפרות שהובא במשנה<sup data-n=\"1056\">17</sup>, אלא מוסיף<sup data-n=\"1057\">18</sup> \"והעשירית יעשה המלך ה­משיח\" — הרמב\"ם הביא בספרו גם הלכ­תא למשיחא, שאז \"חוזרין כל המשפטים. . כשהיו מקודם, מקריבין קרבנות כו'\"<sup data-n=\"1058\">19</sup>, אבל למה הבדיל הרמב\"ם פרה העשירית מכל הענינים והקרבנות של \"הנשיא\" — שבנבואת יחזקאל<sup data-n=\"1059\">20</sup>, וכותב שהמלך המשיח יעשה הפרה העשירית?\nוע\"פ הנ\"ל יש לומר — שבזה מרמז הרמב\"ם, ששלימות הטהרה על ידי פרה אדומה בכלל תהי' רק בפרה העשירית שתיעשה על ידי המלך המשיח. כי אין כפרה גמורה לחטא העגל (כמש\"נ<sup data-n=\"1060\">21</sup> \"וב­יום פקדי ופקדתי גו'\") עד לעת\"ל, ורק אז, כשתוגמר הכפרה על מעשה העגל, אז תבוא שלימות הטהרה מטומאת מת, כי יבוטל אז כל ענין המיתה (כמ\"ש<sup data-n=\"1061\">22</sup> בלע המות לנצח), שהיא הסיבה לטומאת מת כנ\"ל<sup data-n=\"1062\">23</sup>.\nוזהו הרמז בהרמז ש\"העשירית יעשה המלך המשיח\" — כי עשר הוא מספר ה­שלם (כנודע<sup data-n=\"1063\">24</sup>), ושלימות ה(טהרה ד)פרה אדומה תהי' רק לעת\"ל, בפרה שיעשה המלך המשיח.\nג. עפ\"ז יש לבאר גם השייכות דפרה אדומה \"אליך\" למשה רבינו:\nיסוד הטהרה של פרה אדומה אינו רק ביטול הטומאה בפועל, אלא ביטול סיבת הטומאה מעיקרא — ענין המיתה. ולכן צריכים בזה לכחו של משה<sup data-n=\"1064\">25</sup> — כי מעניניו המיוחדים של משה הוא ענין הנצחיות, כמבואר בחז\"ל<sup data-n=\"1065\">26</sup> שמעשי ידי",[["1054","15","הל' פרה אדומה ספ\"ג. — ביאור הלכה זו ע\"ד ההלכה ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300281131\" data-slug=\"likkutei-sichot\" data-id=\"1300281131\">לקו\"ש חכ\"ח ע' 131</a> ואילך."],["1055","16","בפשטות י\"ל — להודיע שצריך להביא מתשע פרות ולא משבע כדברי ר\"מ."],["1056","17","פרה פ\"ג מ\"ה."],["1057","18","וצ\"ע וחיפוש מקורו דהרמב\"ם. ולהעיר מכו\"כ ענינים שהעשירי הוא בימוה\"מ (או ע\"י משיח) — שירה העשירית, מנין העשירי דבנ\"י, כיבוש ארץ עשר אומות, עשר נימין דכינור המקדש וכו'. וראה מדרש מעשה תורה אות יו\"ד."],["1058","19","ל' הרמב\"ם הל' מלכים רפי\"א. וצע\"ק אם ואיך יקריבו קרבנות קודם עשית פרה העשירית וטהרת ג' וז'."],["1059","20","מה, יז ואילך. — וראה רמב\"ם הל' מעה\"ק ספ\"ב."],["1060","21","תשא לב, לד ובפרש\"י שם. סנהדרין קב, סע\"א. ועוד."],["1061","22","ישעי' כה, ח. משנה סוף מו\"ק. זח\"א קטו, סע\"א. — וראה סה\"מ תרכ\"ח ע' מ ואילך. סה\"מ מלוקט ח\"ב ע' רעז ואילך."],["1062","23","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600523\" data-slug=\"or-hatorah-hb\" data-id=\"8316600523\">אוה\"ת לנ\"ך (ס\"ע תקכג</a> ואילך) ד\"מעשה פרה רומז על הגאולה דלע\"ל ולכן מטהרת טומאת מת שאזי ומחה ה'. . ובלע המות לנצח\". ע\"ש. וראה אוה\"ת פרשתנו ס\"ע תתט."],["1063","24","ראה ראב\"ע לשמות ג, טו. פרדס שער ב'."],["1064","25","וראה עץ הדעת טוב פרשתנו, שענין התורה שניתנה ע\"י משה בא \"לכפר עון אדה\"ר לבטל ה­מיתה\". ע\"ש."],["1065","26","ראה סוטה ט, סע\"א. תנא דבא\"ר פי\"ח. צפע\"נ עה\"ת ר\"פ תרומה. ועוד."]]],[1301430187,"משה הם נצחיים (וכמו שמצינו בנדו\"ד, פרה אדומה גופא, שאפר פרה שלו הוא מתחלת הענין, וגם — קיים לעד), ועד\"ז בנוגע למשה עצמו, אף שנאמר וימת שם משה<sup data-n=\"1066\">27</sup> אמרו עליו<sup data-n=\"1067\">28</sup> \"לא מת משה. . מה להלן עומד ומשמש אף כאן כו'\". ולכן הטהרה של כל פרה ופרה תלוי' באפרו של פרת משה — כי כח הטהרה של פרה אדומה קשור עם ענין הנצחיות של משה רבינו<sup data-n=\"1068\">29</sup>.\nולהעיר, שאע\"פ שענין הטהרה מ­טומאת מת בשלימותו לא יושג עד לעת\"ל כשיבולע המות לנצח (ועד אז הפרה מטהרת מן הטומאה, אבל אין בכחה לבטל סיבת הטומאה) — זהו רק בנוגע ליחיד, אבל בנוגע לציבור — ע\"י תורה, שקיבל משה מסיני ומסרה כו', נעשית מציאות ציבור, אשר \"אין הציבור מתים\"<sup data-n=\"1069\">30</sup>, שבציבור דבנ\"י לא שייך ענין המיתה.\nד. והנה \"התורה היא נצחית\"<sup data-n=\"1070\">31</sup> בכל זמן ובכל מקום. שמזה מובן, דאע\"פ ש­עכשיו אין לנו אפר פרה, מ\"מ, תוכן הענין דטהרת פרה אדומה, שכולל אפר פרתו של משה, ישנו בעבודה הרוחנית של כאו\"א מישראל.\nהסברת הענין:\nהמשכת הנצחיות של משה היתה ע\"י שהי' בתכלית הביטול להקב\"ה (\"עבד נאמן\"<sup data-n=\"1071\">32</sup>), ענין המסירת נפש, שמוכן למסור כל מציאותו עבורו ית'. וי\"ל ש­לכן מעשי ידי משה נצחיים המה — כי מסירת נפש היא למעלה משינויים, שהרי כל ענין המסירת נפש הוא — התוקף לעשות רצונו ית' באופן ששום דבר שב­עולם לא יוכל לשנותו.\nולכן הטהרה מטומאת מת היא בכח אפר פרתו של משה: טומאת מת מורה על הפירוד מקדושה, כי כאשר \"דבקים בה' אלקיכם (הרי אתם) חיים כולכם היום\"<sup data-n=\"1072\">33</sup> (אין שייך מיתה, ובמילא לא טומאת מת); וכדי לבטל מכל וכל את ה­\"מיתה\" והפירוד מקדושה, שיהי' תכלית הדביקות בה' אלקיכם — ה\"ז ע\"י שה­אדם מעורר בעצמו את מסירת נפשו לה'<sup data-n=\"1073\">34</sup>.\nוכמו שהנצחיות באפר פרתו של משה באה בשני ענינים — (א) שהוא עצמו קיים לעד<sup data-n=\"1074\">35</sup>, (ב) כל הפרות היו צריכות",[["1066","27","ברכה לד, ה."],["1067","28","סוטה יג, סע\"ב. זח\"א לז, סע\"ב ואילך. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261006\" data-slug=\"likkutei-sichot\" data-id=\"1300261006\">לקו\"ש חכ\"ו (ע' 6</a> ואילך) החידוש בזה לגבי המדובר במרז\"ל (ברכות יח, סע\"א ואילך) שצדיקים (בכלל) גם במיתתם קרויים חיים."],["1068","29","וי\"ל שזהו גם הטעם שהרמב\"ם הזכיר רק משה ועזרא ולא העתיק מהמשנה (פרה שם) שמות עושי ז' הפרות לאחרי עזרא — כי כח הטהרה שב­פרה אדומה יסודו מפרתו של משה, כבפנים (ועזרא שקול כמשה ומסר תורה לכל ישראל ונקרא הסופר וכו' — ראה סנהדרין כא, סע\"ב. ועוד)."],["1069","30","הוריות ו, א. תמורה (טו, ב. טז, סע\"א). רמב\"ם הל' פסולי המוקדשין פ\"ד סה\"א (וצע\"ק שינוי ל' הרמב\"ם \"ואין כל ישראל מתים\", ובפרט ע\"פ דעתו דשבט אינו כלה (עיין צפע\"נ להל' קדוה\"ח ספ\"ה בפי' דברי הרמב\"ם בסהמ\"צ מ\"ע קנג — ע\"פ ב\"ב קטו, ריש ע\"ב וברשב\"ם שם))."],["1070","31","ל' התניא — רפי\"ז. שם קו\"א סד\"ה להבין פרטי ההלכות. וראה סה\"מ מלוקט ח\"ב ע' שיב הערה 17 בשוה\"ג."],["1071","32","נוסח תפלת העמידה דשחרית דשבת. וראה בהעלותך יב, ז."],["1072","33","ואתחנן ד, ד."],["1073","34","ראה גם לקו\"ש ח\"ד ע' 1058 ואילך. ולהעיר מ<a class=\"ft-cite\" href=\"#/read/tanya/3401310024\" data-slug=\"tanya\" data-id=\"3401310024\">תניא פי\"ט (כד, ב</a>) בענין \"החכמה תחי'\". וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181242\" data-slug=\"likkutei-sichot\" data-id=\"1300181242\">לקו\"ש חי\"ח ע' 233</a> ואילך."],["1074","35","ולהעיר, שגם ההשתמשות באפרו של פרת משה נתארכה ריבוי שנים, שהרי עד ימי עזרא לא הוצרכו לפרה שני' — קרוב לאלף שנה השתמשו בפרתו של משה (ואילו במשך השנים דבית שני — ת\"כ שנה — עשו שמונה פרות!)."]]],[1301430188,"לאפר פרתו של משה<sup data-n=\"1075\">36</sup> — עד\"ז הוא ב­עבודה רוחנית, שבהתעוררות כח המסי­רת נפש יש שני ענינים: (א) ההתעוררות של עצם כח המסירת נפש, (ב) מה שכח המסירת נפש נותן כח ועוז בכל עניני עבודת ה' שיהיו כדבעי, וכמבואר ב­תניא<sup data-n=\"1076\">37</sup>, \"שקיום התורה ומצותי' תלוי בזה שיזכור תמיד ענין מסירת נפשו לה'. . שיהי' קבוע בלבו תמיד ממש יומם ו­לילה לא ימיש מזכרונו כי בזה יוכל לעמוד נגד יצרו לנצחו תמיד בכל עת ובכל שעה\".\nובעבודת האדם מדי יום ביומו — הוא החילוק בין עבודת התפלה ושאר עניני עבודת ה' במשך כל היום כולו:\nבשעת התפלה צריך האדם לעורר את אהבתו לה' המסותרת בלבו, שענינה של אהבה זו (כמבואר בארוכה בספר ה­תניא<sup data-n=\"1077\">38</sup>) — הרצון והחפץ לידבק בה' אחד עד כדי מסירת נפש [ואהבה זו נטועה בלב כאו\"א מישראל, להיות נפשו \"חלק אלקה ממעל ממש\"<sup data-n=\"1078\">39</sup>, ש\"ה' אחד\" מאיר בהחלק באופן גלוי; אלא שהיא מסותרת בלבו, ועבודת האדם, לעורר אהבה זו ולהביאה לידי גילוי];\nואח\"כ, במשך כל היום, שאז אין ה­אדם עסוק בעבודת המסירת נפש (כשל­עצמה), אלא \"בקיום התורה ומצותי'\", מ\"מ גם אז צ\"ל זכרון \"ענין מסירת נפשו לה'\", שעי\"ז \"יוכל לעמוד נגד יצרו ל­נצחו תמיד בכל עת ובכל שעה\" — דבי­קות תמידית ונצחית בה', ואז — \"חיים כולכם היום\".\n<span data-k=\"q\">(משיחת ש\"פ חוקת תשכ\"ג)</span>",[["1075","36","ובפרט ע\"פ מ\"ש במפרשים שבכל הפרות היו צריכין לערב מאפר פרתו של משה (ראה ש\"ך עה\"ת ושפ\"ח פרשתנו (יט, ב). עץ הדעת טוב שם. ועוד). — ובפני דוד (להחיד\"א) פרשתנו, ש\"כעת לא נתברר לי זה שמערבין בכל פרה מאפר פרה שעשה משה\"."],["1076","37","ספכ\"ה."],["1077","38","פי\"ח­יט."],["1078","39","<a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a>."]]],[1301430189,"<h3>שיחה ב</h3>\nא. בפירושו על הפסוק<sup data-n=\"1079\">1</sup> \"וישלח ישראל מלאכים אל סיחון מלך האמורי\", מעתיק רש\"י \"וישלח ישראל מלאכים\", ומפרש: ובמקום אחר תולה השליחות ב­משה שנאמר<sup data-n=\"1080\">2</sup> ואשלח מלאכים ממדבר קדמות וכן וישלח משה מלאכים מקדש אל ארץ אדום<sup data-n=\"1081\">3</sup> וביפתח הוא אומר<sup data-n=\"1082\">4</sup> ו­ישלח ישראל מלאכים אל מלך אדום וגו' הכתובים הללו צריכים זה לזה זה נועל וזה פותח שמשה הוא ישראל וישר­אל הם<sup data-n=\"1083\">5</sup> משה לומר לך שנשיא הדור הוא ככל הדור כי הנשיא הוא הכל.\nוהנה אף שלפי המשמעות השטחית כוונת רש\"י בפירוש זה היא לתווך ה­סתירות בין הכתובים (אם השליחות ל­סיחון או לאדום היתה ע\"י משה או ע\"י ישראל), הרי כבר נת' כמ\"פ בארוכה ש­אין זו דרכו של רש\"י לתרץ ולתווך סתירות ואי­הבנות שבכתובים אלא ל­אחרי, במקום שבו מתעוררת הסתירה וכיו\"ב. ולפי זה, עכצ\"ל שכוונת רש\"י כאן היא לבאר קושי המתעורר בפסוק דנן, אלא שלצורך זה עליו לבאר את כל הכתובים שמביא ומיישב בדרך אגב.\nויש לומר, שהקושי בכתוב כאן הוא — השינוי בין כתוב זה שבשליחות ל­סיחון (שנאמר בו \"וישלח ישראל מלאכים\") לכתוב שלפנ\"ז (המובא ברש\"י כאן) גבי השליחות למלך אדום \"וישלח משה מלאכים\"<sup data-n=\"1084\">6</sup> — וכדי לבאר שינוי זה מבאר רש\"י \"ובמקום אחר כו'\", שעי\"ז<sup data-n=\"1085\">7</sup> מתיישב (גם) שינוי זה.\nב. אמנם לכאורה יש להבין פרטי לשון רש\"י \"הכתובים הללו צריכים זה לזה זה נועל וזה פותח שמשה הוא ישר­אל וישראל הם משה לומר לך שנשיא הדור הוא ככל הדור כי הנשיא הוא הכל\":\nא) מהו תוכן ההקדמה \"הכתובים הללו צריכים זה לזה זה נועל וזה פותח\"<sup data-n=\"1086\">8</sup>?\n[ואף שלשון רש\"י מקורו במדרש<sup data-n=\"1087\">9</sup>, הרי: א) כבר נת' כמ\"פ שענינו של רש\"י לפרש פשש\"מ ולא להעתיק ולהודיע ל' המדרש, ובמקום שמעתיק דברי רז\"ל במדרש וכיו\"ב, הוא משום שלשון זה נוגע להבנת פשוטם של כתובים. וזהו גם כשכותב בפירוש \"רבותינו דרשו\" ו­כיו\"ב, ופשיטא שכן הוא כאשר מפרש הכתוב בלי לכתוב שמקור הפירוש הוא בדברי חז\"ל. ב) ועיקר: במדרש מתחיל הדרשה כאן \"כל דברי תורה צריכין זה לזה שמה שזה נועל זה פותח\", היינו",[["1079","1","פרשתנו כא, כא."],["1080","2","דברים ב, כו."],["1081","3","פרשתנו כ, יד."],["1082","4","שופטים יא, יז."],["1083","5","בדפוס שני וכמה כת\"י רש\"י (שתח\"י): הוא משה."],["1084","6","ראה גם משכיל לדוד כאן."],["1085","7","והיינו דהתחלת פרש\"י \"ובמקום אחר כו'\", הוא התחלת התירוץ."],["1086","8","להעיר שכל זה (מהתיבות \"הכתובים הללו\" עד \"הם משה\") ליתא בדפוס ראשון ובב' כת\"י רש\"י (שתח\"י)."],["1087","9","תנחומא פרשתנו כג. במדב\"ר פי\"ט, כח. ועד\"ז הוא בתנחומא (באבער) שם נב. ילקו\"ש פרשתנו עה\"פ (רמז תשסד קרוב לסופו)."]]],[1301430190,"שתוכן מאמר המדרש הוא ביאור כללי<sup data-n=\"1088\">10</sup> בדרך \"כל דברי תורה\"<sup data-n=\"1089\">11</sup>, אבל בפרש\"י שכוונתו רק לבאר פרטי פסוקים אלה, למאי נפק\"מ ההקדמה ש\"הכתובים הללו צריכים זה לזה זה נועל וזה פותח\"?].\nב) מהו כפל הלשון (והענין) \"שמשה הוא ישראל וישראל הם משה<sup data-n=\"1090\">12</sup> (לומר לך שנשיא הדור הוא ככל הדור)\"?\nג) כשם שבפרטי הענין כותב את שני הצדדים, \"שמשה הוא ישראל וישראל הם משה\", כך הו\"ל לכאורה לפרט ב­סיכום פירושו, לא רק \"שנשיא הדור הוא ככל הדור\" אלא גם \"וכל הדור הוא כמו הנשיא\" וכיו\"ב?\nד) מהו תוכן הטעם \"כי הנשיא הוא הכל\"<sup data-n=\"1091\">13</sup>, ומהי ההוספה בזה על מה שאמר לפנ\"ז \"שנשיא הדור הוא ככל הדור\"<sup data-n=\"1092\">14</sup>? ויתירה מזו — לכאו' ה\"ז סתירה מיני' ובי': בתחלה משמע שנשיא הדור הוא רק כמו כל הדור<sup data-n=\"1093\">15</sup> (ולא ממש \"כל ה­דור\"), ובהמשך כותב \"כי הנשיא הוא הכל\", שאינו רק \"ככל הדור\" בכ\"ף ה­דמיון, כ\"א \"הכל\" ממש?\nג. ויש להקדים ביאור דיוק לשון רש\"י \"ובמקום אחר תולה השליחות ב­משה שנאמר ואשלח כו'\", דלכאורה הו\"ל לקצר ולומר \"ובמקום אחר נאמר ואשלח\" וכיו\"ב.\nויש לומר, שבלשון זה מודגש הקושי בכתוב כאן ע\"פ פשש\"מ, שאותו בא רש\"י ליישב בפירושו.\nוהביאור בזה:\nזה שבכתוב דידן (בשליחות לסיחון) כתיב \"וישלח ישראל מלאכים\", ובכתוב הקודם (בשליחות למלך אדום) נאמר \"וישלח משה מלאכים\" — אין לפרש ה­כוונה בזה שהמשלח למלך אדום הי' משה והמשלח לסיחון הי' עם ישראל. כי\nפשוט ששילוח המלאכים אל מלך אדום הי' בשליחות עם ישראל, כהמשך כל הפרשה שם<sup data-n=\"1094\">16</sup> \"כה אמר אחיך ישראל גו'<sup data-n=\"1095\">17</sup> וירדו אבותינו מצרימה גו' ונצעק אל ה' וישמע קולנו גו'\", דכל תוכן ה­דיבורים הוא בנוגע עם ישראל<sup data-n=\"1096\">18</sup>, ומה שנאמר \"וישלח משה\" מובן בפשטות, כי כל מעשיהם של עם ישראל היו ונעשו על ידי משה, והוא הוא ששלח את המלאכים בפועל<sup data-n=\"1097\">19</sup>;\nולאידך — גם כשנאמר \"וישלח ישר­אל\" פשוט שהשילוח בפועל הי' על ידי",[["1088","10","להעיר גם ממרז\"ל (ירוש' ר\"ה פ\"ג ה\"ה. תוס' כריתות יד, סע\"א) \"ד\"ת עניים במקומן ו­עשירים במ\"א\"."],["1089","11","ולכן מסיים (בתנחומא ושמו\"ר שם) וכותב עוה\"פ \"הכתובים אלו צריכים זל\"ז\"."],["1090","12","ראה בהנסמן בהערה 8, שליתא שם תיבות אלו (ורק ממשיך — אחרי הביאו הפסוקים: אלא לומר לך שנשיא כו')."],["1091","13","וליתא בדפוס שני דרש\"י. וכן ליתא במדרשים הנ\"ל."],["1092","14","בא' מכת\"י רש\"י (שתח\"י) — אחרי הבאת הכתובים — \"ללמדך שנשיא הדור הוא הכל\" ותו לא."],["1093","15","כ\"ה בדפוסים שלפנינו וכ\"ה בדפוס שני (אלא שליתא שם ההמשך, כנ\"ל הערה 13). אבל בדפוס ראשון וכמה כת\"י רש\"י (שתח\"י) \"הוא כל הדור\" (כמו בתנחומא ושמו\"ר שם. ובתנחומא (באבער) ויל\"ש שם — כברש\"י שלפנינו)."],["1094","16","כ, יד­טז."],["1095","17","וראה פרש\"י שם: מה ראה להזכיר כאן אחוה כו'."],["1096","18","וראה שם גם בההמשך (כ, יט) \"ויאמרו אליו בנ\"י\"."],["1097","19","וראה עץ הדעת טוב (להרח\"ו) שם (כ, יד) להיפך, כי ישראל הם השולחים אמנם לפי עצת משה כו'."]]],[1301430191,"משה, ומה שנאמר \"וישלח ישראל\" הוא לפי שהשליחות היתה בשביל ומכל עם ישראל, ונעשית בפועל על ידי משה — ככל הדברים הנוגעים לכלל ישראל ש­היו ע\"י משה<sup data-n=\"1098\">20</sup>.\nועפ\"ז — השליחות לסיחון והשליחות למלך אדום אין ביניהם הבדל, אלא רק שינוי בלשון הכתובים.\nוזהו מה שמדייק רש\"י — \"ובמקום אחר תולה השליחות כו'\", שכוונתו, שה­שאלה בשינוי לשון הכתובים כאן אינה בנוגע למה שאירע בפועל (אם משה שלח המלאכים או ישראל), כ\"א רק במי תולה הכתוב השליחות, כלומר, מה טעם לשינוי לשון הכתוב — דגבי אדום תלה הכתוב השליחות במשה, וכאן תלה ה­כתוב השליחות בישראל,\nובפרט שלכאורה איפכא מסתברא, דאם בהשליחות למלך אדום, שבה מוד­גש בהכתובים שהשולח הוא כלל ישר­אל (\"כה אמר אחיך ישראל\"), נאמר שם \"וישלח משה\", עאכו\"כ שהי' צריך לומר כן בשליחות לסיחון (שאין בה הדגשה זו).\nד. והנה לכאורה הי' מקום לבאר ש­תליית השליחות במשה או בישראל אינה רק ענין צדדי (— בלשון הכתוב), אלא זה מבאר מי הי' יוזם השליחות (דמכיון שהשליחות באה ביוזמתו, הרי שהשלי­חות תלוי' בו)<sup data-n=\"1099\">21</sup>.\nוזהו טעם החילוק שבאדום תולה ה­כתוב השליחות במשה, וכאן — בישראל, כי שאני השליחות למלך אדום מהשלי­חות למלך סיחון<sup data-n=\"1100\">22</sup>:\nגבי אדום היתה השליחות ע\"פ ציווי ה'<sup data-n=\"1101\">23</sup>, ולכן תולה הכתוב השליחות במשה, שהוא עבד ושליח השם ששומע הוראת הקב\"ה ומקיימן בפועל (ועד שאין ה­כתוב צריך לכתוב שהשם ציוהו על כך, כי מובן מאליו שכן הוא, וכדמצינו<sup data-n=\"1102\">24</sup> בכמה מקומות שלא נאמר בתורה ציווי",[["1098","20","משא\"כ ע\"פ המדרש (ראה מדרש לק\"ט כאן), שלמלך אדום שלח משה, משא\"כ למלך סיחון שלחו ישראל (\"ברשות משה\", אבל לא משה עצמו). ע\"ש הטעם. ובאו\"א — ראה ש\"ך עה\"ת כאן."],["1099","21","וזה שבשילוח המרגלים מפורש בכתוב \"וישלח אותם משה\" (שלח יג, ג. טז. יז. יד, לו), אף שסיבתו הי' מצד זה \"שבאו ישראל ואמרו (דברים א, כב) נשלחה אנשים לפנינו\" (רש\"י ר\"פ שלח) — י\"ל כי מכיון שהקב\"ה אמר לו \"שלח לך — לדעתך, אני איני מצוה לך אם תרצה שלח\", הי' זה תלוי ברצונו של משה, ולכן נק' על שמו (ראה דברים א, כג \"וייטב בעיני הדבר ואקח גו'\"). ועוד ועיקר: שליחות ראשי י\"ב שבטים \"ראשי בני ישראל המה\" (שלח יג, ג) — אין מתאים לייחסה לבנ\"י, כ\"א למשה, נשיא הראשים. וראה המשך הכתוב דברים (שם) \"ואקח מכם שנים עשר אנשים גו'\"."],["1100","22","במושב זקנים עה\"ת כאן, דמה שלא שלח משה כאן (בסיחון) כמו בראשונה בהשליחות למלך אדום הוא \"כי ידע שיש לו למות\" (וצ\"ע במ\"ש שלא שלח משה, והרי מפורש ששלח בפ' דברים. ואולי כוונתו שלכן לא נאמר כן מפורש בתורה כאן). ובכל אופן מ\"ש בטעם שלא שלח \"כי ידע שיש לו למות\" הוא היפך פרש\"י מטות לא, ג \"אע\"פ ששמע שמיתתו תלוי' בדבר עשה בשמחה וכו'\" (ובנ\"י לא רצו ללכת — ראה פרש\"י שם, ה). ועד\"ז הוא במושב זקנים מטות שם, ב (אלא — שספר זה הוא ליקוט מכמה מפרשים). וראה מדרש הגדול ופנים יפות כאן."],["1101","23","בעץ הדעת טוב שם: השי\"ת לא ציוהו בכך כי אין רצונו ית' להכניסו לארץ אבל משה בעצמו ביקש לשלחם לסיבה הנ\"ל (שיוכל ליכנס לארץ).\nאבל ע\"ד הפשט אין הכרח לפרש, דמה שנאמר בתורה בהליכת בנ\"י אל א\"י — כוונת משה בזה היתה לפעול ביטול שבועת ה' (פרשתנו כ, יב) \"לא תביאו\". ובפשטות הי' זה כחלק מהנהגת משה את בנ\"י במדבר בדרך (שהם יכנסו לארץ). וראה פנים יפות שם, יד."],["1102","24","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300131072\" data-slug=\"likkutei-sichot\" data-id=\"1300131072\">לקו\"ש חי\"ג ע' 72</a>. וש\"נ."]]],[1301430192,"השם אל משה)<sup data-n=\"1103\">25</sup>; משא\"כ גבי סיחון, הרי מפורש ברש\"י כאן<sup data-n=\"1104\">26</sup> שהקב\"ה לא צוה לפתוח לו בשלום<sup data-n=\"1105\">27</sup>, וא\"כ יש מקום לו­מר, שמטעם זה נאמר \"וישלח ישראל\", ללמדנו, שבנ\"י הם הם שתבעו שליחות זו, ומשה הסכים על ידם<sup data-n=\"1106\">28</sup>, ולכן נאמר \"וישלח ישראל\".\nוכדי לשלול פירוש זה מתחיל רש\"י פירושו — \"ובמקום אחר תולה השליחות במשה שנאמר ואשלח מלאכים ממדבר קדמות\", היינו שמפורש ש(גם) שליחות זו — דמשה, ואין לייחס ולתלות אותה (רק) בישראל<sup data-n=\"1107\">29</sup>; ואח\"כ ממשיך רש\"י \"וכן וישלח משה מלאכים מקדש אל מלך אדום וביפתח הוא אומר וישלח ישראל מלאכים אל מלך אדום וגו'\" — כלומר, גם בשליחות למלך אדום אין כוונת הכתוב לתלות השליחות רק במשה (ולא בבנ\"י), שהרי מפורש \"וישלח ישראל\".\nוזהו שממשיך רש\"י \"הכתובים הללו צריכים זה לזה זה נועל וזה פותח ש­משה הוא ישראל וישראל הם משה\":\nאם בשליחות לאדום הי' כתוב רק \"וישלח משה\", הי' \"זה נועל\", כלומר, זה הי' נועל (בפני הפירוש) ושולל שהשלי­חות לאדום היתה (גם) של בנ\"י, כ\"א משה עשה זאת בתור שליח השם ואין לתלות השליחות בישראל (אף שתוכן השליחות הוא בשבילם)<sup data-n=\"1108\">30</sup>; וכן לאידך — אם בשליחות לסיחון הי' כתוב רק \"ו­ישלח ישראל\" הי' \"זה נועל\" הפי' ד­שליחות משה בזה, כי השליחות לסיחון יש לתלות רק בישראל ולא במשה.\nולכן בא הכתוב השני ו\"פותח\" ומגלה — \"שמשה הוא ישראל וישראל הם משה\", דמ\"ש \"וישלח משה\" הרי זה כ­אילו נאמר \"וישלח ישראל\" (כי \"משה הוא ישראל\"), ומש\"נ \"וישלח ישראל\" הוא כאילו נאמר \"וישלח משה\" (כי \"ישראל הם משה\").\nה. אלא שצריך ביאור — איך אפשר לומר \"שמשה הוא ישראל וישראל הם משה\"? ומבאר רש\"י \"לומר לך שנשיא הדור הוא ככל הדור כי הנשיא הוא הכל\" —\nדי\"ל שב' הענינים בפרש\"י, \"נשיא הדור הוא ככל הדור כי הנשיא הוא ה­כל\", הם כנגד שני הענינים שלפנ\"ז<sup data-n=\"1109\">31</sup> — \"משה הוא ישראל וישראל הם משה\":",[["1103","25","וראה פנים יפות שם דישראל לא רצו לשלוח אלא משה שלח בשבילם ולא חש שמיתתו תלוי' בזה \"כמו שפרש\"י (שבהערה 22) גבי מלחמת מדין\". ועד\"ז הוא באלשיך שם. וראה גם צרור המור וש\"ך עה\"ת שם."],["1104","26","כא, כב."],["1105","27","ולהעיר מילקוט כאן (רמז תשסד קרוב לסופו) שהקב\"ה א\"ל \"אני אמרתי החל רש והתגר בו מלחמה ואתה משלח שלוחי שלום\" (אלא שב­ילקוט הוא להפירוש דמשה שלח, כהפסוק בדברים ובפרש\"י שם)."],["1106","28","ראה מדרש לקח טוב כאן."],["1107","29","ובזה גם סותר פי' החזקוני כאן, דשתי אגרות כתבו אחת של משה לשלום וא' של ישראל למלחמה. ומה שלא ס\"ל לרש\"י כן, ובפרט ששם נאמר בכתוב \"מדבר קדמות\"<sup data-n=\"e25\">*</sup> — כי בפשטות, ב­משנה תורה חוזר על דברים שאירעו לפנ\"ז ולא ענינים חדשים לגמרי (אם לא שיש הכרח גמור לומר כך). ועצ\"ע."],["1108","30","ומה שנאמר שם (ב, יט) \"ויאמרו אליו בני ישראל במסלה נעלה\" — בפשטות אינה שליחות חדשה, כ\"א המשך השקו\"ט של המלאכים שלוחי בנ\"י ומלך אדום. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081155\" data-slug=\"likkutei-sichot\" data-id=\"1300081155\">לקו\"ש ח\"ח ע' 144</a> ואילך ובהערות שם."],["1109","31","וצ\"ע בלשון רש\"י \"כי הנשיא כו'\". ולהעיר שברוב כת\"י רש\"י (שתח\"י) ליתא לתיבה זו."],["e25","*","ומפרש בפשוטו ש\"מ (בדברים שם) שאינו שם מקום (ראה מלבי\"ם כאן), אלא \"למדתי. . שקדמה. . שקדמת כו'\"."]]],[1301430193,"זה ש\"משה הוא ישראל\" הוא לפי \"שנשיא הדור הוא ככל הדור\", כלומר — אין פירוש הדברים, דכאשר המדובר ב­התעסקותו של משה בענין השייך לצרכי כלל ישראל אין הוא איש פרטי בזה, אלא הוא עושה זאת עבור הכלל, וב­מילא אפשר לכתוב \"משה\" (העושה ב­פועל) או \"ישראל\" (שבשבילם נעשה) — אלא שעצם מציאותו של משה, להיותו \"נשיא הדור\", הוא \"ככל הדור\". היינו דנשיא הדור הוא (איש) צבורי בעצם מהותו, ובמילא מה שהוא עושה ה\"ז עשיית ישראל.\nוכן לאידך — זה \"שישראל הם משה\" הוא לפי \"שהנשיא הוא הכל\": כאן לא כתב רש\"י \"כל הדור\", כי אין כוונתו כאן שמהותו של נשיא הדור היא — כל אנשי הדור, אלא שהכל<sup data-n=\"1110\">32</sup> — כל צרכי הכלל — הם (צרכיו ובאים על ידי) ה­נשיא<sup data-n=\"1111\">33</sup>, דכל מה שיש אצל בנ\"י בא מ(כח) הנשיא [כמו שמצינו בנוגע לבנ\"י במדבר, שכל צרכיהם הגשמיים (אכילה (מן ובשר)<sup data-n=\"1112\">34</sup> ושתי'<sup data-n=\"1113\">35</sup>) קיבלו על ידי משה, וכן כל התורה נמסרה להם (וכמה ציווים וכיו\"ב) על ידי משה]. ומכיון שכל עניני וצרכי בנ\"י באים ממשה (הנשיא), נמצא ש\"ישראל הם משה\"<sup data-n=\"1114\">36</sup>.\nוזהו ש\"הכתובים הללו\" — שתולים השליחות פעם במשה ופעם בישראל — באים \"לומר לך\", ששליחות שלכאורה יש לייחס ולתלות רק במשה (בתור שליח השם), הנה היא שייכת לכל ישר­אל, וכן לאידך, ששליחות שלכאורה היא של ישראל, תולה אותה הכתוב ב­משה — לפי \"שנשיא הדור הוא ככל הדור. . הנשיא הוא הכל\".\nו. מה\"ענינים מופלאים\" שבפירוש רש\"י:\nבמדרש<sup data-n=\"1115\">37</sup> (מקורו של פרש\"י) הלשון הוא \"שראש הדור הוא כל הדור\", ורש\"י משנה וכותב \"נשיא הדור הוא ככל ה­דור\"<sup data-n=\"1116\">38</sup>.\nויש לומר, שזהו בהתאם לחידושו של רש\"י (הנ\"ל): \"ראש הדור\" פירושו (ע\"ד",[["1110","32","להעיר מהלשון \"שלום שקול כנגד הכל\" (פרש\"י בחקותי כו, ו)."],["1111","33","להעיר מהגי' בדפ' ראשון \"שעל פי הנשיא הוא הכל\"."],["1112","34","כפשטות הכתובים בפ' בשלח — טז, ב ואילך. וראה פרש\"י שם, לה. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181269\" data-slug=\"likkutei-sichot\" data-id=\"1300181269\">לקו\"ש חי\"ח ע' 260</a>. וראה שם בנוגע ענני הכבוד."],["1113","35","ראה שם טו, כד­ה. פרשתנו כ, ז ואילך. וראה פרש\"י פרשתנו כא, כ. וראה לקו\"ש שם."],["1114","36","ועפכ\"ז יש לבאר ההוספה והחידוש כאן לגבי פרש\"י (ר\"פ יתרו) \"שקול משה כנגד כל ישראל\"<sup data-n=\"e26\">*</sup>, כי (נוסף לזה שכאן למדים משינוי הכתובים שאין זה ענין השייך רק למשה ולישראל בדורו כ\"א לכל נשיא הדור, הרי) זה שמשה שקול כנגד כל ישראל הוא ענין בגדלותו וחשיבותו של משה, וכאן — המדובר הוא בשייכותו לדורו. ולהעיר מגו\"א לפרש\"י שם."],["1115","37","שבהערה 9. וראה לעיל הערה 15 (ובהערה הבאה)."],["1116","38","ואולי י\"ל, שדברי רש\"י \"נשיא הדור הוא ככל הדור כי הנשיא הוא הכל\" — הוא פירוש ו­פירוט לשון קצר דהמדרש \"ראש הדור הוא כל הדור\". וראה להלן בפנים."],["e26","*","במכילתא יתרו שם ממשיך \"וישראל כמשה שקול רב כתלמיד ותלמיד כרב\". אבל לכאורה אינו פשוטו של מקרא. ולהעיר ממכילתא בשלח (ר\"פ השירה) \"משה שקול כנגד ישראל וישראל שקולין כמשה בשעה שאמרו שירה\". ושם \"מגיד שאמר משה שירה כנגד כל ישראל\". ושם טו, יג \"משה שנשקל כנגד הכל. . שהי' משה שקול כנגד הכל\". וראה גם ספרי מטות לא, ו. וגם שם הביא רש\"י רק צד א' — שהי' פינחס שקול כנגד כולם. ואכ\"מ."]]],[1301430194,"ראש כפשוטו) שהוא מנהיג את כל הדור; משא\"כ \"הנשיא\" הוא לשון נשי­אות והרמה, היינו שהוא שם התואר ל­אדם מרומם ומנושא.\nולכן: בלשון המדרש \"שראש הדור הוא כל הדור\" אפשר לפרש הכוונה, ד­מכיון שהוא הראש המנהיג את כל הדור, ועל ידי הנהגה אחת ואחידה של הראש — נעשים כל אנשי הדור למציאות אחת, מציאות הראש, לכן \"ראש הדור הוא כל הדור\",\n[ולהעיר משו\"ת הרשב\"א<sup data-n=\"1117\">39</sup> בענין מלך \"המלך כצבור שהצבור וכל ישראל תלויין בו\"<sup data-n=\"1118\">40</sup>, שהטעם שהמלך הוא כ­צבור, הוא לפי שהצבור וכל ישראל תלויים בו<sup data-n=\"1119\">41</sup>],\nולפ\"ז נמצא, דמה ש\"ראש הדור הוא כל הדור\" ה\"ז (רק) בענינים הצבוריים שלו, והיינו בענינים שעושה עבור כל ישראל וכיו\"ב, שעי\"ז מתאחדים כל ישראל כמציאות אחת.\nאבל בלשונו של רש\"י \"שנשיא הדור הוא ככל הדור כי הנשיא הוא הכל\", י\"ל שבזה מודגש ש\"נשיא\" הדור, גם כמו שהוא מרומם ומנושא (בפני עצמו), הרי הוא ככל הדור.\nוהחידוש שבדבר הוא בשני הקצוות:\nמחד גיסא, מכיון שעניניו ה\"ה חלק ממציאותו בתור נשיא, הרי מובן, שפעו­לותיו ומעשיו, שלכאורה הי' מקום לומר שהם \"בשוה\", עכ\"פ \"בערך\" למעשי שאר בנ\"י, גם בהם הוא שונה ומנושא<sup data-n=\"1120\">42</sup>, לגבי כל העם.\nולאידך, מכיון ש\"נשיא הדור הוא ככל הדור\", הרי גם עניניו הכי נעלים של הנשיא, שלכאורה הם בבחי' \"משכמו ומעלה גבוה מכל העם\"<sup data-n=\"1121\">43</sup> ואינם בערך לאנשי הדור, הרי מכיון שגם הם חלק ממציאות הנשיא (הנשיא הוא הכל) — הרי הם פועלים ונמשכים באנשי הדור<sup data-n=\"1122\">44</sup>.\nז. פ' חוקת חלה בכמה שנים בין ג' תמוז (היום אשר \"חופשה ניתנה לו\", התחלת הגאולה) וי\"ב­י\"ג תמוז — יום גאולת כ\"ק מו\"ח אדמו\"ר, נשיא הדור, ממאסרו אשר נאסר על הרבצת התורה וחיזוק הדת.\nויש למצוא רמז לעבודתו ואופן נשי­אותו בפרש\"י הנ\"ל — כי אצלו הי' נראה בגלוי, ובפרט בעבודתו הנ\"ל, ש\"נשיא הדור הוא ככל הדור. . הנשיא הוא הכל\":\n\"העבודה הגדולה\" אשר עבד כ\"ק",[["1117","39","ח\"א סי' קמח."],["1118","40","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191165\" data-slug=\"likkutei-sichot\" data-id=\"1300191165\">לקו\"ש חי\"ט ע' 165</a> ואילך. ושם נת' החילוק בין לשון זה ללשון הרמב\"ם (הל' מלכים פ\"ג ה\"ו) בנוגע למלך \"שלבו הוא לב כל קהל ישראל\"."],["1119","41","להעיר מ<a class=\"ft-cite\" href=\"#/read/tanya/3401310085\" data-slug=\"tanya\" data-id=\"3401310085\">תניא</a> אגה\"ק סכ\"ט (קמח, ב) מ\"מ\"ש האריז\"ל\" בביאור הטעם ש\"מצות התלויות במלך. . מוציא כל ישראל כי הוא כללות כולם\", ומשנה מל' המשנת חסידים (מסכת חיוב הנשמות פ\"ב מ\"א) \"שמפני חשיבותו כל המצות הראויים לו עולים לכל ישראל כו'\". וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181201\" data-slug=\"likkutei-sichot\" data-id=\"1300181201\">לקו\"ש חי\"ח ע' 192</a> סוף הערה 55."],["1120","42","להעיר מצפע\"נ ר\"פ קרח, שמפרש מחלוקת קרח וטעותו, היפך האמת אשר גם בדבר שהלויים דומים לכהנים, היינו גבי מצות שמירה, מ\"מ כהן למעלה והם למטה. עיי\"ש בארוכה."],["1121","43","ל' הכתוב (בנוגע לשאול) ש\"א ט, ב (וראה גם שם י, כג). וראה אוה\"ת בראשית (כרך ד) ע' 1528. שה\"ש (כרך ב) ע' תיד­טו. ועוד."],["1122","44","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310049\" data-slug=\"tanya\" data-id=\"3401310049\">תניא פמ\"ד</a> \"ואף כי מי הוא זה ואיזהו אשר ערב לבו לגשת להשיג אפי' חלק אחד מני אלף. . מ\"מ הרי אפס קצהו ושמץ מנהו מרב טובו ואורו מאיר לכללות ישראל כו'\". וראה בכל הנ\"ל בארוכה לקו\"ש ח\"ד ע' 1051 ובהערות שם."]]],[1301430195,"מו\"ח אדמו\"ר \"בהרבצת תורה וחיזוק הדת\"<sup data-n=\"1123\">45</sup> במדינה ההיא (שבדרך הטבע — היא שגרמה להמאסר) — וכן בכל מקום מגורו לאחר צאתו ממדינה ההיא<sup data-n=\"1124\">46</sup> — לא היתה מוגבלת בתחום מסויים של יהדות, כ\"א עסק בכל השטחים<sup data-n=\"1125\">47</sup> — הן בכל ה­שייך לחיזוק הדת: שילוח רבנים ושוח­טים למקומות שהיו זקוקים להם, בנין מקוואות, יסוד ישיבות וחדרים בשביל תשב\"ר, עד להרבצת התורה לכל ישר­אל, וגם הפצת רזי דרזין דאורייתא; והן הצלת נפשות כפשוטה, בפדיון שבויים, עזר וסיוע גשמיים לעניים וכל הזקוקים לזה (כידוע פרשת הימים ההם, ומה ש­ידוע הוא — מעט מזעיר, מטעמים מו­בנים).\nובכל עבודות אלו, שחלוקות מן ה­קצה אל הקצה, היתה התעסקותו בזה במסירה מוחלטת, עד למסירת נפש בפועל.\nוכך ראו במוחש אצלו הענין ד\"נשיא הדור הוא ככל הדור\" — ובמילא — \"הנשיא הוא הכל\", שכל עניני צרכי בנ\"י הרוחניים והגשמיים באים ונמשכים ממנו.\n<span data-k=\"q\">(משיחת ש\"פ חוקת תשמ\"א)</span>",[["1123","45","ל' כ\"ק מו\"ח אדמו\"ר במכתבו לחגיגת י\"ב תמוז הראשונה — בשנת תרפ\"ח (נדפס בסה\"מ תש\"ח ע' 263. אג\"ק שלו ח\"ב ע' פ. ועוד)."],["1124","46","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181311\" data-slug=\"likkutei-sichot\" data-id=\"1300181311\">לקו\"ש חי\"ח ע' 302</a> ואילך."],["1125","47","ראה גם מכתב ג' תמוז השי\"ת (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111216\" data-slug=\"likkutei-sichot\" data-id=\"1300111216\">לקו\"ש חי\"א ע' 209</a> ואילך. ועוד)."]]],[1301430196,"<h3>שיחה א</h3>\nא. נוסח ברכת הגומל (להלכה<sup data-n=\"1126\">1</sup>) הוא \"ברוך כו' הגומל לחייבים טובות ש­גמלני טוב<sup data-n=\"1127\">2</sup>\", ונוסח ברכת הנס (שנעשה ליחיד) הוא \"ברוך כו' שעשה לי נס במקום הזה\"<sup data-n=\"1128\">3</sup>. ומדייק כ\"ק מו\"ח אדמו\"ר (במאמרו<sup data-n=\"1129\">4</sup> שאמר בש\"ק (ט\"ז תמוז תרפ\"ז) שלאחרי גאולתו ממאסרו במדינה ההיא), וז\"ל:\nוצריך להבין למה נשתנה נוסח ברכה זו מברכת הנסים, דבברכת הנס אומר ברוך שעשה לי נס, ואינו מזכיר בברכתו חובה לעצמו, והיינו שימצא חוב בעצמו אשר בעבורו עמד ר\"ל בסכנה והוא ב­עצמו מודה שהי' חייב בדבר הסכנה ח\"ו אלא שהקב\"ה עשה לו נס, משא\"כ ב­ברכה זו אומר הגומל לחייבים טובות שמזכיר חוב לעצמו, והוא בעצמו מודה שהוא החייב בזה אלא שזהו מחסדי הוי' ודרכי הוי' שהוא ית' גומל גם לחייבים טובות. עכ\"ל.\nוהנה בהמשך המאמר לא נתפרשה, לכאורה, התשובה לשאלה זו (\"למה נשתנה נוסח ברכה זו מברכת הנסים\"), ורק לאחרי שמבאר ענין \"ארבעה צרי­כין להודות\"<sup data-n=\"1130\">5</sup> בעבודת האדם, שהם ד' סוגים במניעות ועיכובים על עבודת השם<sup data-n=\"1131\">*5</sup> (שעל ידם נוצר מצב של סכנה רוחנית לאיש ישראל), והקב\"ה עומד לימין כל אדם ונותן לו כח להתגבר על המניעות ועיכובים — מסיים את המאמר בביאור קצר בתוכן אמירת \"הגומל ל­חייבים\", וז\"ל:\nוזהו נוסח ברכה זו הגומל לחייבים טובות, דהלא כל ישראל מחוייבים בלי­מוד התורה ובקיום המצות. . ואם מצד איזה סיבה לא קיים זה הלא הוא האשם בזה. . כל המניעות ועכובים שבזמן ה­גלות הם רק נסיונות. . ולכן בברכה זו מזכיר חוב לעצמו.\nב. ונראה לבאר התשובה לשאלה הנ\"ל, ובהקדמה:\nבבית יוסף<sup data-n=\"1132\">6</sup> מפרש נוסח הברכה \"ה­גומל לחייבים\" — \"כלומר אפילו לאותם שהם חייבים דהיינו שהם רשעים. . עכ\"ז גומל להם טובות, וגם אני כאחד מהם שאף על פי שאיני הגון גמלני בכל טוב\".",[["1126","1","רמב\"ם הל' ברכות פ\"י ה\"ח. טור (וב\"י) ושו\"ע או\"ח ר\"ס ריט. סידור אדה\"ז."],["1127","2","כן הוא בסידור אדה\"ז (וכ\"ה בכת\"י הרמב\"ם החתום בעצם כי\"ק (רמב\"ם ספר אהבה — ירושלים, תשד\"מ) ועוד כת\"י — ראה רמב\"ם הוצאת קאפח). אבל ברמב\"ם לפנינו, טושו\"ע שם \"שגמלני כל טוב\". וראה רד\"ה ברוך הגומל שבהערה 4."],["1128","3","ברכות נד, א. רמב\"ם שם ה\"ט. שו\"ע שם סרי\"ח ס\"ד. סדר ברכת הנהנין לאדה\"ז רפי\"ג."],["1129","4","ד\"ה ברוך הגומל (נדפס בסה\"מ קונטרסים ח\"א קפד, ב ואילך. סה\"מ תרפ\"ז ע' ריא ואילך)."],["1130","5","ברכות נד, ב. — ולהעיר, שנלמדים בגמ' שם מהכתובים דמזמור קז שבתהלים — המזמור המתאים לשנותיו של כ\"ק מו\"ח אדמו\"ר במשך השנה (י\"ב תמוז תשמ\"ו­תשמ\"ז (שנת הדפסת שיחה זו)), ע\"פ תקנת הבעש\"ט (קובץ מכתבים לתהלים (בסוף תהלים אהל יוסף יצחק) ע' 214. ועוד) \"לאמר הקאפיטל תהלים המתאים למספר שנותיו\" (וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051115\" data-slug=\"likkutei-sichot\" data-id=\"1300051115\">לקו\"ש ח\"ה ס\"ע 103</a> ואילך (וש\"נ) בנוגע להמשך הזמן לאחרי ההסתלקות)."],["1131","*5","להעיר גם מחדא\"ג מהרש\"א ברכות שם."],["1132","6","לטואו\"ח ר\"ס ריט."]]],[1301430197,"ומשמעות פירושו, שהתואר \"חייבים\" כאן הוא כעין \"בלתי ראויים\" לקבלת חסדי השם, והיינו שהמברך מודה ו­משבח להקב\"ה על עשיית חסד זה עמו אף שאינו ראוי לכך (\"אע\"פ שאיני הגון\")<sup data-n=\"1133\">7</sup>.\nאמנם במאמר כ\"ק מו\"ח אדמו\"ר הנ\"ל מפורש<sup data-n=\"1134\">8</sup>, דהזכרת \"חובה לעצמו\" ענינה \"שימצא חוב בעצמו אשר בעבורו עמד ר\"ל בסכנה והוא בעצמו מודה שהי' חייב בדבר הסכנה ח\"ו\".\nויש לומר, ששינוי זה לגבי מ\"ש הבית יוסף נוגע להבנת תירוץ השאלה \"למה נשתנה נוסח ברכה זו (ברכת הגומל) מ­ברכת הנסים\":\nאת\"ל שאמירת \"הגומל לחייבים\" כוונתה רק להודות לה' על הטובה ש­נעשה עמו אע\"פ שאינו ראוי לכך — תמוה, אמאי לא תיקנו לשון זה גם בברכת הנסים?\nולכאורה, כלפי לייא: ברכת הגומל אין חיובה דוקא על הצלה שבאה על ידי נס, ואדרבה, הארבעה שצריכים ל­הודות הם במצבים שע\"פ טבע יכולים לצאת מהם בשלום (שלכן אין הם חייבים גם בברכת הנס אא\"כ ניצלו על ידי נס מיוחד כו'<sup data-n=\"1135\">9</sup>), משא\"כ ברכת הנס חיובה הוא על נס היוצא ממנהגו של עולם<sup data-n=\"1136\">10</sup>.\nוא\"כ, אם בהצלה טבעית יש להודות להשם על שגמל עמו טובה זו \"אע\"פ שאיני הגון\" — כש\"כ וק\"ו כשמודים ל­הקב\"ה על שידוד מערכות הטבע, שהי' צריך להוסיף בההודאה ההדגשה ש­נעשה לו הנס \"אע\"פ שאיני הגון\".\nג. לכאורה יש מקום לחלק בין ברכת הגומל לברכת הנס:\nברכת הגומל היא מברכות הודאה, שמודה ומשבח לה' על הטובה שהגיעה לו, ולכן יש מקום להוסיף \"הגומל ל­חייבים טובות\", מכיון שזה מפליא יותר את החסד שנעשה עמו (שלמרות שאינו הגון מ\"מ נעשה עמו חסד זה);\nמשא\"כ ברכת הנס היא מברכות הראי' — שמברך על ראיית המקום ש­נעשה שם הנס, היינו שהברכה היא על עצם עשיית הנס במקום זה (המראה על גדלותו ית' שביכלתו לשדד מערכות הטבע), ובמילא אין מקום להוסיף הפרט ד\"הגומל לחייבים\" השייך להאדם ש­אירע עמו נס זה, ולא לעצם עשיית הנס.\nאבל [לבד זאת, שכאשר הנס נעשה לשאינו ראוי י\"ל שזהו נס גדול יותר, הרי] חילוק זה אינו מוכרח, כי מלשון",[["1133","7","ועי\"ז מגדיל בשבחו ית', דנוסף על עצם ה­ענין שהקב\"ה גמל עמו טוב, הרי עשה זאת למרות שהוא אינו ראוי לטובה זו."],["1134","8","וכן פי' בתשובת מהר\"ם מינץ סי\"ד (שהובא במג\"א ר\"ס ריט). וכן מוכח בפי' התפלות והברכות לר\"י ב\"ר יקר (רבו דהרמב\"ן) ח\"ב (ירושלים, תשכ\"ט. תשל\"ט). וראה גם שו\"ת מהר\"ם שיק או\"ח ספ\"ח. שו\"ת אבני נזר או\"ח סל\"ט. ערוך השולחן או\"ח סרי\"ט ס\"ד."],["1135","9","ראה מג\"א שם סרי\"ט סק\"ט. סדר ברכת הנהנין לאדה\"ז רפי\"ג."],["1136","10","ראה שו\"ע או\"ח סו\"ס ריח ובמג\"א שם. ט\"ז שם סרי\"ט סק\"ו. ערוך השולחן שם ס\"א­ד. ועוד. וראה גם ס' פי' התפלות והברכות (שבהערה 8): ומן הדין יחיד שנעשה לו נס הי' לו לברך הגומל. . אלא שנפטר ממנה ע\"י ברכה זו שעשה לי נסים שהיא גדולה ממנה שהרי הי' חולה כו' אינו נעשה לו נס שהרי רוב חולים מתרפאים כו'. ע\"ש. וצע\"ק בפרש\"י צו (ז, יב): דבר הודאה על נס שנעשה לו כגון יורדי הים כו' וחולה שנתרפא כו'. וראה סדור הנסמן בהערה 22."]]],[1301430198,"ברכת הנס (ליחיד<sup data-n=\"1137\">11</sup>) \"ברוך שעשה לי נס במקום הזה\" מוכח שההודאה והשבח<sup data-n=\"1138\">12</sup> הם (לא רק על עצם הנס, אלא) ע\"ז ש­הוא \"בעל הנס\" [שלכן חייבים רק \"כל<sup data-n=\"1139\">13</sup> יוצאי יריכו של אותו אדם. . הם ובני­הם עד סוף כל הדורות לברך. . שכולם שותפים באותו נס\"].\nוי\"ל, שכדי ליישב שאלה זו מוסיף כ\"ק מו\"ח אדמו\"ר<sup data-n=\"1140\">14</sup> שהפירוש ב\"הגומל לחייבים\" הוא, ש\"מודה שהי' חייב בדבר הסכנה ח\"ו\" — דזה שייך רק בברכת הגומל, שהיא הודאה על הצלה, כלומר, כאשר לפנ\"ז הי' מצב של סכנה ואח\"כ ניצול ממנה, ולכן שייך לומר \"הגומל לחייבים\"<sup data-n=\"1141\">15</sup>, ש\"מודה שהי' חייב בדבר ה­סכנה ח\"ו\" (היינו שבאשמתו נעשה המצב שדרש הצלה מלמעלה);\nמשא\"כ ברכת הנס אינה דוקא על נס שהוא הצלה ממצב של סכנה. וע\"ד \"הרואה. . מעברות הירדן\"<sup data-n=\"1142\">16</sup> (המקום ש­עברו בו ישראל בימי יהושע<sup data-n=\"1143\">17</sup>), שנס זה (בקיעת הירדן) לא הי' בגדר הצלה מ­מקום סכנה אלא רק להקל עליהם העברת הירדן<sup data-n=\"1144\">18</sup>. שמזה מובן, שגם כש­מברכים על נס של הצלה, אין ההודאה על ביטול מצב סכנה, אלא על עצם החסד, שהקב\"ה עשה לו נס.\nולכן אינו מתאים בברכת הנס ענין \"הגומל לחייבים\", מכיון שאין הכרח שבעל הנס הי' במצב בלתי רצוי (סכנה וכיו\"ב) \"שהי' חייב בדבר הסכנה ח\"ו\"<sup data-n=\"1145\">19</sup> (וגם אם הי' במצב כזה — אין הכוונה בברכה זו להודות על ביטול מצב זה, כנ\"ל).\n[ועד\"ז הוא החילוק בין ברכת הגומל וברכת הנס בתוכנם הפנימי:\nברכת הגומל — שענינה הוא ההודאה על הצלה ממצב בלתי רצוי (סכנה כו') — שייכת לעבודת הנשמה בגוף, שהיא ירידה גדולה (כמבואר בארוכה בהמשך",[["1137","11","והרי כל השאלה (בהמאמר) מלכתחילה היא מברכת נס דיחיד, שהרי על נס דרבים (שנעשה לכל ישראל או לרובם — שו\"ע או\"ח סרי\"ח ס\"ב) אין לומר \"(הגומל) לחייבים\" — שהרי אדרבא זכות הרבים מסייעתם. ובכלל צ\"ל זהירות יתירה להזכיר חובה על כלל ישראל (ראה ישעי' ו, ה ואילך ובמפרשים. יבמות מט, ב), משא\"כ יחיד המזכיר חובה לעצמו.\n[ודוחק גדול לומר, שלא תיקנו לשון \"חייבים\" בברכת נס דכל יחיד מפני \"לא פלוג\"]."],["1138","12","ראה ברכות נד, א: על כולן צריך שיתן הודאה ושבח."],["1139","13","ל' אדה\"ז — סדר ברכת הנהנין פי\"ג ס\"א. וראה טושו\"ע או\"ח סרי\"ח ס\"ד ובנ\"כ."],["1140","14","היינו שהשאלה נכתבה בסגנון כזה, שמ­אריכות הביאור בהמאמר (בעבודת האדם) יובן ה­תירוץ על שאלה זו. וראה לקמן בפנים בסוף הסעיף."],["1141","15","וי\"ל שזהו גם הדיוק \"הגומל. . שגמלני\" — ע\"פ מרז\"ל (ברכות נו, סע\"ב) \"הרואה גמל בחלום מיתה נקנסה לו מן השמים והצילוהו ממנה\" (וראה רש\"י וחדא\"ג מהרש\"א שם, שהסימן הוא מצד ה\"נוטריקון של גמל\", השייך גם לתיבת \"גומל\")."],["1142","16","ברכות נד, א. טושו\"ע או\"ח ר\"ס ריח."],["1143","17","רש\"י ברכות שם."],["1144","18","בביאור הלכה (ר\"ס ריח) \"דהברכה לא נתקנה על פלאי הבורא כו' דנתקן רק אהצלת אדם מן המיתה בדרך נס\". ע\"ש באורך. אבל לכאורה צע\"ק מ\"מעברות הירדן\", כבפנים.\nובכל אופן: גם לפירושו י\"ל, דאף שהברכה נתקנה רק כשהיתה הצלה מן המיתה — מ\"מ, תוכן ההודאה והשבח אינו על ביטול הסכנה אלא על עשיית הנס (משא\"כ ברכת הגומל שתוכנה ההודאה שניצל מן הסכנה), כבפנים."],["1145","19","וע\"ד בפרשתנו (פ' בלק) — הנסים שנעשו לפינחס (ספרי, תנחומא, תיב\"ע ורש\"י סוף פרשתנו, סנהדרין פב, ב), שלא שייך לומר שהוא \"הי' חייב בדבר הסכנה\", ורק שגרם והביאה ע\"ע."]]],[1301430199,"מאמר כ\"ק מו\"ח אדמו\"ר), שירידה זו נותנת מקום שהאדם יכניס א\"ע למצב של סכנה ר\"ל (בד' האופנים ד\"ארבעה צריכים להודות\"); אלא שגם לאדם זה שהכניס עצמו למצב זה נותן הקב\"ה כח להנצל מהסכנה, על ידי ש\"גומל ל­חייבים טובות שגמלני טוב\" — (\"אין<sup data-n=\"1146\">20</sup> טוב אלא תורה שהוא טוב האמיתי\"<sup data-n=\"1147\">21</sup>);\nולכן אומרים בברכה זו \"הגומל ל­חייבים\", מכיון שהיא קשורה עם מצב של \"חייב\", סכנה רוחנית, והאדם מודה להשם שהצילו אף \"שהי' חייב בדבר הסכנה\", כנ\"ל.\nמשא\"כ ברכת הנס ענינה ההודאה והשבח להקב\"ה על ההתגלות האלקית שבמעשה נסים (שלמעלה — מל' ארים נסי<sup data-n=\"1148\">22</sup> — מטבע העולם), ולכן לא שייך בזה אמירת \"הגומל לחייבים\", שהרי אין כאן מצב של \"חייב\", כ\"א אדרבה, הת­גלות השם].\nד. אמנם לכאורה צ\"ע בגוף הפירוש הנ\"ל:\nברכת הגומל היא בנוסח שווה לכל ישראל, גם לצדיקים גמורים, ולכאורה תמוה ביותר לומר, שגם צדיק גמור \"הי' חייב בדבר הסכנה ח\"ו\"<sup data-n=\"1149\">23</sup>?\nבשלמא לפי' הב\"י שהכוונה ב­\"חייבים\" היא לענין קבלת הטוב (שה­אדם מודה שאינו הגון וראוי לטובה זו) יש לומר שזה שייך גם בצדיקים, ש­מחמת גודל ענוותנותם חושבים שאינם ראויים לחסדי ה'<sup data-n=\"1150\">24</sup>. וע\"ד שמצינו ביעקב ש\"התנצל<sup data-n=\"1151\">25</sup> על יראתו מפני עשו ולא די לו בהבטחתו כו' מפני היות קטן יעקב במאד מאד בעיניו כו' ואינו ראוי וכדאי כלל להנצל כו' שנדמה בעיניו שחטא\".\nאבל איך אפ\"ל שגם צדיק גמור צריך לחשוב (ובאמת) שחטא עד כדי כך<sup data-n=\"1152\">26</sup> שיהי' \"חייב בדבר הסכנה ח\"ו\"<sup data-n=\"1153\">27</sup>?\nוביותר אינו מובן: פירוש זה נאמר",[["1146","20","אבות פ\"ו, ג."],["1147","21","לשון כ\"ק מו\"ח אדמו\"ר סד\"ה הגומל שם."],["1148","22","ישעי' מט, כב (רש\"י יתרו כ, יז. חקת כא, ח. וראה סדור עם דא\"ח מד, סע\"ב (בעניננו — הודאה על נס). אוה\"ת בשלח ע' תרסה. ועוד)."],["1149","23","ולהעיר מעיון יעקב לע\"י ברכות (נד, ב ד\"ה על) \"גנאי הוא לת\"ח כמותו לומר כן (הגומל ל­חייבים)\". ט\"ז או\"ח סרי\"ט סק\"ג. ובס' מאמר מרדכי (ליוורנו, תקמ\"ד) או\"ח שם סק\"ו ד\"חייבים\" היינו \"חייבים דעלמא\".\nולהעיר שבשו\"ת לחמי תודה ס\"ה (שהובא ב­שערי תשובה ורעק\"א לשו\"ע או\"ח שם בריש הסימן) פי' \"חייבים\" (לא לשון \"חיוב של עונש\", אלא) \"לשון חוב. . שהאדם יש לו טובות הרבה אצל בוראו כו'\"."],["1150","24","וכדיוק ל' הב\"י, שמתחיל ד\"חייבים. . הם רשעים\", וממשיך \"וגם אני כאחד מהם שאע\"פ שאיני הגון כו'\" (ולא \"רשע\")."],["1151","25","ל' אדה\"ז בתניא אגה\"ק ס\"ב. וראה לקמן סעיף ה."],["1152","26","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091206\" data-slug=\"likkutei-sichot\" data-id=\"1300091206\">ראה טעמי</a> המצות להרח\"ו פ' קדושים בטעם שהאריז\"ל נהג \"לומר פרטי הוידוים\". ולהעיר מלקו\"ש ח\"ט ע' 206 ואילך."],["1153","27","בפרש\"י וישלח (לב, יא) \"נתמעטו זכיותי כו' שמא משהבטחתני נתלכלכתי בחטא ויגרום לי להמסר ביד עשו\". וברא\"ם שם מפרש ד\"ממעוט זכיותיו לחודי' אין לו לירא כל זמן שלא חטא דאין יסורין בלא חטא ולא מיתה בלא עון\". וראה פרש\"י תהלים קז, יא.\nאבל ראה חדא\"ג מהרש\"א ברכות (ד, א) ש­מסקנת הגמ' (שבת נה, ב) היא דיש מיתה בלא חטא כו'. וכוונת רש\"י ב\"נתלכלכתי בחטא\" היא (לא שלכן יענש להמסר ביד עשו, אלא) שזה יגרום שתתבטל ההבטחה<sup data-n=\"e27\">*</sup>. וכן מוכח מל' אדה\"ז באגה\"ק שם. וראה לקו\"ש ח\"ה ע' 398 הערה 67 (ח\"כ ע' 168 הערה 19)."],["e27","*","ועפ\"ז יומתק ל' רש\"י \"ויגרום לי להמסר ביד עשו\"."]]],[1301430200,"ע\"י כ\"ק מו\"ח אדמו\"ר בקשר לגאולתו ממאסרו, אשר הסיבה הטבעית למאסרו (\"דבר הסכנה\") היתה \"העבודה הגדולה\" אשר עבד \"בהרבצת תורה וחיזוק ה­דת\"<sup data-n=\"1154\">28</sup>, שעבד בזה עד כדי מסירת נפש בפועל, שזהו מצב של זכות בתכלית השלימות והעילוי — ואיך יתכן לומר שהוא \"הי' חייב בדבר הסכנה ח\"ו\"?!\nה. ויובן זה ע\"פ המבואר באגרת רבינו הזקן<sup data-n=\"1155\">29</sup> (שכתבה \"אחר ביאתו מ­פטרבורג\"<sup data-n=\"1156\">30</sup>) בפירוש הכתוב<sup data-n=\"1157\">31</sup> \"קטונתי מכל החסדים\", וז\"ל:\nבכל חסד וחסד שהקב\"ה עושה לאדם צריך להיות שפל רוח במאד כי חסד. . היא בחי' קרבת אלקים ממש. . וכל הקרוב אל ה' ביתר שאת. . צריך להיות יותר שפל רוח. . כל שהוא קמי' יותר הוא יותר כלא ואין ואפס. . וזו היא ג\"כ מדתו של יעקב. . היות קטן יעקב במאד מאד בעיניו מחמת ריבוי החסדים. . ואינו ראוי וכדאי כלל להנצל כו' וכמארז\"ל<sup data-n=\"1158\">32</sup> שמא יגרום החטא שנדמה בעיניו שחטא.\nמהמשך הלשון מובן, דגם זה שיעקב \"נדמה בעיניו שחטא\" הוא תוצאה מ\"ריבוי החסדים\". היינו, שה\"קרבת אלקים\" (שע\"י ריבוי החסדים) פעלה אצל יעקב לא רק הרגש של קטנות ו­שפלות (שיהי' קטן במאד מאד בעיניו) אלא שיהי' \"נדמה בעיניו שחטא\".\nויש לומר הסברת הענין:\nזה שחשש יעקב \"שמא יגרום החטא שנדמה בעיניו שחטא\" לא היתה זאת עניוות של שקר ח\"ו<sup data-n=\"1159\">33</sup>, שטעה יעקב ב­עצמו לחשוב שעבר על רצונו ית', אלא שחשש זה נתחדש ע\"י שנעשה \"קרוב אל ה' ביתר שאת\".\nכלומר<sup data-n=\"1160\">34</sup>: לפני שזכה ל\"קרבת אלקים\" זו, היתה עבודתו בתכלית ה­שלימות בלי חסרון כלל; ורק לאחרי ש­נתעלה להיות \"קרוב אל ה' ביתר שאת\" אזי (חשב ש)עבודתו הקודמת כחטא תחשב (אף שלפנ\"ז לא הי' שום חסרון בעבודתו)<sup data-n=\"1161\">35</sup>.",[["1154","28","ל' כ\"ק מו\"ח אדמו\"ר במכתבו לחגיגה ה­ראשונה — י\"ב תמוז תפר\"ח (אגרות קודש שלו ח\"ב ע' פ. וש\"נ)."],["1155","29","תניא שם."],["1156","30","כ\"ה הכותרת בתניא שם. ולהעיר מהכותרת למאמר כ\"ק מו\"ח אדמו\"ר הנ\"ל (שנכתבה על ידו) — \"ש\"פ פנחס, פ\"ז פטרסבורג\" [וכ\"ה ב\"מפתח\" לסה\"מ תרפ\"ז שם — שהוא ג\"כ לשון בעל הגאולה] — אף שבימים ההם שם העיר הי' לענינגראד [וכ\"ה הלשון בהרשימה שנדפסה בראש הקונטרס<sup data-n=\"e28\">*</sup> (שבו נדפס המאמר בפעם הראשונה) — \"ביום החמישי כו' ויבא לביתו ללענינגראד כו' אמר המאמר ברוך הגומל כו'\"]. — וראה סה\"ש תנש\"א ח\"ב ע' 658."],["1157","31","וישלח שם."],["1158","32","ברכות ד, א. רש\"י וישלח שם (בשינוי לשון)."],["1159","33","דנוסף לזה שיעקב מדתו מדת האמת (זח\"א קלט, סע\"א. קסא, א. <a class=\"ft-cite\" href=\"#/read/tanya/3401310018\" data-slug=\"tanya\" data-id=\"3401310018\">תניא ספי\"ג</a>. ובכ\"מ) — הרי ידוע שענין הענוה (משא\"כ שפל) אינו שטועה לחשוב שהוא בעל חסרון, אלא שלמרות שיודע מעלותיו ה\"ה קטן בעיני עצמו, בהכירו שכל מעלותיו ניתנו לו מלמעלה (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300131033\" data-slug=\"likkutei-sichot\" data-id=\"1300131033\">לקו\"ש חי\"ג ע' 33</a>. וש\"נ)."],["1160","34","בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251016\" data-slug=\"likkutei-sichot\" data-id=\"1300251016\">לקו\"ש חכ\"ה ע' 16</a> ואילך. וראה גם לקו\"ש ח\"ה ע' 396 ואילך (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201166\" data-slug=\"likkutei-sichot\" data-id=\"1300201166\">ח\"כ ע' 166</a> ואילך)."],["1161","35","היינו שאין הכוונה שאזי מכיר החסרון שהי' בו לפנ\"ז — אלא שהחסרון נתחדש עתה — כי ע\"י עלי' זו נדרשה ממנו שלימות בערכו עתה (ולפנ\"ז היתה עבודתו בשלימות) — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251015\" data-slug=\"likkutei-sichot\" data-id=\"1300251015\">לקו\"ש חכ\"ה (ע' 15</a> ואילך). וש\"נ.\nעוד דוגמא: ה\"מפסיק ממשנתו ואומר מה נאה אילן זה כו'\" (אבות פ\"ג מ\"ז) — אף שכשאינו עוסק בתורה, מחוייב לברך כשיוצא בימי ניסן ורואה אילנות שמוציאין פרח (ברכות מג, ב. טושו\"ע או\"ח סרכ\"ו. סדר ברכת הנהנין לאדה\"ז פי\"ג סי\"ד)."],["e28","*","גם רשימה זו נכתבה על ידי בעל הגאולה, אלא שכתבה בסגנון שלישי המדבר (ראה פתיחת הרמב\"ן לתורה)."]]],[1301430201,"דוגמא לדבר — מה שארז\"ל<sup data-n=\"1162\">36</sup> דמאן ד\"מחוו לי' במחוג קמי מלכא\" ה\"ז מרי­דה במלך, כי בעמדו לפני המלך צ\"ל בביטול גמור, מבלי כל זיז ותנועה כל שהיא<sup data-n=\"1163\">37</sup>; שזהו רק כשעומד לפני המלך, משא\"כ שלא במעמד המלך, הרי לא זו בלבד שמספיק כשמדת ביטולו אל ה­מלך תהי' בדרגא פחותה יותר (שמקבל ע\"ע לקיים חוקי המלך וכו'), אלא עוד זאת, שזהו רצון המלך, שהאדם לא יהי' בביטול גמור כזה, שהרי במצב ביטול כזה לא יהי' מסוגל למלאות פקודות המלך בישוב המדינה כו'.\nונמצא, שבהיותו לפני המלך — הרי עבודתו הרגילה בעת עסקו בהמדינה בישוב המדינה (גם שהיא בתכלית ה­שלימות) נחשבת \"כחטא\", כי לפני המלך אין לו אלא ביטולו אל המלך.\n[וכמבואר בספרים<sup data-n=\"1164\">38</sup>, שזוהי גם סיבת ההפרש בין ימי החול שבהם נצטווינו<sup data-n=\"1165\">39</sup> \"ששת ימים תעבוד ועשית כל מלאכתך\" (וארז\"ל<sup data-n=\"1166\">40</sup> \"זו מצות עשה\"), ואילו ביום השבת נאסרה עשיית מלאכה:\nביום השבת מאירה קדושתו ית' בעו­לם באופן גלוי<sup data-n=\"1167\">41</sup>, ע\"ד שעומדים לפני המלך, ולכן אסורים במלאכה<sup data-n=\"1168\">42</sup>; משא\"כ בימי החול, שקדושתו ית' מתעלמת בעו­לם, ה\"ז כמו בני המדינה הנמצאים מחוץ להיכל המלך — שאזי רצונו של המלך הוא שיתעסקו, יעשו מלאכה בישובו של עולם כו'].\nוזהו הפירוש בזה שיעקב \"נדמה בעי­ניו שחטא\", כי \"מחמת ריבוי החסדים\" שהגביהו את יעקב להיות \"קרוב אל ה' ביתר שאת\", הרי דרגתו, קטנותו בעיני עצמו הקודמת בעבודת השם נחשבת כחטא.\nועד\"ז יש לפרש נוסח הברכה \"הגומל לחייבים טובות\" אצל צדיקים גמורים — שעי\"ז גופא שנגמל להם חסד וטוב, ה\"ז גורם שירגישו א\"ע כ\"חייבים\", שלגבי גודל קרבתם אל ה' (ע\"י חסד זה), הרי מצבם הקודם הוא בגדר \"חייבים\" (אף שקודם \"קרבת אלקים\" זאת, היתה עבוד­תם בתכלית השלימות), כנ\"ל.\nו. אמנם עדיין אין הענין מיושב, כי ביאור הנ\"ל מספיק רק להסביר איך אפשר שצדיק גמור יחשיב א\"ע (באמת)",[["1162","36","חגיגה ה, ב."],["1163","37","וכן בשמו\"ע שאז צ\"ל כ\"עומד לפני המלך\" (שו\"ע אדה\"ז או\"ח סק\"ד ס\"ב. וראה ברכות לג, רע\"א. שבת י, א. טושו\"ע ודאדה\"ז או\"ח סו\"ס צה). — וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251016\" data-slug=\"likkutei-sichot\" data-id=\"1300251016\">לקו\"ש שם (ס\"ע 16</a> ואילך. וש\"נ) בטעם אמירת סלח לנו בתפלת שמו\"ע."],["1164","38","אוה\"ת לך (כרך ג) תשכ, א­ב (וש\"נ). המשך תרס\"ו ע' כב."],["1165","39","יתרו כ, ט."],["1166","40","מכילתא הובאה בדרשות ר' יהושע אבן שועיב פ' וישב ובס' מנחה בלולה יתרו שם. וראה מכילתא דרשב\"י יתרו שם. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011203\" data-slug=\"likkutei-sichot\" data-id=\"1300011203\">לקו\"ש ח\"א ע' 189</a> הערה 8."],["1167","41","וי\"ל ששני ענינים בזה: מצד המטה (הרגש האדם) — דמכיון שבשבת מרגישים יותר \"קרבת אלקים\" ה\"ז פועל הרגש הביטול; וכן מצד למעלה (דרגת האור) — שבשבת מאיר אור עליון נעלה יותר, שמצד אור זה אין מקום למציאות יש."],["1168","42","ובזה גופא כמה דרגות — יו\"ט<sup data-n=\"e29\">*</sup> שמותר במלאכת אוכל נפש; שבת שאסורה בכל מלאכה, אבל מותר באכו\"ש (עניני הגוף); יום הכפורים שאין בו אכו\"ש כו'."],["e29","*","ולפני זה חוה\"מ דמותר במלאכת דבר האבד."]]],[1301430202,"כ\"חייב\", אבל בהמאמר מפרש (כנ\"ל) \"חייבים\" — ש\"מודה שהי' חייב בדבר הסכנה ח\"ו\", והתמי' במקומה עומדת: הן אמת שלגבי מצבו בהווה עבודתו ה­קודמת אינה בשלימות, אבל איך אפ\"ל \"שהי' חייב (קודם לזה) בדבר הסכנה ח\"ו\"?\n[ודוחק גדול לומר שפירוש זה ב­\"הגומל לחייבים\" הוא רק לשאינם צדי­קים, ששייך לומר שהם אשמים \"בדבר הסכנה\"].\nויש לומר הביאור בזה:\nזה שהקב\"ה מעמיד את הצדיק במצב של סכנה כו', ה\"ז רק כדי להעלות אותו למדריגה עליונה יותר. כי דוקא על ידי העבודה במצב של \"מיצר\", מגיעים ל­\"מרחב\" האמיתי (מן המיצר גו' ענני ב­מרחב).\n[וע\"ד המבואר בהמאמר בענין ירידת הנשמה למטה (שההודאה דברכת הגומל בעבודת האדם היא על היציאה מהסכנה הרוחנית שבירידה זו) — שהכוונה ב­ירידה זו היא לצורך עלי', שע\"י עבודת הנשמה בבירור וזיכוך הגוף הגשמי (ו­המשכת קדושה בדברים גשמיים) מתע­לית הנשמה למדריגה עליונה וביותר מכמו שהיתה קודם ירידתה בגוף.\nוענין זה הוא גם אצל צדיקים גמו­רים, שהענין שעובד ה' בעוה\"ז ה\"ז ירידה, כי \"גם. . צדיק גמור עובד ה' ביראה ואהבה רבה בתענוגים לא יגיע למעלות דביקותו בה'. . בטרם ירידתו לעוה\"ז החומרי לא מינה ולא מקצתה ואין ערך ודמיון ביניהם כלל\"<sup data-n=\"1169\">43</sup> — אלא שירידה זו צורך עלי', שע\"י עבודתם ב­היותם נשמות בגופים דוקא, מתעלים בעילוי אחר עילוי כו'].\nולכן גם צדיק גמור מברך \"הגומל לחייבים טובות\" — אף שלא שייך לומר שהוא \"אשם\" \"בדבר הסכנה ח\"ו\" — כי מצבו הקודם, שהוא בגדר \"חייבים\"<sup data-n=\"1170\">44</sup> לגבי \"קרבת אלקים\" שזכה לה על ידי גמילת הטוב, הוא הוא שגרם שיועמד ב­מיצר זה, כדי שיגיע לעלי' הזאת (הבאה ע\"י מיצר זה<sup data-n=\"1171\">45</sup>).\nוככל הדברים האלה נראה במוחש ב­גאולת כ\"ק מו\"ח אדמו\"ר<sup data-n=\"1172\">46</sup> — שדוקא לאחרי שעבר את יסורי המאסר ר\"ל, הותחלה תקופה חדשה בעבודתו בהר­בצת התורה וחיזוק הדת בכלל, שעבו­דתו זו נתרחבה — יצאה למרחב — ועד להפצה בכל קצוי תבל.\nונתגלה לעין כל, שהכוונה של ה­מאסר היתה בשביל עלי' זו, ליתן ה­אפשריות להרחבת העבודה, להפיץ תורה ויהדות — כולל הפצת המעיינות של פנימיות התורה — בכל מרחבי (שבכל קצוי) תבל.\n<span data-k=\"q\">(משיחות י\"ב תמוז תשכ\"א, ש\"פ בלק תשל\"ז)</span>",[["1169","43","<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מח, סע\"א</a>)."],["1170","44","גם י\"ל שעצם הירידה למצב של מיצר ו­סכנה הו\"ע של \"חייב\" — ע\"ד הידוע דהגם שה­צמצום הוא בשביל הגילוי, מ\"מ \"גוף ועצם הצמצום הוא היפך הרצון\" (סה\"מ קונטרסים ח\"א קצב, א ואילך). ואכ\"מ."],["1171","45","ועפ\"ז יש לפרש נוסח הברכה \"הגומל ל­חייבים\" — שע\"י הרגש המיצר מזה שנמצאים במצב ד\"חייבים\", זוכים ל\"הגומל. . טובות\" — דמן המיצר אל המרחב, כנ\"ל. וראה לקו\"ש שצויין בהערה 26."],["1172","46","להעיר, שאדה\"ז אמר לאחרי גאולתו [י\"ט כסלו תק\"ס — שנה לאחרי גאולתו, אבל בא בהמשך לד\"ה בכ\"ה בכסלו שאמר אדה\"ז בחנוכה תקנ\"ט בוויטעבסק בנסיעתו חזרה ממאסרו בפעטערבורג] דרוש \"ברוך שעשה נסים לאבותינו\" (לקו\"ד ח\"א כא, א. וראה שם מה שאמר \"בתחילת אמירתו\"), וכ\"ק מו\"ח אדמו\"ר אמר מאמר \"ברוך הגומל כו'\". ואכ\"מ."]]],[1301430203,"<h3>שיחה ב</h3>\nא. אודות יום י\"ב תמוז — היום שבו נגאל כ\"ק מו\"ח אדמו\"ר ממאסרו<sup data-n=\"1173\">1</sup> אשר נאסר בגלל \"העבודה הגדולה\" אשר עבד \"בהרבצת תורה וחיזוק הדת\"<sup data-n=\"1174\">2</sup> — כתב כ\"ק מו\"ח אדמו\"ר, במכתבו לחגיגת י\"ב תמוז הראשונה (בשנת תרפ\"ח)<sup data-n=\"1175\">3</sup>, וז\"ל \"ראוי הוא לקובעו ליום התועדות ו­התעוררות לחיזוק התורה והיהדות בכל אתר ואתר לפי ענינו\".\nנתבאר כמה פעמים, אשר כל דברי רבותינו נשיאינו מדוייקים המה, אפילו בנוגע ל\"שיחות\" ואפילו בנוגע לשיחות חולין שלהן — שהן צריכין לימוד<sup data-n=\"1176\">4</sup>, ו­כ\"ש וק\"ו שכן הוא בדברי תורתם, וביתר שאת כולל — הוראותיהם (תורה מלשון הוראה).\nובעניננו — יש לדייק בלשון כ\"ק מו\"ח אדמו\"ר הנ\"ל \"חיזוק התורה וה­יהדות\". דלכאורה, \"יהדות\" ה\"ה שם כללי, הכולל כל השייך לדת ישראל — הן לימוד התורה והן שמירת וקיום ה­מצוות (דאורייתא, דרבנן, עד למנהגי ישראל כו'), וא\"כ הי' מספיק לומר \"חיזוק היהדות\" — ומאי קמ\"ל ב\"(חיזוק) התורה\"?\nבפשטות הכוונה בזה להדגיש הענין והפעולות ד\"חיזוק התורה\", כמו שכותב כמה פעמים במכתבו הנ\"ל ע\"ד עבודתו ב\"הרבצת תורה\" (והכוונה כפשוטה — יסוד חדרים, ישיבות ושיעורי תורה ב­רבים (עבור בעלי עסק) וכו') — אבל הו\"ל (לכאורה) להקדים את הכל והכלל, \"יהדות\", ואח\"כ להוסיף ההדגשה על הפרט, \"תורה\".\nגם יש לדייק ולבאר לשונו \"חיזוק התורה\", ולא כלשונו כמה פעמים ב­מכתבו שם \"הרבצת תורה\".\nונראה לומר, שאחת הכוונות דכ\"ק מו\"ח אדמו\"ר כאן היא — לא לעורר על שני ענינים שונים — התחזקות בעבודת הרבצת התורה והתחזקות בעבודת החזקת היהדות (שמירת וקיום המצוות וכו') — אלא הכוונה לענין אחד — \"חיזוק היהדות\"; אלא שאא\"פ לחזק את היהדות באופן הנרצה כ\"א ע\"י הקדמת והתחלת חיזוק התורה.\nב. ביאור הדבר:\nהמושג \"יהדות\" במובנו הפשוט פירו­שו כללות הנהגות יהודים בתור יהודים. ולכן יש צורך להדגיש ולקבוע, ש­\"יהדות\" אינה רק הנהגת בני אדם, הדרך שנהגו בו בני ישראל במשך הדורות, מעשה ידי אדם ח\"ו — אלא כל כולה ומ­הותה הוא קיום הוראות התורה שניתנה בסיני מפי הגבורה.\nוזהו תוכן ההדגשה \"חיזוק התורה וה­יהדות\", שלפני חיזוק היהדות יש צורך לחזק את האמונה וההכרה שרק התורה היא הקובעת מהי \"יהדות\"<sup data-n=\"1177\">5</sup>, ואין הדבר",[["1173","1","ביום י\"ב תמוז נתבשר כ\"ק מו\"ח אדמו\"ר שחופשה ניתנה לו, וניתנה לו תעודת השחרור למחרתו — יום י\"ג תמוז."],["1174","2","לשון כ\"ק מו\"ח אדמו\"ר במכתבו שמובא בפנים."],["1175","3","נדפס בסה\"מ תרפ\"ח ע' קמו. תש\"ח ע' 263. אגרות קודש אדמו\"ר מהוריי\"צ (ח\"ב ע' פ)."],["1176","4","סוכה כא, ב. ע\"ז יט, ב."],["1177","5","להעיר ממאמר הרס\"ג (האמונות והדעות מ\"ג פ\"ז) \"אומתנו איננה אומה כי אם בתורותי'\"."]]],[1301430204,"מסור לבני אדם, שבשכלם יכריעו שעני­נים מסוימים אלה ביהדות הם חובה, משא\"כ ענינים אחרים — אלא כל פרט ופרט שבתורה, עד לחידוש של תלמיד ותיק, ואפילו מנהגי ישראל שנתחדשו בדורות האחרונים (ונתקבלו ברוב תפו­צות ישראל<sup data-n=\"1178\">6</sup>) — ה\"ה חלק מתורתנו ה­קדושה, שהיא תורת ה', תורה מן השמים, שניתנה למשה מסיני<sup data-n=\"1179\">7</sup> (כי אפילו מנהג ישראל — תורה הוא<sup data-n=\"1180\">8</sup>).\nומזה מובן, שמי שמקיל בחומרות ו­מנהגי ישראל שנתתקנו והונהגו בדורות האחרונים, בחשבו שהם \"מעשה בני אדם\", ואשר ע\"כ אין הוא מחויב לקבלם על עצמו — הרי אין התנגדותו בנוגע לאיזה ענינים פרטים של \"יהדות\" וחסר הוא מעשים אחדים, אלא שזהו בניגוד ממש לעיקרי היהדות, שכולה אינה מעשה בני אדם, אלא כל פרט ופרט שבה הוא דת שגילה השם על ידי עבדיו — חכמי ישראל שבכל דור ודור<sup data-n=\"1181\">9</sup>.\n[ולא עוד, אלא ש\"שיטה\" זו — לחלק בין עניני תורה שבע\"פ המיוסדים על תורה שבכתב (היינו, הענינים שלמדו חכמים ע\"פ י\"ג מדות שהתורה נדרשת בהן) או שהם הלכה למשה מסיני, ל­\"הגזירות והתקנות והמנהגות\"<sup data-n=\"1182\">10</sup> שנת­חדשו ע\"י חכמי ישראל<sup data-n=\"1183\">11</sup> שבכל דור ו­דור — ה\"ה פתח<sup data-n=\"1184\">12</sup> לכפירה ר\"ל בהעיקר שהתורה שבעל פה היא כולה מן ה­שמים<sup data-n=\"1185\">13</sup>].\nג. ויש לומר, שהצורך בהדגשה זו, \"חיזוק התורה\" לפני חיזוק היהדות, הוא בגלל המשך הענין בהוראה זו — \"(חיזוק התורה והיהדות) בכל אתר ואתר לפי ענינו\":\nאילו הי' חיזוק התורה והיהדות רק ב\"עיר מלאה חכמים\" וכיו\"ב — אין צורך בהדגשה הנ\"ל, דפשיטא אצל כאו\"א שכל מהות היהדות היא היותה תורת השם; אבל כיון שהמדובר הוא בחיזוק היהדות \"בכל אתר ואתר לפי ענינו\", יש צורך לשלול טעות, שהיהדות ניתנה ל­השתנות ח\"ו וח\"ו לפי תנאי הזמן וה­מקום. ועוד זאת, הרי יש \"אתר\" שאנשיו רחוקים מאד מיהדות ואא\"פ להשפיע עליהם שיקבלו על עצמם עול שמירת כל התורה כולה לכל פרטי', באופן ש\"ענינו\" של \"אתר\" זה דורש להסתפק (לפי שעה) בהשתדלות על מנת שיקיימו (רק) מצוות אחדות (וכיו\"ב).\nולכן, כאשר עוסקים בחיזוק היהדות \"בכל אתר ואתר לפי ענינו\", צריכים לזכור תמיד (ההקדמה) שקודם חיזוק היהדות בא \"חיזוק התורה\", שה\"יהדות\"",[["1178","6","ראה בפרטיות הל' ממרים פ\"ב. ע\"ש. — וראה הערה 9."],["1179","7","ראה מגילה יט, ב. ירושלמי שם פ\"ד ה\"א. ירושלמי פאה פ\"ב ה\"ד. שמו\"ר ספכ\"ח. שם רפמ\"ז. ויק\"ר רפכ\"ב. ועוד. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191265\" data-slug=\"likkutei-sichot\" data-id=\"1300191265\">לקו\"ש חי\"ט ע' 252</a> הערה 21."],["1180","8","ראה תוד\"ה נפסל (מנחות כ, ב). רמ\"א יו\"ד סשע\"ו ס\"ד. וראה ירושלמי פסחים פ\"ד ה\"א. ועוד."],["1181","9","אלא שבזה גופא מחלקת התורה כמבואר ע\"פ חכמי התורה: הלכה חומרא מנהג שנתקבל במקום אחד ובמקום שני נתקבל ע\"פ כללי התורה מנהגי' (ראה הקדמת הרמב\"ם לספר היד). ועוד."],["1182","10","ל' הרמב\"ם הל' ממרים פ\"א ה\"ב וג'. וראה גם הקדמת הרמב\"ם שם. ועוד."],["1183","11","ראה רמב\"ם הל' ממרים שם. ובארוכה — בהקדמתו לפירוש המשניות."],["1184","12","אף שחלוקים המה (דאורייתא, ד\"ס וכו') כנ\"ל — הרי זה הוא רק מפני שכן רצה הקב\"ה וגילה בתורתו תורה אור חילוקים אלה."],["1185","13","הל' תשובה פ\"ג ה\"ח ובכס\"מ שם. וראה פיה\"מ פ' חלק היסוד הט'."]]],[1301430205,"נקבעת ונבנית אך ורק על חיזוק יסוד ה­תורה, שלא ניתנה להשתנות מצד שינויי הזמן והמקום.\nוכמשנ\"ת כמה פעמים בפירוש דיוק לשון המשנה<sup data-n=\"1186\">14</sup> \"הוי מתלמידיו של אהרן כו' אוהב את הבריות ומקרבן לתורה\" — שצריכים לקרב את הבריות לתורה, ולא להיפך, \"לקרב\" ולהוריד את התורה ח\"ו אל הבריות, על ידי וויתורים ח\"ו ו­פשרות וגרעונות בהלכות התורה — גם אפילו באם נדמה שיתכן ופשרה זו דוקא תועיל (לפי דעתו) לקרב את הזולת ל­תורה ומצוותי', עכ\"פ לקיום מצוות אחדות; כי, כנ\"ל, תורתנו הקדושה היא תורת אמת, ולא ניתנה לפשרות, וכאו\"א מישראל, מבלי הבט על מצבו ומקומו, חובתו לקבל את כל התורה כולה לשמור ולקיים כולה.\nואין זה סותר לכך שההשתדלות ב­חיזוק היהדות היא, כפי שמפורש, \"בכל אתר ואתר לפי ענינו\", ועד שלפעמים צ\"ל ההשתדלות באופן דלאט­לאט — ועד שמי שהוא בגדר תינוק שנשבה ל­בין העכו\"ם, יתחיל בקיום מצוה אחת וכיו\"ב (כנ\"ל) — כי אין פירוש הדברים שעושים פשרות בתורה ויהדות, אלא ע\"ד שמצינו בנוגע ללימוד התורה, שעם תינוק מתחילים בלימוד הא\"ב, ואח\"כ הולך מחיל אל חיל: לימוד צירוף כמה אותיות, כמה תיבות ועד שזוכה ללמוד את כל התורה כולה; ופשוט, שלימוד הא\"ב עם תינוק אינו \"פשרה\" כלל, ואין בזה כל וויתור או גרעון כלל וכלל, אלא זהו סדר הלימוד, מן ההתחלה אל ההמשך וכו' דייקא;\nוכן הוא בנוגע לקיום המצוות, \"חיזוק היהדות\" — דכאשר מתעסקים עם \"תינוק\" (ברוחניות), שאין לו שום ידיעה בעניני יהדות, צריכים לכל­לראש ל­למדו את הא\"ב של \"יהדות\"; אבל תיכף בהתחלה זו יודע \"התינוק\" שאין הא\"ב (שבזה התחיל) כל התורה כולה, אלא שבמצבו עתה (שהוא \"תינוק\" כו') הרי מתחילים בקיום מצוה אחת, ובמשך הזמן ילך מחיל אל חיל, ו\"מצוה גוררת מצוה\"<sup data-n=\"1187\">15</sup>.\nד. וזוהי ההוראה בפועל, שצריכה לשמש כיסוד לההתועדויות דחגיגת חג הגאולה די\"ב תמוז — שהעסק בחיזוק היהדות צ\"ל מיוסד על שני עיקרים אלה, ובשני הקצוות:\nהעיקר הא' הוא — \"חיזוק התורה וה­יהדות\", והיינו האמונה הטהורה שכל ענין של יהדות נקבע אך ורק על ידי התורה שהיא מן השמים (ואינו מעשה בני אדם כלל וכלל ח\"ו ור\"ל), ובמילא לא שייך שיהי' בזה פשרה, וויתור או גרעון בתורה ומצוותי', כי כשם ש\"אני ה' לא שניתי\"<sup data-n=\"1188\">16</sup>, כך אין שייך שינוי ב­\"יהדות\" שהיא דבר השם.\nוביחד עם זה חייבים להשתדל בחי­זוק היהדות \"בכל אתר ואתר לפי ענינו\", דאע\"פ שהמדובר ב\"אתר\" שהוא רחוק לעת עתה מיהדות ומה גם מקיום כל התורה כולה, וההשתדלות שם היא \"לפי ענינו\" (כנ\"ל באורך)\n— אבל ביחד עם זה באמת, ודוקא מתוך אמת לוקחים וכובשים (נעמט מען אן) את האדם —\nאסור לו לאדם לעמוד מרחוק [כאו­תם האומרים, שרק עם יהודים יראים ושלמים יש להתעסק כדי לחזק ידיהם",[["1186","14","אבות פ\"א מי\"ב."],["1187","15","אבות פ\"ד מ\"ב."],["1188","16","מלאכי ג, ו."]]],[1301430206,"בשמירת התורה ומצוותי', אבל לא עם אלה החסרים בזה ועאכו\"כ — אלה ה­רחוקים מתורת ה' ועבודתו],\nאלא חייב להשתדל בכל כחו לקרבם לתורה ומצוותי', כהוראת הבעש\"ט<sup data-n=\"1189\">17</sup> ע\"ד גודל הענין של מצות אהבת ישראל לכאו\"א מישראל, גם למי \"שלא ראה אותו מעולם\", וכמשנ\"ת במק\"א<sup data-n=\"1190\">18</sup> שה­כוונה בזה היא גם ברוחניות הענינים, ש­גם יהודי שרחוק מיהדות עד שלכאורה אין לו שום שייכות עמו ביהדות, הנה גם אותו צריך לאהוב עד כדי להשתדל לקרבו לתורה וליהדות — דברים הכי יקרים בכל העולם כולו;\nוכמבואר בספר התניא<sup data-n=\"1191\">19</sup>, ד\"מי שאינו חבירו (בתורה ומצות) ואינו מקורב אצלו\", אסור לשנאותו ח\"ו (גם אם ראה שחטא), אלא \"ע\"ז אמר הלל הזקן<sup data-n=\"1186\">14</sup> הוי מתלמידיו של אהרן אוהב שלום וכו' אוהב את הבריות ומקרבן לתורה, לומר. . צריך למשכן בחבלי עבותות אהבה וכולי האי ואולי יוכל לקרבן לתורה ועבודת ה'\".\nועל ידי ההשתדלות באהבת ישראל, לכאו\"א מישראל ממש, זוכים לברכת ה', ד\"ברכנו אבינו (כאשר) כולנו כאחד\"<sup data-n=\"1193\">20</sup> דוקא,\nעד לברכה העיקרית והפנימית — גאולה האמיתית והשלימה על ידי משיח צדקנו, במהרה בימינו ממש.\n<span data-k=\"q\">(משיחת י\"ג תמוז תשכ\"ט) </span>",[["1189","17","\"היום יום\" טו כסלו (וראה שם ג' אדר א' בשם אדה\"ז. ועוד)."],["1190","18","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011215\" data-slug=\"likkutei-sichot\" data-id=\"1300011215\">לקו\"ש ח\"א ע' 201</a>."],["1191","19","פרק לב."],["1186","14","אבות פ\"א מי\"ב."],["1193","20","ברכת שים שלום בתפלת העמידה (הובא בתניא שם לפנ\"ז)."]]],[1301430207,"<h3>בלק</h3>\nא. אודות דרכו של רש\"י בפירוש נבואות בלעם (שבפרשתנו), נתבאר ב­מ\"א<sup data-n=\"1194\">1</sup>, שאף שקבע רש\"י שלא בא בפירו­שו אלא לפרש פשוטו של מקרא ומביא רק אגדות המיישבות את המקראות<sup data-n=\"1195\">2</sup>, מ\"מ שונה בזה פירושו בנבואת בלעם, שמביא ריבוי דרשות רז\"ל — והטעם כי בכתוב כפשוטו מפורש \"וישא משלו\"<sup data-n=\"1196\">3</sup>, היינו שע\"פ דרך הפשט, אין פירוש כתו­בים אלה לפי \"פשוטם\" ממש כשאר ה­כתובים, אלא הם \"משלים\", ומשל הרי פשטות ענינו (גם) רמזים ודרשות [ועד\"ז בפירושו לשירת הים, שירת האזינו ועוד — להיותן \"שירות\" מביא שם רש\"י כמה דרשות].\nעוד מצינו, שבנבואת בלעם הרבה רש\"י להביא פירושי \"תרגומו\" שלא ע\"ד הרגיל בפירושו עה\"ת. וע\"פ הנ\"ל מובן — שבהבאת דברי התרגום, כוונתו בעי­קר (אינה לתרגום לשונות הכתובים, אלא) לפירוש הנמשל של ה\"משל\" לפי תרגומו.\nאמנם בזה גופא מצינו כמה אופנים: לפעמים מתחיל רש\"י פירושו \"כתרגומו\" ואח\"כ מביא עוד פי' מדרשת חז\"ל, ו­לפעמים להיפך. וע\"פ הנ\"ל מובן, דתלוי מה קרוב יותר לפשש\"מ בתוכן דברי ה\"משל\".\nעפכ\"ז יש לעיין בפרש\"י עה\"פ<sup data-n=\"1197\">4</sup> \"הן עם כלביא יקום גו'\", שמפרש: \"כשהן עומדין משינתם שחרית הן מתגברים כלביא וכארי לחטוף את המצות ללבוש ציצית לקרוא את שמע ולהניח תפלין. לא ישכב — בלילה על מטתו עד שהוא אוכל ומחבל כל מזיק הבא לטרפו כיצד קורא את שמע על מטתו כו'\", ולאחרי אריכות פירושו (שמקורו בדברי המד­רש<sup data-n=\"1198\">5</sup>) כתב \"ד\"א הן עם כלביא יקום וגו' — כתרגומו\".\nויש להבין: למה מקדים להביא דברי המדרש שהם רמז רחוק, לכאורה, בפי' התיבות, ולא הביא בתחלה פי' התרגום, שלפי פירושו (\"הא עמא. . לא ישרי ב­ארעה עד דיקטול קטול ונכסי עממיא יירת\") מדבר הכתוב בכניסת בני ישראל לארץ ישראל וכיבוש הארץ (וכמו ש­הביא הרמב\"ן<sup data-n=\"1199\">6</sup> מהתרגום)?\nויתירה מזו: בנבואת בלעם שלאח\"ז, ששם נאמר<sup data-n=\"1200\">7</sup> ע\"ד הלשון שבפסוק זה — \"כרע שכב כארי וכלביא מי יקימנו\", פרש\"י \"כתרגומו, יתיישבו בארצם בכח ובגבורה\" ותו לא, ומאי טעמא לא הביא כאן מתחלה פי' התרגום הקרוב יותר לפשש\"מ (גם) כאן?\nוביותר יוקשה, דבתחלת נבואה זו של בלעם \"לא איש א­ל וגו'\"<sup data-n=\"1201\">8</sup> פרש\"י \"כבר נשבע להם להביאם ולהורישם ארץ",[["1194","1","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181271\" data-slug=\"likkutei-sichot\" data-id=\"1300181271\">לקו\"ש חי\"ח ע' 262</a> ובהערה 3 שם. חכ\"ח ע' 167 ואילך."],["1195","2","ראה פירושו בפ' בראשית ג, ח. שם, כד. ועוד."],["1196","3","פרשתנו כג (ז. יח). כד (ג. טו. כ. כא. כג). וראה פרש\"י חקת כא, כז."],["1197","4","כג, כד."],["1198","5","תנחומא פרשתנו יד. במדב\"ר פ\"כ, כ."],["1199","6","פרשתנו כג, כג. וראה גם ראב\"ע כאן פסוק כד."],["1200","7","כד, ט."],["1201","8","כג, יט."]]],[1301430208,"שבעה אומות ואתה סבור להמיתם ב­מדבר\", הרי שעיקר דברי בלעם (ובפרט בנבואה זו) מיוסדים על זה, לשלול הסברה \"להמיתם במדבר\" — כי ברור לו (לבלעם) שבנ\"י ימשיכו ללכת בכח ו­גבורה לכבוש ארץ שבעה עממין<sup data-n=\"1202\">9</sup>, ו­ינצחו את האומות, ובהמשך לזה מתאים יותר לכאורה פירוש התרגום הנ\"ל.\nב. וי\"ל הביאור בזה — בפשטות:\nבתוכן נבואות בלעם, שענה<sup data-n=\"1203\">10</sup> לבלק (ע\"ז שביקש ממנו \"לכה נא ארה לי את העם הזה\"<sup data-n=\"1204\">11</sup>) שאינו יכול לקלל את ישראל — יש ב' אופנים: א) שאינו יכול לקללם ולהרע להם ע\"י דבורו, כי הם חביבים בעיני הקב\"ה והוא משגיח עלי­הם ושומרם כו'. ב) יש להם מעלות ו­זכויות רבות שאינם בשאר האומות, ו­לכן (לא רק שא\"א לו להרע להם ע\"י דבורו, אלא יתירה מזו —) \"ראויים הם לברכה\"<sup data-n=\"1205\">12</sup>.\nוי\"ל, שבכללות זהו החילוק בין נבואתו הראשונה ונבואתו השני': בהק­דמה לנבואה הא' אמר<sup data-n=\"1206\">13</sup> \"מה אקב לא קבה א­ל ומה אזעם לא זעם ה'\", ואילו ההקדמה לנבואה הב'<sup data-n=\"1207\">14</sup> היא \"הנה ברך לקחתי וברך ולא אשיבנה\".\n[ואף שבב' הנבואות (וכן בנבואה הג' והד') יש מב' הענינים (אופנים) הנ\"ל, למה אינו יכול לקללם (ויתירה מזו, דר­כו של רש\"י בפי' כתובים אלה שהרבה להביא יותר מפירוש אחד, לפי שמסתבר שיש להוסיף בפירוש דברי בלעם בזכות ומעלת ישראל), מ\"מ תלוי מהו העיקר].\nובזה מבואר החילוק הכללי בין פי­רושי רש\"י בשתי נבואות אלו:\nבנבואה הא' שמתחילה<sup data-n=\"1208\">15</sup> \"כי מראש צורים אראנו\", פירש\"י \"אני מסתכל בראשיתם ובתחלת שרשיהם ואני רואה אותם מיוסדים וחזקים כצורים וגבעות הללו ע\"י אבות ואמהות. . זכו לו אבותיו כו'\", להדגיש שאינו יכול להרע להם בדבורו מצד חביבותם לפני הקב\"ה;\nובנבואה הב' שמתחילה<sup data-n=\"1209\">16</sup> \"לא הביט און ביעקב גו'\" כתב רש\"י תחלה \"כתר­גומו\", ואח\"כ מביא פי' המדרש — כי דוקא לפי התרגום (\"לית פלחי גלולין בדבית יעקב ואף לא עבדי לאות שקר בישראל\"), מדבר במעלת ישראל עצמם, משא\"כ לפי המדרש אינו מדבר במעלת ישראל עצמם (מצד מעשיהם), אלא חבי­בותם כו' לפני הקב\"ה (דגם<sup data-n=\"1210\">17</sup> \"כשהן עוברין על דבריו אינו מדקדק אחריהן",[["1202","9","ומטעם זה דוחק לפרש שזה שלא הביא רש\"י פי' התרגום כפי' הראשון הוא משום שכיבוש ארץ ז' עממין אינו נוגע לבלק — שהרי זה מורה ומדגיש כחם וגבורתם שלא יוכל בלק לנגוע בהם וכ\"ש להכותם כו', ובמילא אם ילכו דרך ארצו כו' (ראה רש\"י פרשתנו כב, ה ד\"ה עם יצא ממצרים. שם, יא ד\"ה וגרשתיו) לא יוכל למונעם. וראה מלבי\"ם כאן."],["1203","10","מיכה ו, ה (הפטרת פרשתנו)."],["1204","11","כב, וא\"ו. וראה גם שם, יז. כג, יא. יג. ועוד."],["1205","12","לשון רש\"י עה\"פ (כג, כג) כי לא נחש ביעקב."],["1206","13","כג, ח."],["1207","14","כג, כ."],["1208","15","כג, ט."],["1209","16","כג, כא. משא\"כ ג' הפסוקים שלפנ\"ז הם הקדמה לנבואתו."],["1210","17","ומ\"מ מביא רש\"י גם פירוש זה, כי נוסף על הנ\"ל בפנים, שכל מה שאפשר להוסיף בפי' הכתובים במעלת ישראל מוסיפים, ובזה מודגש גודל מעלת וחביבות ישראל לפני הקב\"ה (שאינו בפי' הא' \"כתרגומו\"), שאינו מדקדק אחריהן כו', הרי ענין ש\"לא הביט\" משמעו שישנו \"און\" אלא ש\"לא הביט\" — אינו מתיישב כ\"כ לפי' הא' (ראה משכיל לדוד כאן. אבל ראה מה שהעיר עליו בבאר בשדה)."]]],[1301430209,"להתבונן באוניות שלהם ובעמלן שהם עוברים על דתו\")<sup data-n=\"1211\">18</sup>.\nועד\"ז הוא בכתוב דידן \"הן עם כלביא יקום וגו'\": לפי \"תרגומו\" שמדבר ע\"ד כיבוש הארץ \"לא ישרי בארעה עד דיקטול קטול ונכסי עממיא יירת\", הרי מדבר בעיקר עד\"ז שהקב\"ה יעשה עמ­הם. ולכן מקדים רש\"י פי' המדרש \"כש­הן עומדין משינתם שחרית הן מתגברים כלביא וכארי לחטוף את המצות כו'\", היינו שמדבר ע\"ד גודל המעלה במעשי­הם של ישראל<sup data-n=\"1212\">19</sup>, ואשר זהו סדר תמידי אצלם<sup data-n=\"1213\">20</sup>, בכל יום. ומזה מובן, שנוסף שאין שייך שבלעם יקללם ח\"ו, הרי יתי­רה מזו \"ראויים הם לברכה\"<sup data-n=\"1205\">12</sup>.\nג. ועפ\"ז יש לבאר גם הטעם שבפי' הא' משנה רש\"י מלשון המדרש:\nבמדרש אי'<sup data-n=\"1215\">21</sup> \"לא ישכב עד יאכל טרף כשהוא אומר ה' אחד נאכלין ה­מחבלין מפניו מלחשין אחריו ברוך שם כבוד מלכותו לעולם ועד ובורחין, והוא נסמך בזכות קריאת שמע משומרי היום לשומרי הלילה, וכשבא לישן מפקיד רוחו ביד הקב\"ה ואומר בידך אפקיד רוחי, וכשננער ממליך להקב\"ה, השומ­רין בלילה מוסרים אותו לשומרי היום שנאמר כו'\";\nואילו רש\"י כותב \"לא ישכב בלילה על מטתו עד שהוא אוכל ומחבל כל מזיק הבא לטרפו כיצד קורא את שמע על מטתו<sup data-n=\"1216\">22</sup> ומפקיד רוחו ביד המקום בא מחנה וגייס להזיקם הקב\"ה שומרם ו­נלחם מלחמותם ומפילם חללים\".\nהיינו, שרש\"י מוסיף ומדגיש בהתחלת הפירוש \"עד שהוא אוכל ומחבל כל מזיק כו'\", שנוסף על שמעשה הקב\"ה הוא בזכות פעולת האדם, הוא גם באופן שפעולת הקב\"ה עצמה מתייחסת למעשה האדם.\nד. אמנם יל\"ע בשינוי עיקרי ששינה רש\"י מהמדרש בתחלת פירושו — דב­מדרש אי' \"עמדו משנתן עומדים כאריות חוטפים קריאת שמע\", ורש\"י כותב \"לחטוף את המצות ללבוש ציצית לקרוא את שמע ולהניח תפילין\". ולפי פשוטו הביא רש\"י כל המצות שעושה אדם ב­שחרית תיכף כשקם משנתו, ולא רק ק\"ש. אבל יש להבין זה גופא, למה הוזקק רש\"י להוסיף על דברי המדרש ולהביא גם \"ללבוש ציצית\" ו\"להניח תפלין\".\nגם צריך להבין הסדר שבו מנה רש\"י ג' מצות אלה — ציצית, ק\"ש ותפילין<sup data-n=\"1217\">23</sup> —",[["1211","18","ולכן כ' בפסוק כי לא נחש ביעקב (כג, כג (בסופו)) \"ואונקלוס לא תרגם כן\", שכוונתו לשלול כאן פי' אונקלוס, כי לפי תרגומו אין הכתוב מדבר במעלת ישראל — כמבואר בלקו\"ש חי\"ח <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181277\" data-slug=\"likkutei-sichot\" data-id=\"1300181277\">שם ע' 268</a> ואילך."],["1212","19","ועוד י\"ל בזה, שלפני נבואה זו (הב') אמר בלק לבלעם (כג, יג) \"אפס קצהו תראה וכולו לא תראה\", שכוונתו, שאף שלא יכול להרע הכלל, \"כי מראש צורים אראנו גו'\", מ\"מ יכול להרע מקצתם כו' (ראה ספורנו שם), ולכן מסתבר שגם בלעם בנבואתו אמר דבר השייך (לא רק לעם ישראל כצבור, אלא גם) ליחידים."],["1213","20","כמו בהמשל, ש\"כלביא יקום וכארי יתנשא לא ישכב עד יאכל טרף גו'\" ה\"ז סדר הנהגה יום יומית של לביא וארי (משא\"כ להתרגום דקאי ב­כיבוש ז' עממין)."],["1205","12","לשון רש\"י עה\"פ (כג, כג) כי לא נחש ביעקב."],["1215","21","תנחומא, ועד\"ז בבמדב\"ר ויל\"ש עה\"פ (רמז תשסט)."],["1216","22","תיבות אלו \"שהוא אוכל. . מטתו\" ליתא בדפוס ראשון."],["1217","23","כ\"ה בדפוס ראשון, דפוס שני ורוב כת\"י רש\"י (שתח\"י). אבל בכמה כת\"י רש\"י (שתח\"י) ה­סדר: ציצית, תפילין וקריאת שמע. וכן הובא בבחיי כאן."]]],[1301430210,"שאינו לפי סדרן בפרשיות התורה (ש­תחלה נאמר פ' תפלין (בפ' בא), אח\"כ פ' ציצית (בפ' שלח) ולבסוף (ולאחרי פרשתנו) פ' ק\"ש (בפ' ואתחנן))<sup data-n=\"1218\">24</sup>; וכן<sup data-n=\"1219\">25</sup> לא כפי סדר עשייתן<sup data-n=\"1220\">26</sup> ע\"י האדם, דאף שהמנהג הוא שלובשים ציצית בבוקר תיכף לאחרי נט\"י<sup data-n=\"1221\">27</sup>, ולאח\"ז קורין ק\"ש, הרי ק\"ש באה לאחרי הנחת תפילין<sup data-n=\"1222\">28</sup>, וכדאיתא בגמ'<sup data-n=\"1223\">29</sup> \"כל הקורא ק\"ש בלא תפילין כאילו מעיד עדות שקר בעצמו כו'\" (וכמובא במפרשי רש\"י כאן<sup data-n=\"1224\">30</sup>)?\nויובן בהקדם עוד שינוי בלשון רש\"י ללשון המדרש: במדרש<sup data-n=\"1215\">21</sup> נאמר \"הרי הן ישנים מן התורה ומן המצות עמדו משנתן עומדים כאריות חוטפים קריאת שמע וממליכים להקב\"ה\", וברש\"י הלשון \"כשהן עומדין משינתם שחרית הן מתגב­רים כלביא וכארי לחטוף את המצות ללבוש כו'\". כלומר א) רש\"י משמיט מ\"ש במדרש \"הן ישנים מן התורה ומן ה­מצות\". ב) מוסיף על לשון המדרש הקדמה כללית — \"לחטוף את המצות\". ג) משמיט תוכן מצות ק\"ש המפורש במדרש \"וממליכים להקב\"ה\".\nויש לומר, שג' שינויים אלה תלויים זב\"ז:\nבמדרש שכתב \"הרי הן ישנים מן התורה ומן המצות\", מדגיש שהשינה היא (גם) שינה רוחנית<sup data-n=\"1226\">31</sup>, שאינם ערים לתורה ומצות של הקב\"ה, וה\"עמידה\" מ\"שינה\" זו כוללת גם ההתעוררות לתומ\"צ, שמ­קבלים עליהם עול מלכות שמים, וזהו שממשיך במדרש \"עמדו משנתן עומדים כאריות חוטפים קריאת שמע וממליכים להקב\"ה\".\nאבל ברש\"י שכ' כפשוטו, עומדים מ­שינת שחרית, היינו בזמן שאינם (חייבים ואינם) יכולים לקיים המצות, לכן תיכף כשעומדים הם מתגברים \"לחטוף את המצות\", היינו מצות בכלל, שכל המצות לא היו יכולים לקיימן בעת השינה.\nולכן כתבם בסדר זה דוקא, כי זהו לפי סדרן ביחס לכללות המצות:\nתחילה \"ללבוש ציצית\", שמצות ציצית שקולה כנגד כל המצות<sup data-n=\"1227\">32</sup>, וכמ\"ש בפרשת ציצית<sup data-n=\"1228\">33</sup> \"וראיתם אותו וזכרתם",[["1218","24","ודוחק גדול לומר שלא מנה תפילין שלפני הדיבור (פ' בא) כ\"א זה שלאחרי הדיבור (בסיום פ' שמע והי' אם שמוע)."],["1219","25","וגם לא לפי סדר קדושתן, דתפילין הוה מקודש לגבי ציצית, דתפילין הם תשמישי קדושה וציצית הם רק תשמישי מצוה — ראה בארוכה שאגת ארי' סי' כח, שמטעם זה הי' צריך להניח תפילין לפני לבישת הציצית. וראה זח\"ג פא, א ובמפרשים שם. לקוטי לוי\"צ לזהר שם. וראה פרמ\"ג בפתיחתו להל' תפילין בתחלתה. ואכ\"מ."],["1220","26","ולהעיר שגם זמן חיובן אחד הוא, משיראה את חבירו מרחוק ד\"א כו' — ראה הדיעות (ב\"י, ב\"ח, פרמ\"ג (משב\"ז) ועוד או\"ח רסנ\"ח). ולהעיר מגמ' מנחות שבהערה 40."],["1221","27","ראה טור, מג\"א ושו\"ע אדה\"ז או\"ח ר\"ס ח."],["1222","28","אלא שי\"ל שלדעת רש\"י נוהגין כן שקוראין ק\"ש לפני הנחת תפילין כהדיעות בזה — ראה שו\"ת בית יצחק או\"ח (סי\"ז) ואות חיים ושלום (לבעל מנח\"א) סכ\"ה סק\"ו — ע\"ד מנהג חסידים ואנשי מעשה לקרות ק\"ש בבוקר כשיעמדו ממטתם פן יעברו זמן ק\"ש, ושקו\"ט והאריכו בסדר ק\"ש ותפילין. ועיין בבית יצחק שם אות ב שמיישב דברי רש\"י בפרשתנו, כי לדידן דשבת לאו זמן תפילין הוי ק\"ש תדיר, ותדיר קודם. ע\"ש בארוכה. וראה שיחת ש\"פ שלח תשי\"ב."],["1223","29","ברכות יד, סע\"ב. וש\"נ."],["1224","30","ראה משכיל לדוד, שם אפרים, באר בשדה ועוד."],["1215","21","תנחומא, ועד\"ז בבמדב\"ר ויל\"ש עה\"פ (רמז תשסט)."],["1226","31","ראה שהש\"ר עה\"פ (שה\"ש ה, ב) אני ישנה ולבי ער. זח\"ג צה, א."],["1227","32","הובא גם בפרש\"י ס\"פ שלח טו, מא."],["1228","33","שם, לט. מ."]]],[1301430211,"את כל מצות ה' ועשיתם אותם\", \"למען תזכרו ועשיתם את כל מצותי\" [וכדאיתא בגמ'<sup data-n=\"1229\">34</sup> \"ולימא להו. . קיימו כל המצות כולן\" ומשני (דאז הי' קאי על) \"מצות ציצית<sup data-n=\"1230\">35</sup> דאמר מר שקולה מצות ציצית כנגד כל המצות כולן\"<sup data-n=\"1231\">36</sup>, ובספרי<sup data-n=\"1232\">37</sup> איתא ש\"כל המקיים מצות ציצית מעלים עליו כאילו קיים כל המצות\"]; ואח\"כ מביא \"לקרוא את שמע\", שגם היא מצוה כללית, שיש בה יחוד השם אהבתו כו' (ובכללות — קבלת עול מלכות שמים) שהיא יסוד<sup data-n=\"1233\">38</sup> כל המצות<sup data-n=\"1234\">39</sup>, אבל לא כמו מצות ציצית שהיא עצמה שקולה כנגד כל המצות (ומביאה לקיום כל המצות כולן) כנ\"ל<sup data-n=\"1235\">40</sup>; ואח\"כ \"ולהניח תפילין\", שהיא מצוה פרטית, אבל נאמר בה \"והי' לך לאות על ידך ולזכרון בין עיניך. . כי ביד חזקה הוציאך ה' ממצרים\"<sup data-n=\"1236\">41</sup>, ש­זכירת יצי\"מ היא יסוד לכמה מצוות התורה<sup data-n=\"1237\">42</sup>.\nה. ויש להוסיף בזה, שע\"פ הנ\"ל ה­חילוק בין פרש\"י ודברי המדרש הוא, אם קריאת שמע בבוקר היא (רק) בגדר דחטיפת קבלת עול מלכות שמים או שהיא בגדר דחטיפת כל מעשה המצוות.\nויש לומר, שזה תלוי בפלוגתא אם מצות ק\"ש מה\"ת היא רק פסוק ראשון בלבד או שכוללת יותר מזה (פרשה ראשונה, שתי פרשיות, או שלשתן)<sup data-n=\"1238\">43</sup>, והיינו אם גדר מצות ק\"ש הוא זה ש­ממליך את הקב\"ה עליו באמירת פסוק ראשון<sup data-n=\"1239\">44</sup> \"שמע ישראל ה' אלקינו ה' אחד\", שבו מקבל עליו יחודו ית' בפי­רוש<sup data-n=\"1240\">45</sup>, או שגדר מצות ק\"ש כוללת קבלת עול מצות (וכמפורש במשנה לגבי ב' פרשיות דק\"ש<sup data-n=\"1241\">46</sup>):\nלהמדרש, גדר ק\"ש הוא שממליכים את הקב\"ה והוא (בעיקר) בפסוק ראשון (או גם פרשה ראשונה<sup data-n=\"1242\">47</sup>), וכמשמע גם מהמשך דברי המדרש כנ\"ל \"ממליך להקב\"ה לא ישכב עד יאכל טרף כשהוא אומר ה' אחד נאכלין המחבלין מפניו, מלחשין אחריו ברוך שם כבוד מלכותו לעולם ועד\".",[["1229","34","נדרים כה, א. שבועות כט, סע\"א."],["1230","35","וראה תוד\"ה מצות ציצית שבועות שם: הא דשבק ע\"ז כו' משום דבלשון בנ\"א לא מקרי כל המצות אלא ציצית."],["1231","36","כ\"ה בשבועות שם. ועד\"ז הוא במנחות מג, ב. ובנדרים \"כנגד כל מצות שבתורה\". וראה פרש\"י שבועות ומנחות שם (ובנמוק\"י הל' ציצית (הובא בב\"י (וראה גם ב\"ח) או\"ח ר\"ס כה), שמטעם זה מתעטפין בציצית לפני תפילין)."],["1232","37","שלח טו, לט. הובא בספר הפרדס לרש\"י ריש הל' ציצית. בשבלי הלקט מהל' ציצית (של רש\"י). ועוד."],["1233","38","ראה לשון הרמב\"ם הל' ק\"ש פ\"א ה\"ב. וראה לקמן בפנים."],["1234","39","ולהעיר ממנחות שם: \"ראה מצוה זו וזכור מצוה אחרת התלוי' בו ואיזו זו זו קרית שמע\", ובחדא\"ג מהרש\"א שם \"דהיא (ק\"ש) נקראת כל מצות ה' שיש בק\"ש עיקר האמונה קבלת מלכות ואחדות כו' נמצא כשנזהר בק\"ש שמפורש בה כלל אמונה זוכר את כלל המצות כולן\"."],["1235","40","ולהעיר גם מ\"תניא אידך\" במנחות שם: וראיתם אותו וזכרתם את כל מצות ה', כיון שנתחייב אדם במצוה זו נתחייב בכל המצות כולן. וראה פרש\"י שם."],["1236","41","בא יג, ט ובפרש\"י. וראה גם שם, טז."],["1237","42","ראה חינוך מצוה טז. כא. ועוד."],["1238","43","ראה קרית ספר (להמבי\"ט) ריש הל' ק\"ש. פר\"ח (ונ\"כ השו\"ע) או\"ח סי' סז. שו\"ת שאג\"א סי' ב'. פרמ\"ג בהקדמתו לאו\"ח הלכות ק\"ש. ובכ\"מ. וראה שו\"ע אדה\"ז ר\"ס נח. וש\"נ. ועוד."],["1239","44","ואתחנן ו, ד."],["1240","45","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310052\" data-slug=\"tanya\" data-id=\"3401310052\">תניא פמ\"ז</a>."],["1241","46","ברכות יג, א. וראה שם ע\"ב. יד, ב. ובמפרשים שם."],["1242","47","ראה תר\"י שהובאו בב\"י או\"ח סו\"ס סג. וראה לשון הרמב\"ם הל' ק\"ש פ\"א ה\"ב."]]],[1301430212,"ואילו לפרש\"י גדר מצות ק\"ש כולל שממליכים את הקב\"ה בה' אחד, קבלת עומ\"ש בפרשה ראשונה, וקבלת עול מצות, ולכן כולל ב\"לחטוף את המצות\" גם קריאת שמע.\n[ואולי י\"ל יתירה מזו, שלדעת רש\"י (בפירושו עה\"ת) מצות ק\"ש כוללת גם פרשה שלישית, כי אין קיום מצות ק\"ש בשלימותה בקבלת עול מצות בכלל אלא כאשר מקבל עליו מצות ציצית<sup data-n=\"1243\">48</sup> הכוללת (זכירת) כל המצות כולן<sup data-n=\"1244\">49</sup>. ולכן כאשר בא לקיים המצות כדבעי (שזהו תוכן הענין ד\"לחטוף את המצות\" כד­לקמן ס\"ו) (גם מצות ק\"ש), הרי אינו מסתפק בזה שקורא פרשת ציצית, אלא לובש ציצית ואח\"כ קורא את שמע (כולל פרשת ציצית), כדי שתהא זכירת כל המצות ע\"י מצות ציצית<sup data-n=\"1245\">50</sup> בפועל<sup data-n=\"1246\">51</sup>].\nו. וע\"פ מה שנתבאר לעיל (ס\"ב), ש­הקדים רש\"י פי' המדרש לתרגומו, כי ע\"פ פשש\"מ מסתבר יותר (בפרט בנבואה זו (השני') דבלעם) שמדבר במעלת ישר­אל במעשיהם, ולא רק זה שהקב\"ה עושה עמהם (שמראה גודל כחם כו' כלפי אוה\"ע), יש לבאר הטעם ששינה רש\"י בענין זה מהמדרש:\nחטיפה מורה שהדבר הנחטף חביב ביותר אצל החוטף<sup data-n=\"1247\">52</sup>, דדבר שאינו יקר וחביב לו כ\"כ לוקחו בניחותא, משא\"כ דבר החביב עליו — חוטפו.\nולפ\"ז מובן, דענין \"חוטפים ק\"ש וממ­ליכים להקב\"ה\" שבמדרש מורה שענין ה\"חטיפה\" הוא רק לגבי עצם קבלת עול מלכותו ית', אבל קיום התומ\"צ שלאח\"ז בא באופן רגיל, בניחותא.\n[ולכן לא נזכר במדרש בהמשך לזה קיום המצות, אלא \"מפליגין לדרך ארץ למשא ומתן\", כי בקיום המצות עצמן לא ניכרת מעלה מיוחדת בקיומם, והמלכת הקב\"ה בק\"ש באופן שחוטפין ק\"ש מועי­לה להם דכאשר מפליגין לדרך ארץ ו­למשא ולמתן תהי' הפלגה זו באופן כשר, משאו ומתנו באמונה<sup data-n=\"1248\">53</sup>, ו\"כל מעשיך יהיו לשם שמים\"<sup data-n=\"1249\">54</sup>, וכיו\"ב].\nואילו לפרש\"י טבע בני ישראל הוא שכשהם עומדים משנתם שחרית הן מתגברים \"לחטוף את המצות\", שכל ה­מצות יקרים וחביבים הם אצל כאו\"א מישראל, שחוטפין את המצות, ואינו מסתפק בחטיפת מצוה אחת, אלא שחוט­",[["1243","48","ראה ברכות יב, ב: \"פרשת ציצית מפני מה קבעוה כו' מפני שיש בה חמשה דברים מצות ציצית יצי\"מ עול מצות כו'\". ע\"ש."],["1244","49","ראה רמב\"ם שם ובנו\"כ שם. ובהנסמן בהערה 43."],["1245","50","להעיר מפרש\"י ברכות שם שפי' מ\"ש בגמ' \"עול מצות\" — \"ועשיתם את כל מצותי\", ואינו מובן שהרי בש\"ס מפורש \"עול מצות וראיתם אותו ו­זכרתם את כל מצות ה'\"? אלא שרש\"י מפרש הכוונה בגמ' שבשביל קבלת \"עול מצות\" אמיתית אינו מספיק \"וראיתם אותו וזכרתם גו'\" — רק זכירת המצות, אלא צ\"ל (גם) \"ועשיתם את כל מצותי\", קבלת עשייתן בפועל. וראה לשון הרמב\"ם הל' ק\"ש שם ובנ\"כ שם. וראה לעיל ע' 100 הערה *46. ועצ\"ע."],["1246","51","ולהעיר מברכות שם (יד, סע\"ב ואילך): \"הרוצה שיקבל עליו עומ\"ש שלימה כו' יניח תפילין ויקרא ק\"ש ויתפלל\", ושקו\"ט למה לא הובא ציצית — ראה ב\"ח ופרישה לטאו\"ח סו\"ס ב. שו\"ע אדה\"ז סי' סו ס\"ג וסי\"א. ועוד."],["1247","52","ראה חולין קלג, א. אלא דלמסקנא שם ישנו לימוד מיוחד \"ונתן ולא שיטול מעצמו\", ולכן לא הוי חביבותא. וגם מובן הוא כיון שהמדובר בדבר שהוא לאכילה והנאת הגוף, משא\"כ בנדו\"ד דקיום מצות שאין בה הנאת הגוף. וראה ברכות (נג, ב) \"חטוף ובריך\"."],["1248","53","שבת לא, סע\"א."],["1249","54","אבות פ\"ב מי\"ב. רמב\"ם ספ\"ג מהל' דיעות."]]],[1301430213,"פים עוד מצוה, קריאת שמע, וחוטפים עוד מצוה, הנחת תפילין, ומובן שכן הוא בהמשך כל היום כולו בקיום מצותיו של הקב\"ה.\nוזה מבטא אופן נעלה יותר במעלתן של ישראל.\nז. ע\"פ הנ\"ל תובן גם השייכות דפ' בלק (שקורין בכל שנה בסמיכות) לי\"ב תמוז, היום שבו נגאל כ\"ק מו\"ח אדמו\"ר ממאסרו אשר נאסר בגלל \"העבודה ה­גדולה\" אשר עבד \"בהרבצת תורה וחי­זוק הדת\"<sup data-n=\"1250\">55</sup>.\nהפירוש ד\"חטיפה\" הוא — פעולה ש­לא ע\"פ סדר וחשבון, ובעבודת ה' ה\"ז מורה על עבודה שלמעלה מטעם ודעת, העבודה דמסירת נפש<sup data-n=\"1251\">56</sup>.\nוזה הי' אופן העבודה הגדולה אשר עבד כ\"ק מו\"ח אדמו\"ר במדינה ההיא, ואשר בה חינך ולימד את תלמידיו ו­חסידיו, עבודה באופן של מסירת נפש בפועל, ולא רק על ענינים כלליים ו­ענינים עיקריים של תורה ומצות, אלא על כל מצוה ומצוה, קלה כחמורה, מס\"נ על בנין או החזקת מקוה, לייסד חדרים ללמוד עם תשב\"ר אל\"ף­בי\"ת וכיו\"ב, וביחד עם זה ובאותו התוקף ומסנ\"פ להפצת פנימיות התורה, רזין דאורייתא, וכן מס\"נ על הידור במצות.\n[וגם באופן עבודה זו דחטיפה, מסנ\"פ על כל צעד, בקש ותבע בשיחותיו ב­אותו הזמן<sup data-n=\"1252\">57</sup> חטיפה בתוך חטיפה, מס\"נ בתוך מס\"נ, \"יהודים חיטפו מס\"נ חיטפו, כי עובר וחולף הזמן של מסנ\"פ, עוד מעט ויבוא זמן של חופש גמור בעניני הדת ואז תחפשו אופן דמסירת נפש ולא תמצאו, עוד מעט ויבוא זמן שתדברו במעלתו של מי שזכה \"לשבת\" (בבית האסורים) בגלל היותו מלמד, בגלל החזיקו חדר, ישיבה או מקוה טהרה. תתקנאו בהם ותצטערו על עצמכם שאתם לא זכיתם לכך, יהודים — חיטפו מסנ\"פ\"].\nובכח זה עמדו בנ\"י במדינה ההיא במשך עשיריות בשנים במצב של גזירות ורדיפות על הדת, וכח זה הטביע ב­שלוחיו ובהולכים באורחותיו, אשר גם בהיותם בחסדי ה' במצב של חירות לא יסתפקו באופן של חוטפין ק\"ש להמליך עליהם את הקב\"ה, אלא שתהי' אצלם גם העבודה לחטוף את המצות — כל ה­מצות, ולא להתחשב בשום חשבונות ומניעות ועיכובים, ולא להתפעל ממלעי­גים כו', הן בעבודת ה' בעצמה, והן ב­הפצת התורה והיהדות.\nעדי קיום היעוד המפורש בפרשת בלעם<sup data-n=\"1253\">58</sup> \"וקם<sup data-n=\"1254\">59</sup> שבט מישראל. . והי' ירשה גו' זה המלך המשיח שנאמר<sup data-n=\"1255\">60</sup> ועלו מושיעים בהר ציון וגו' והיתה לה' המלוכה\".\n<span data-k=\"q\">(משיחת ש\"פ בלק תשל\"א)</span>",[["1250","55","לשון כ\"ק מו\"ח אדמו\"ר במכתבו לחגיגת י\"ב תמוז הראשונה בשנת תרפ\"ח — נדפס בסה\"מ תרפ\"ח ע' קמו. תש\"ח ע' 263. אג\"ק שלו ח\"ב ע' פ. ועוד."],["1251","56","וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251279\" data-slug=\"likkutei-sichot\" data-id=\"1300251279\">לקו\"ש חכ\"ה ע' 279</a> ואילך שחטיפה מורה על לקיחת דבר היפך רצונו דמנגד, והו\"ע עבודת התשובה. ע\"ש. וש\"נ."],["1252","57","י\"ט כסלו תרפ\"ז (שנת המאסר) — סה\"ש תרפ\"ז ע' 120 ואילך, הובא בס' התולדות אדמו\"ר מהוריי\"ץ ח\"ג (קה\"ת תשל\"ב ושלאח\"ז) ע' 55."],["1253","58","רמב\"ם הל' מלכים פי\"א ה\"א."],["1254","59","פרשתנו כד, יז­יח."],["1255","60","עובדי' א, כא."]]],[1301430214,"<h3>שיחה א</h3>\nא. כ\"ק מו\"ח אדמו\"ר סיפר<sup data-n=\"1256\">1</sup>, שבשנת תר\"מ<sup data-n=\"1257\">2</sup>, בש\"ק י\"ז בתמוז, הי' זקנו אדמו\"ר מהר\"ש בשמחה גדולה, והזכיר כמה פעמים<sup data-n=\"1258\">3</sup> ששבת זה נקרא \"נדחה\", כי צום שבעה עשר בתמוז נדחה ע\"י ש\"ק, וסיים \"הלואי שיהי' נדחה באמת\".\nוהנה לפי פשוטם, דברי אדמו\"ר מהר\"ש הם בגדר ברכה ותפלה (וכמו ש­סיים כ\"ק מו\"ח אדמו\"ר: ברכה של צדיק הלא מתקיימת, הלואי שכן יהי', ושיהי' נדחה באמת ויהפך לששון ולשמחה). אבל (נוסף לזה שאפילו שיחות חולין של ת\"ח צריכין לימוד<sup data-n=\"1259\">4</sup>, וכ\"ש וק\"ו תפי­לותיהם וברכותיהם, הרי) ע\"פ הידוע גודל הדיוק בדברי רבותינו נשיאינו, יש לומר, שבדיוק לשונו טמון ומרומז תוכנו של תענית נדחה, הן ע\"פ הלכה, והן ע\"פ פנימיות התורה.\nב. בהשקפה ראשונה הקשר בין ד­חיית צום (י\"ז תמוז) ע\"י יום השבת ל­דחייתו לגמרי לעתיד לבוא, פשוט הוא, דאין זה רק דחי' מזמנו הקבוע לזמן אחר, אלא שהדחי' פועלת גם המעטה בחומר התענית, כי הצום הנדחה (ליום ראשון) קיל מכשהוא בזמנו [וכמפורש בהלכה לענין ברית מילה<sup data-n=\"1260\">5</sup>, דכאשר ה­צום הוא בזמנו חייב בעל הברית להש­לים התענית, אבל כשחל בשבת ונדחה ליום הראשון אין בעל הברית משלים תעניתו<sup data-n=\"1261\">6</sup> מפני שיו\"ט שלו הוא], ומכיון שנתמעט חומר התענית הרי י\"ל שזוהי התחלה לביטולה לגמרי.\nויסוד לזה (שדחיית התענית ממעטת חומרתו, עד שנותנת מקום לדחייתה לגמרי) הוא בדברי רבי<sup data-n=\"1262\">7</sup> לענין \"תשעה באב שחל להיות בשבת. . ודחינוהו ל­אחר השבת ואמר רבי הואיל ונדחה ידחה\", היינו דס\"ל שכיון שאי אפשר ל­התענות בזמנו, בטל חיוב התענית לגמרי בשנה כזו.\nועפ\"ז יש לבאר דברי אדמו\"ר מהר\"ש<sup data-n=\"1263\">8</sup> בהקדם ביאור והסברה בדברי רבי הנ\"ל \"הואיל ונדחה ידחה\".\nג. בגמ' שם פליגי חכמים על דברי רבי, ולכאורה י\"ל שתוכן הפלוגתא הוא — אם הדחי' משבת ליום א' עושה יום א' \"זמנו\" של התענית (וזוהי דעת חכמים).\n[ועפ\"ז י\"ל שרבי ורבנן לשיטתייהו",[["1256","1","שיחת י\"ב תמוז (יום הולדת וחג הגאולה שלו) ה'ש\"ת (נדפס בספר השיחות ה'ש\"ת ע' 157)."],["1257","2","השנה שבה נולד כ\"ק מו\"ח אדמו\"ר — שהקביעות היתה (כבשנה זו (תשמ\"ח)) די\"ב תמוז חל ביום שני, ובמילא י\"ז תמוז הוא בש\"ק ונדחה."],["1258","3","בליל ש\"ק (בה\"שלום זכר\") וביום השבת."],["1259","4","סוכה כא, ב. ע\"ז יט, ב."],["1260","5","בת\"ב — טושו\"ע סי' תקנט ס\"ט. ב\"י שם. וראה מג\"א שם סקי\"א (ובמחה\"ש) דכ\"ה בנוגע לשאר הצומות י\"ז בתמוז וכו', דרק כשנדחה אין בעל הברית משלים תעניתו."],["1261","6","וראה הגהות רעק\"א בשו\"ע שם (מתשובת שבות יעקב): וכן בחולי קצת ומעוברת שיש מיחוש קצת מותרים לאכול. וראה שד\"ח פאת השדה (אסיפת דינים) מע' בין המצרים ס\"א אות יג (ח\"ט א'תשסב, א) עוד קולות בתענית שבעה עשר בתמוז כו' נדחה."],["1262","7","מגילה ה, ריש ע\"ב."],["1263","8","ולכאורה כש\"כ הוא, דהרי בנוגע לת\"ב אמר ר\"י (תענית כט, א) \"אלמלי הייתי באותו הדור לא קבעתיו אלא בעשירי מפני שרובו של היכל בו נשרף\" (וראה תוד\"ה ובקש (מגילה שם) בתירוץ הב', שזוהי הס\"ד בדברי ר\"א דביקש רבי לעקור ת\"ב), משא\"כ בדחיית שבעה עשר בתמוז לי\"ח תמוז דקיל טפי. אבל ראה שו\"ת חת\"ס או\"ח סל\"ג, וראה במקומות שנסמנו לקמן הערה 11."]]],[1301430215,"אזלי, ד\"תניא<sup data-n=\"1264\">9</sup> חל (י\"ד אדר) להיות ב­שבת כפרים מקדימין ליום הכניסה ו­עיירות גדולות קורין בע\"ש כו' רבי אומר אומר אני הואיל ונדחו עיירות ממקומן ידחו ליום הכניסה. . זמנם שבת היא והואיל דנדחו ידחו\", שרבי סבירא לי' שהתקנה דמקרא מגילה היתה שבכל שנה יקראו פרזות בי\"ד ומוקפין בט\"ו, אלא שמפני גזירה דרבה דחו תקנה זו<sup data-n=\"1265\">10</sup>, ורבנן ס\"ל שמפני גזירה דרבה היתה מלכתחילה התקנה דמקרא מגילה שכש­יחול י\"ד בשבת יקדימו את זמנה].\nוע\"ד השקו\"ט באחרונים כעין זה ב­נוגע להלכה בפועל<sup data-n=\"1266\">11</sup>, אם חיוב התענית בצום הנדחה משבת ליום א' הוא בתורת תשלומין או שכן היתה התקנה מעיקרא, שכשחל בשבת נקבע זמן התענית ליום ראשון. וכתבו כמה נפק\"מ לדינא, ול­דוגמא: א) קטן שנתגדל ביו\"ד באב, דאם זהו יום התענית (בשנה זו), אזי יש חיוב על הקטן להתענות כיון שגדל בו ביום. אבל אם התענית ביום א' הוי רק תש­לומין להתענית דט' באב (שחל בשבת), הרי כיון שביום התענית עדיין אינו בר חיובא, שוב אינו חייב בתשלומין. ב) מתי חל הדין (וחומרא) דשבוע שחל בו תשעה באב<sup data-n=\"1267\">*11</sup>, דאת\"ל דחיוב התענית דיום א' (הנדחה) הוא מעיקר התקנה, א\"כ השבוע שלפני השבת אינו שבוע שחל בו ת\"ב<sup data-n=\"1268\">12</sup>, משא\"כ אם יום א' הוי בגדר ה­שלמה, הרי השבוע שלפנ\"ז הוא השבוע שחל בו ת\"ב<sup data-n=\"1269\">*12</sup>, כיון דדין ת\"ב לא בטל ע\"י יום השבת ומחוייב בתשלומין. ג) ל­ענין אבילות בדברים שבצנעה, אם נוה­גין בת\"ב שחל בשבת: הדיעות שאין נוהגין דברים שבצנעה ס\"ל שלגמרי עקרוהו ואוקמינהו אעשירי<sup data-n=\"1270\">13</sup>, משא\"כ ה­דיעות שנוהגין דברים שבצנעה בשבת.\nאבל דוחק קצת לפרש כן פלוגתת רבי ורבנן בדחיית תענית ת\"ב, דכיון שלא קיי\"ל כרבי (כי לא הודו לו חכ­מים), נמצא שלהלכה אין זה דחי', אלא דבשנה זו תענית ת\"ב זמנו הוא ביום א' (מעיקר הדין והתקנה); אבל בשו\"ע",[["1264","9","מגילה ד, ב."],["1265","10","וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071050\" data-slug=\"likkutei-sichot\" data-id=\"1300071050\">לקו\"ש ח\"ז ע' 50</a> ואילך ובהערות שם, שאין סברא לומר שפלוגתתם היא בזמן התקנה — דרבנן סברי שביחד עם תקנת מקרא מגילה תקנו אנשי כנה\"ג שכשחל בשבת קורין עיירות גדולות בע\"ש, ורבי סבר שתקנת הקדימה היתה ע\"י חכמי ישראל שאחר כנה\"ג (ראה רש\"י מגילה ה, א ד\"ה ערב שבת) — אלא י\"ל דלכו\"ע היתה התקנה על ידי אנשי כנה\"ג, ופליגי באיזה אופן דחוהו. וי\"ל שעד\"ז הוא בנדו\"ד דהרי בעת שגזרו להתענות ידעו שיזדמן שיחול בש\"ק ופליגי באופן תקנת הדחי'. אבל צ\"ע בלשון הגמרא \"ודחינוהו לאחר השבת ואמר רבי הואיל ונדחה כו'\". ואכ\"מ."],["1266","11","בכל הבא לקמן ראה צפע\"נ הפלאה ב­השמטות (נד, סע\"ג ואילך). מהד\"ת כח, ג. שו\"ת דווינסק ח\"ב סל\"א­לב. שו\"ת ווארשא (נ.י.) ח\"א סמ\"ד. שו\"ת אבני נזר או\"ח סי' תכו. שו\"ת כתב סופר או\"ח סק\"א. מהרש\"ם ח\"ג סשס\"ג. ועוד."],["1267","*11","ראה ב' הדיעות בטושו\"ע או\"ח סתקנ\"א ס\"ד."],["1268","12","להעיר ממהרי\"ל הל' ת\"ב: כאילו איקלע קביעותא בא' בשבת דמי."],["1269","*12","ראה מג\"א שם סקי\"ז. וראה צפע\"נ שבהערה 11, שלהסברא שהתענית ביום א' \"הוי גדר תשלום\" — אין כאן הדין ד\"לאחריו\" (כמ\"ש בירושלמי תענית פ\"ד ה\"ו. אלא דשם, שאז גם אין הדין ד\"לפניו\". ולהעיר מסמ\"ק (סי' צו. הובא בטור שם) שגם להדיעה דיש דין דלפניו (כשחל ת\"ב בשבת), \"הוא רק חומרא יתירה\", כי יש חילוק \"בין חל להיות בתוכה בין חל להיות בשבת\")."],["1270","13","שו\"ת הרשב\"א ח\"א סתק\"כ (הובא באבני נזר שם בסופו. ועוד)."]]],[1301430216,"מפורש<sup data-n=\"1271\">14</sup> (כנ\"ל) שדוקא \"ט' באב שחל להיות בשבת ונדחה ליום ראשון, בעל ברית מתפלל מנחה בעוד היום גדול ורוחץ ואינו משלים תעניתו לפי שיום טוב שלו הוא\", משא\"כ כשהברית מילה היא בת\"ב עצמו חייב הוא להשלים<sup data-n=\"1272\">15</sup> — הרי מובן מזה, שלהלכה קיי\"ל דת\"ב שנדחה ליום א' אינו חמור כת\"ב שלא נדחה היינו שהוא בגדר דחי' ואינו מ­עיקר התקנה (דאל\"כ מדוע מקילים בו לענין בעל ברית)<sup data-n=\"1273\">16</sup>.\nוע\"כ צ\"ל שגם לדעת רבנן, התענית ביום א', כשחל ת\"ב בשבת, ה\"ז בגדר דחי', ולכן אינו חמור כתענית שביום ת\"ב עצמו — ופלוגתת רבי ורבנן היא ב­גדרה של \"דחי'\" זו עצמה, שיש לפרשה בכמה אופנים, כדלקמן.\nד. מבואר באחרונים<sup data-n=\"1274\">17</sup>, שבתענית יש ב' ענינים (ואופנים): חלות שם תענית על היום, וחלות דיני וחיובי התענית על האדם<sup data-n=\"1275\">18</sup>.\nולפי זה י\"ל, דפלוגתת רבי ורבנן אינה בחומרת התענית דיום ראשון (שנד­חית משבת), אלא בגדרו של יום השבת שהתענית שבו נדחית — אם הדחי' בשבת היא רק בקיום דיני התענית, אבל נשאר בה ענין יום תענית — וזוהי דעת רבנן; או שנדחה בשבת גם ענין יום התענית — והיא דעת רבי, דרבי ס\"ל שלגמרי נדחה חלות יום התענית ובכה\"ג אין חלות יום תענית (אלא כיון שהתענית רק נדחה, נשארו איזה דיני ת\"ב, כמו דברים שב­צנעה<sup data-n=\"1276\">*18</sup> וכיו\"ב).\nאבל דבר זה צריך ביאור, דאיך אפשר לומר שיש ענין תענית ביום ד­שבת, הרי שבת אסור בתענית, ואדרבה יש חיוב לענגו באכו\"ש וכו'<sup data-n=\"1277\">19</sup>, ולכמה דיעות<sup data-n=\"1278\">20</sup> איסור התענית בו הוא מדאו­רייתא (וכתב אדה\"ז<sup data-n=\"1279\">21</sup>, דאיסור התענית נפק\"ל מדכתיב<sup data-n=\"1280\">22</sup> \"אכלוהו היום כי שבת היום לה'\", מכלל דבשבת אסור להת­ענות).\nויש לומר בביאור הדבר (בפנימיות הענינים):",[["1271","14","סי' תקנט ס\"ט. וכ\"ה בטור שם."],["1272","15","כמ\"ש המג\"א שם בשם הב\"י. ואף שהב\"י לא כתבו בשו\"ע בפירוש, הרי מובן הוא מזה שכתב הדין רק בת\"ב שחל בשבת."],["1273","16","אלא שצ\"ע בדעת השו\"ע, שהרי בסתקנ\"א ס\"ד הביא ב' דיעות בת\"ב שחל בשבת \"אם מותר בשתי שבתות\"; ולענין דברים שבצנעה כ' (סתקנ\"ד סי\"ט) דת\"ב שחל בשבת מותר בכולן אפילו כו'<sup data-n=\"e30\">*</sup>, ומזה משמע לכאורה דס\"ל דבשנה זו עקרוהו לגמרי מט' באב וקבעוהו ליו\"ד כהרשב\"א הנ\"ל. וא\"כ שוב אין להוכיח (לכאורה) מדין הנ\"ל, דרק בת\"ב נדחה אין בעל הברית משלים, דהוי בגדר השלמה. וכבר האריכו בספרים בהשקו\"ט בזה — ראה הנסמן בהערה 11. ובכל אופן, הביאור בפנים הוא להדיעות דס\"ל דאנן קיי\"ל להלכה דהוי בגדר תשלומין."],["1274","17","ראה בצפע\"נ שבהערה 11 ובצפע\"נ הל' תענית פ\"א ה\"ט. ועוד."],["1275","18","ובצפע\"נ שם מבאר: וזה נ\"מ ג\"כ בין קבלה אז הוי היום יום תענית ובין בלא קבלה אז הוי רק גדר איסור אכילה."],["1276","*18","את\"ל שלדעת רבי דברים שבצנעה נוהגים בת\"ב שחל בשבת. ואכ\"מ."],["1277","19","ראה שו\"ע אדה\"ז ריש הל' שבת. וש\"נ."],["1278","20","שו\"ת הרשב\"א ח\"א סי' תריד — לדעת הרמב\"ם הל' שבועות פ\"א ה\"ו (הובא לקמן בפנים). וראה שו\"ת הצ\"צ או\"ח סל\"ו."],["1279","21","או\"ח סי' רמב קו\"א סק\"א. ועד\"ז בפרמ\"ג או\"ח (א\"א) סי' רפח סק\"ז."],["1280","22","בשלח טז, כה."],["e30","*","ובשו\"ת כתב סופר שם, שגם כוונת הרמ\"א שם \"ויש אוסרין\" הוא לא מדינא, אלא מכח מנהגא שנתקבל בזה. ע\"ש בארוכה."]]],[1301430217,"התענית ענינו הוא (בלשון הכתוב<sup data-n=\"1281\">23</sup>) \"יום רצון לה'\". ואף שזה נאמר (בעיקר) בתענית שהוא לתשובה וכפרה<sup data-n=\"1282\">24</sup>, משא\"כ ד' הצומות, ובפרט ת\"ב, ה\"ה בגדר אבי­לות<sup data-n=\"1283\">25</sup> על הצרות שאירעו בזמנים אלו — הרי כתב הרמב\"ם<sup data-n=\"1284\">26</sup> שגם צומות אלו הם \"כדי לעורר הלבבות לפתוח דרכי התשובה ויהי' זה זכרון למעשינו הרעים ומעשה אבותינו שהי' כמעשינו עתה עד שגרם להם ולנו אותן הצרות, שבזכרון דברים אלו נשוב להיטיב שנאמר<sup data-n=\"1285\">27</sup> ו­התודו את עונם ואת עון אבותם וגו'\", דמזה מוכח שיש בתעניות אלו שני ה­ענינים<sup data-n=\"1286\">28</sup>.\nוהיינו שהיותו \"יום רצון\" מתגלה על ידי הצום והנהגות התענית שביום זה, וכדאיתא בגמרא<sup data-n=\"1287\">29</sup> \"שיהא חלבי ודמי שנתמעט כאילו הקרבתיו לפניך על גבי המזבח ותרצני\"<sup data-n=\"1288\">30</sup>.\n[ובזה יש לבאר מש\"נ בזכרי'<sup data-n=\"1289\">31</sup> והובא ברמב\"ם<sup data-n=\"1290\">32</sup> להלכה, שלעתיד (לא רק ש­יבטלו כל הצומות, אלא עוד זאת, ש)­ייהפכו (הצומות) לימים טובים וימי ששון ושמחה.\nדלפי פשוטו צ\"ע: ביטול הצומות ל­עת\"ל מובן, דכיון שהצומות הם לזכר הצרות שאירעו לאבותינו, לכן, בהבטל זכרון הצרות (על ידי הגאולה) בטלים בדרך ממילא הצומות — אבל מדוע יהפכו ימים אלה לששון ולשמחה<sup data-n=\"1291\">33</sup>? ד­לכאורה, לשמחה מה זו עושה?\nאבל ע\"פ הנ\"ל מובן, כי עיקר ה­תענית אינו העינוי שבו, כ\"א זה שהוא \"יום רצון לה'\"<sup data-n=\"1292\">34</sup>, אלא שבזמן הגלות, כשעדיין לא בטלו חטאינו (שגרמו ל­\"גלינו מארצנו\"), הרי הדרך להרגיש ולנצל מעלת היום היא על ידי עינוי הגוף, שזה מעורר את האדם לתשובה וכו'; משא\"כ לעתיד לבא, כאשר \"את רוח הטומאה אעביר מן הארץ\"<sup data-n=\"1293\">35</sup>, אין מקום לעינוי (הגוף), אלא להוספה בעבודת ה' ועבודה זו ה\"ה מתוך שמחה וטוב לבב, ולכן יהיו ימי רצון אלה ימי שמחה, שיהפכו לימים טובים]<sup data-n=\"1294\">36</sup>.",[["1281","23","ישעי' נח, ה."],["1282","24","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310073\" data-slug=\"tanya\" data-id=\"3401310073\">תניא</a> אגרת התשובה פ\"ב."],["1283","25","ראה זכרי' ז, ג ואילך. ירושלמי ברכות פ\"ב ה\"ז. ובתויו\"ט תענית פ\"ד מ\"א ד\"ה במנחה שלדעת הרמב\"ם \"ד' צומות לא הוקבעו אלא לאבל\". וראה רא\"ש תענית סל\"ב. ועוד."],["1284","26","הל' תעניות רפ\"ה."],["1285","27","בחוקותי כו, מ."],["1286","28","וראה שו\"ת חתם סופר או\"ח סי' רח (ד\"ה מ\"מ וקראת), שלהרמב\"ם \"נקבעו על התשובה\" (ולא כמו \"שהיינו חושבים שהתעניתים הללו אינם על דרך התשובה אלא ע\"ד האבל\")."],["1287","29","ברכות יז, א."],["1288","30","וראה אגה\"ת שם."],["1289","31","ח, יט."],["1290","32","סוף הל' תעניות. וראה טור או\"ח סו\"ס תקפ."],["1291","33","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830010\" data-slug=\"or-hatorah-hb\" data-id=\"8158830010\">אוה\"ת מסעי ס\"ע א'שפד</a> ואילך."],["1292","34","ועפ\"ז מובן ג\"כ בפשטות הא דאי' בגמ' (ר\"ה יח, ריש ע\"ב) בפי' הכתוב (זכרי' שם) \"צום הרביעי וצום החמישי גו' יהי' גו' לששון ולשמחה קרי להו צום וקרי להו ששון ושמחה בזמן שיש שלום יהיו לששון ולשמחה אין שלום צום כו'\", דאיך קורא לאותו יום עצמו בשני שמות הפכיים, ואיך נהפך יום זה מההיפך אל ההיפך? אלא כי עצם תוכן היום הוא יום רצון, אלא שפעולתו וגילויו הוא בהתאם להזמן ומעשה האדם שבזמנים אלו (כבפנים), דבזמן שיש שלום ששון ושמחה אין שלום כו'. ע\"ש בגמ'. וראה צדה לדרך (לר\"מ בר\"א בן זרח) מאמר חמישי כלל ראשון פ\"א."],["1293","35","זכרי' יג, ב."],["1294","36","וי\"ל שזה מוכח מזה גופא שלעתיד יהפכו ויהיו לששון ולשמחה, שזהו אמיתית תוכן ענין הצומות, שהרי לעת\"ל, כל המצות תהיינה על מילואן ושלימותן (ראה רמב\"ם הל' מלכים רפי\"א), \"כמצות רצונך\". ועפ\"ז יומתק גם זה שד' הצומות ה\"מפורשים בקבלה\", הביאם הרמב\"ם (הל' תעניות פ\"ה ה\"ד) מהכתוב בזכרי' \"צום הרביעי גו'\" — שאינם מפורשים בו בתור יום צום כשלעצמם, אלא רק ש\"צום הרביעי וגו' יהי'. . לששון גו'\", היינו שהפסוק בא לומר (לא עצם הצום, כ\"א זה ש)הצומות יהפכו לששון ולשמחה כו'."]]],[1301430218,"ועפ\"ז מובן, דכשחל ת\"ב או א' משאר ד' הצומות ביום השבת, דאין עצב בה<sup data-n=\"1295\">37</sup>, הרי זה שאי אפשר להתענות בו אינו מבטל הענין שיום זה הוא \"יום רצון\", ואדרבה, שהרי שבת מצ\"ע הוא ג\"כ יום ועת רצון, חמדת ימים אותו קראת<sup data-n=\"1296\">38</sup>.\nכלומר: הנשבע שיתענה בשבתות וב­ימים טובים ה\"ז שבועת שוא<sup data-n=\"1297\">39</sup>, כי בימים אלו אסור להתענות והוא נשבע לבטל את המצוה — כי המדובר הוא בפעולת הגברא שיתענה; אבל ימים שמלכתחילה נקבעו ע\"פ תורה לימי תענית, צום הרביעי וצום החמישי וכו', כאשר הם חלים בשבת — הרי אף שהגברא אי אפשר שיתענה ביום זה, מ\"מ החפצא ד­היום (תענית), שהוא יום רצון לה'<sup data-n=\"1298\">40</sup>, במקומו הוא.\nוזהו דס\"ל לרבנן, שגם כשחל יום ה­צום בשבת, ישנם ב' הענינים, יום תענית בתור יום רצון, שהוא ביום השבת, ו­מעשה האדם שביום הצום שנדחה ליום א'.\nה. ויש לבאר זה בעומק יותר, ע\"פ המבואר בכ\"מ<sup data-n=\"1299\">41</sup> בנוגע לתענית דיום ה­כפורים (מ\"ע מה\"ת — וי\"ל שהוא אבוהון דכולהו תעניות) שענינו — \"לחיותם ב­רעב\"<sup data-n=\"1300\">42</sup>, והיינו שמה\"רעב\" דיוהכ\"פ גופא נמשכת חיות להנשמה (ועד \"שהחיים שלהם הוא מבחי' הרעב גופא מה שהם רעבים וצמאים אליו ית'\"), וזה מחי' גם את הגוף כפשוטו.\nוהיינו דהחיות הנמשכת להאדם ביום התענית ע\"י הרעב, היא חיות נעלית יותר מהחיות שעל ידי אכילה ושתי', כי כל מהותה הוא חיות דקדושה (שהרי אין בו אכילה ושתי' וכו', והאדם עסוק רק בעניני קדושה — ובזה הוא חיותו ביום זה)<sup data-n=\"1301\">43</sup>; וי\"ל דמיום הכפורים נמשך הענין ד\"לחיותם ברעב\" (חיות להנשמה מהרעב גופא) גם לשאר הצומות (שמדברי קבלה).\nוהנה גם בשבת האכילה והשתי' אינה דומה לאכילה ושתי' דימות החול, שע\"ד הרגיל והרוב — מתענג האדם מאכו\"ש גשמיים והתענוג שלו הוא תענוג דחול, משא\"כ אכילת שבת, שמצוה לענגו, הרי האכילה והתענוג הם קדושה ומצוה<sup data-n=\"1302\">44</sup>.",[["1295","37","ראה תוס' סד\"ה מ\"ד (מו\"ק כג, ב)."],["1296","38","נוסח ברכת העמידה דש\"ק."],["1297","39","רמב\"ם שבהערה 20."],["1298","40","באגה\"ת שם \"ודרך כלל סוד התענית היא סגולה נפלאה להתגלות רצון העליון ב\"ה כמו הקרבן שנאמר בו ריח ניחוח לה', וכמ\"ש בישעי' הלזה תקרא צום ויום רצון לה' מכלל דהצום הנרצה הוא יום רצון\", ומשמע (קצת) דהיום רצון נעשה ע\"י פעולת האדם — צום הנרצה. אבל י\"ל שזהו רק בתעניות של יחיד לתשובה וכפרה (המדובר ב­אגה\"ת שם), או תעניות שגוזרים על הצבור כדי לבטל גזירה וכיו\"ב, משא\"כ ד' הצומות שהימים עצמם נקבעו ע\"פ תורה, \"מפורשים בקבלה\", הם בעצם \"יום רצון לה'\"."],["1299","41","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381186\" data-slug=\"likkutei-torah\" data-id=\"4001381186\">לקו\"ת שה\"ש</a> סד\"ה הנך יפה (יד, ב). ועוד."],["1300","42","תהלים לג, יט."],["1301","43","ולהעיר שגם בפשטות, חיות הגוף בכלל היא מדצ\"ח, משא\"כ ביום התענית שהחיות דיום זה בא מחיות שכבר נתעלה לדרגת מדבר (ובבנ\"י — שאמיתית חיותו היא מנפשו האלקית — הרי היא חיות קדושה של הנשמה). ועיין לקו\"ת יוהכ\"פ ע, ב."],["1302","44","ראה גם תו\"א ר\"פ ח\"ש. סידור עם דא\"ח סדר סעודת שבת (רג, א ואילך). <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670207\" data-slug=\"torat-chaim\" data-id=\"2300670207\">תו\"ח לך (צו, א</a>­ג). שם ויקהל (תרלא, א ואילך). דרך מצותיך צ, א­ב. סה\"מ תרס\"ג ע' ס ואילך. המשך תרס\"ו (ע' קנד. שם ע' רמב). ובכ\"מ."]]]]});
